  ('hsk1-13-2', 1, 74, '看', 'Грамматика: смотреть, слушать, видеть', 'Gramatyka: patrzeć, słuchać, widzieć', 'Grammar: Watch, Listen, See', 13, 'Глава 13: Телефон и экран', 'Rozdział 13: Telefon i ekran', 'Chapter 13: Phone and Screen'),
  ('hsk1-13-3', 1, 75, '写', 'Читать и писать иероглифы', 'Czytać i pisać znaki', 'Reading and Writing Characters', 13, 'Глава 13: Телефон и экран', 'Rozdział 13: Telefon i ekran', 'Chapter 13: Phone and Screen'),
  ('hsk1-13-4', 1, 76, '读', 'Звонок после занятий', 'Telefon po zajęciach', 'A Call after Class', 13, 'Глава 13: Телефон и экран', 'Rozdział 13: Telefon i ekran', 'Chapter 13: Phone and Screen'),
  ('hsk1-13-5', 1, 77, '创', 'Мой вечер: кино и телефон', 'Mój wieczór: kino i telefon', 'My Evening: Movie and Phone', 13, 'Глава 13: Телефон и экран', 'Rozdział 13: Telefon i ekran', 'Chapter 13: Phone and Screen'),
  ('hsk1-13-6', 1, 78, '考', 'Итоговый экзамен главы', 'Egzamin końcowy rozdziału', 'Chapter Final Exam', 13, 'Глава 13: Телефон и экран', 'Rozdział 13: Telefon i ekran', 'Chapter 13: Phone and Screen'),
  ('hsk1-14-1', 1, 79, '书', 'Книги, стол и стул', 'Książki, stół i krzesło', 'Books, Table and Chair', 14, 'Глава 14: Дом и вещи', 'Rozdział 14: Dom i rzeczy', 'Chapter 14: Home and Things'),
  ('hsk1-14-2', 1, 80, '住', 'Грамматика: жить, делать и «на столе есть»', 'Gramatyka: mieszkać, robić i „na stole jest”', 'Grammar: Live, Do and “There Is on the Table”', 14, 'Глава 14: Дом и вещи', 'Rozdział 14: Dom i rzeczy', 'Chapter 14: Home and Things'),
  ('hsk1-14-3', 1, 81, '猫', 'Одежда, собака и кошка', 'Ubranie, pies i kot', 'Clothes, Dog and Cat', 14, 'Глава 14: Дом и вещи', 'Rozdział 14: Dom i rzeczy', 'Chapter 14: Home and Things'),
  ('hsk1-14-4', 1, 82, '读', 'Комната Ли Мина', 'Pokój Li Minga', 'Li Ming''s Room', 14, 'Глава 14: Дом и вещи', 'Rozdział 14: Dom i rzeczy', 'Chapter 14: Home and Things'),
  ('hsk1-14-5', 1, 83, '创', 'Моя комната', 'Mój pokój', 'My Room', 14, 'Глава 14: Дом и вещи', 'Rozdział 14: Dom i rzeczy', 'Chapter 14: Home and Things'),
  ('hsk1-14-6', 1, 84, '考', 'Итоговый экзамен главы', 'Egzamin końcowy rozdziału', 'Chapter Final Exam', 14, 'Глава 14: Дом и вещи', 'Rozdział 14: Dom i rzeczy', 'Chapter 14: Home and Things'),
  ('hsk1-15-1', 1, 85, '医', 'Врач и больница', 'Lekarz i szpital', 'Doctor and Hospital', 15, 'Глава 15: Здоровье и большое повторение', 'Rozdział 15: Zdrowie i wielka powtórka', 'Chapter 15: Health and the Big Review'),
  ('hsk1-15-2', 1, 86, '谁', 'Грамматика: кто и «эти»', 'Gramatyka: kto i „te”', 'Grammar: Who and “These”', 15, 'Глава 15: Здоровье и большое повторение', 'Rozdział 15: Zdrowie i wielka powtórka', 'Chapter 15: Health and the Big Review'),
  ('hsk1-15-3', 1, 87, '听', 'Аудиопрактикум: тоны и сандхи', 'Praktyka audio: tony i sandhi', 'Audio Practice: Tones and Sandhi', 15, 'Глава 15: Здоровье и большое повторение', 'Rozdział 15: Zdrowie i wielka powtórka', 'Chapter 15: Health and the Big Review'),
  ('hsk1-15-4', 1, 88, '读', 'Папа Ли Мина — врач', 'Tata Li Minga jest lekarzem', 'Li Ming''s Dad Is a Doctor', 15, 'Глава 15: Здоровье и большое повторение', 'Rozdział 15: Zdrowie i wielka powtórka', 'Chapter 15: Health and the Big Review'),
