  ('hsk1-03-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🇨🇳","options":["学校","北京","中国"],"correct":2},{"emoji":"🏫","options":["学校","汉语","同学"],"correct":0},{"emoji":"🎓","options":["老师","学习","学生"],"correct":2},{"emoji":"📚","options":["会","学习","说"],"correct":1}]}'),
