  ('hsk1-03-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Я китаец»?","options":["中国我是。","我是中国人。","我中国是人。"],"correct":1},{"q":"Как спросить «Ты умеешь говорить по-китайски?»","options":["你说会汉语吗？","汉语你会说吗？","你会说汉语吗？"],"correct":2},{"q":"Как читается 不 в 不会?","options":["bǔ","bú","bù"],"correct":1},{"q":"说 — это «учиться».","tf":false},{"q":"Что значит 学校?","options":["школа","ученик","учитель"],"correct":0},{"q":"Как сказать «Он мой одноклассник»?","options":["他是我同学。","他学校我。","他是学习。"],"correct":0},{"q":"北京 значит «северная столица».","tf":true},{"q":"Как читается 学生?","options":["xuěsheng","xuésheng","xuéshēng"],"correct":1},{"q":"Как ответить на 你会说汉语吗？ «Нет»?","options":["不会。","不说是。","不是。"],"correct":0},{"q":"Какой иероглиф означает «человек»?","options":["国","中","人"],"correct":2}]}'),
