  ('hsk1-04-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Нас шесть человек»?","options":["我们六个人。","我们六岁。","六我们人。"],"correct":0},{"q":"Как записать число 78?","options":["八十七","七八","七十八"],"correct":2},{"q":"Для возраста говорим число + 岁.","tf":true},{"q":"Как спросить возраст друга?","options":["你几个？","你什么岁？","你几岁？"],"correct":2}]}'),
