  ('hsk1-04-6', 3, 'game', '{"type":"emoji","big":true,"title":"Цифра → иероглиф","items":[{"emoji":"1️⃣","options":["二","一","七"],"correct":1},{"emoji":"4️⃣","options":["八","四","九"],"correct":1},{"emoji":"6️⃣","options":["五","七","六"],"correct":2},{"emoji":"9️⃣","options":["十","八","九"],"correct":2},{"emoji":"🔟","options":["一","九","十"],"correct":2}]}'),
