  ('hsk1-04-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как будет 25?","options":["二五十","五十二","二十五"],"correct":2},{"q":"Как будет 13?","options":["一三","十三","三十"],"correct":1},{"q":"Как читается 一个?","options":["yì gè","yī gè","yí gè"],"correct":2},{"q":"Для возраста нужно слово 岁.","tf":true},{"q":"Как спросить «Сколько вас человек?»","options":["你们几吗？","你们几岁？","你们几个人？"],"correct":2},{"q":"Как сказать «Мне двадцать лет»?","options":["我岁二十。","我二十个。","我二十岁。"],"correct":2},{"q":"Число 四 считается счастливым.","tf":false},{"q":"Какое число созвучно «разбогатеть»?","options":["六","九","八"],"correct":2},{"q":"Как будет 99?","options":["九九","十九九","九十九"],"correct":2},{"q":"Как будет «шесть человек»?","options":["六岁人","个六人","六个人"],"correct":2}]}'),
  ('hsk1-04-6', 6, 'game', '{"type":"build","title":"Соберите фразу и число","items":[{"answer":["我","十","八","岁"],"hint":"«Мне восемнадцать лет.»"},{"answer":["你","几","岁"],"hint":"«Сколько тебе лет?»"},{"answer":["我们","五","个","人"],"hint":"«Нас пять человек.»"},{"answer":["四","十","三"],"hint":"43"}]}'),
  ('hsk1-04-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我二十个。","context":"Возраст «двадцать лет»","options":["我二十岁。","我岁二十。","我二个十岁。"],"correct":0},{"buggyText":"三人。","context":"«Три человека»","options":["三几人。","三岁人。","三个人。"],"correct":2},{"buggyText":"我十岁二。","context":"«Мне двенадцать»","options":["我十二岁。","我二十岁。","我十二个。"],"correct":0}]}'),
  ('hsk1-04-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Ли Мин","text":"你几岁？","pinyin":"Nǐ jǐ suì?","translation":"Сколько тебе лет?","options":["我是十九。","我九个。","我十九岁。"],"correct":2},{"speaker":"Ли Мин","text":"你们几个人？","pinyin":"Nǐmen jǐ gè rén?","translation":"Сколько вас человек?","options":["我们四岁。","我们四个人。","我四个。"],"correct":1}]}'),
  ('hsk1-04-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"二","pinyin":"èr","m":"два","hint":"две горизонтальные черты"},{"hanzi":"十","pinyin":"shí","m":"десять","hint":"крест"},{"hanzi":"五","pinyin":"wǔ","m":"пять","hint":"горизонталь, вертикаль, горизонталь, вертикаль с изломом"}]}'),
  ('hsk1-04-6', 10, 'recall', '{"words":[{"hanzi":"一","pinyin":"yī","m":"один"},{"hanzi":"二","pinyin":"èr","m":"два"},{"hanzi":"三","pinyin":"sān","m":"три"},{"hanzi":"四","pinyin":"sì","m":"четыре"},{"hanzi":"五","pinyin":"wǔ","m":"пять"},{"hanzi":"六","pinyin":"liù","m":"шесть"},{"hanzi":"七","pinyin":"qī","m":"семь"},{"hanzi":"八","pinyin":"bā","m":"восемь"},{"hanzi":"九","pinyin":"jiǔ","m":"девять"},{"hanzi":"十","pinyin":"shí","m":"десять"},{"hanzi":"个","pinyin":"gè","m":"счётное слово"},{"hanzi":"几","pinyin":"jǐ","m":"сколько"},{"hanzi":"岁","pinyin":"suì","m":"год жизни"}],"tf":[{"zh":"三人。","py":"sān rén.","m":"Три человека.","ok":false,"explain":"Пропущено 个: 三个人."},{"zh":"我二十岁。","py":"wǒ èrshí suì.","m":"Мне двадцать лет.","ok":true}],"sentences":[{"zh":"我十八岁。","tokens":["我","十","八","岁"],"m":"Мне восемнадцать лет."},{"zh":"你们几个人？","tokens":["你们","几","个","人"],"m":"Сколько вас человек?"},{"zh":"我们三个人。","tokens":["我们","三","个","人"],"m":"Нас трое."}]}'),
  ('hsk1-05-1', 1, 'fact', '{"emoji":"👨‍👩‍👧","title":"Повторяющийся слог — язык малышей","text":"Слова 爸爸 bàba и 妈妈 māma удваивают слог, как «папа» и «мама» у нас. А в 女儿 «дочь» и 儿子 «сын» вы узнаете знакомые части: 女 «женщина» и 子 «ребёнок» уже встречались в знаке 好. Дочь — это «женский ребёнок», сын — «ребёнок-儿»."}'),
  ('hsk1-05-1', 2, 'words', '{"title":"Четыре члена семьи","items":[{"hanzi":"爸爸","pinyin":"bàba","m":"папа","emoji":"👨","ex":{"zh":"我爸爸","py":"wǒ bàba","m":"мой папа"}},{"hanzi":"妈妈","pinyin":"māma","m":"мама","emoji":"👩","ex":{"zh":"我妈妈","py":"wǒ māma","m":"моя мама"}},{"hanzi":"儿子","pinyin":"érzi","m":"сын","emoji":"👦","ex":{"zh":"他是我儿子。","py":"Tā shì wǒ érzi.","m":"Он мой сын."}},{"hanzi":"女儿","pinyin":"nǚ''ér","m":"дочь","emoji":"👧","ex":{"zh":"她是我女儿。","py":"Tā shì wǒ nǚ''ér.","m":"Она моя дочь."}}]}'),
  ('hsk1-05-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"👨","options":["儿子","妈妈","爸爸"],"correct":2},{"emoji":"👩","options":["妈妈","爸爸","女儿"],"correct":0},{"emoji":"👦","options":["他","女儿","儿子"],"correct":2},{"emoji":"👧","options":["女儿","儿子","她"],"correct":0}]}'),
  ('hsk1-05-1', 4, 'theory', '{"title":"Как читаются слова семьи","blocks":[{"t":"table","head":["Слово","Тоны","Фишка"],"rows":[["爸爸 bàba","4 + безударный","второй слог лёгкий"],["妈妈 māma","1 + безударный","второй слог лёгкий"],["儿子 érzi","2 + безударный","子 в конце лёгкий"],["女儿 nǚ''ér","3 + 2","апостроф разделяет слоги"]]},{"t":"tip","text":"В 女儿 вы видите 女 и 儿: «женщина» плюс «ребёнок»."},{"t":"ex","zh":"我爸爸和我妈妈。","py":"Wǒ bàba hé wǒ māma.","m":"Мой папа и моя мама.","say":"我爸爸和我妈妈"}]}'),
  ('hsk1-05-1', 5, 'quiz', '{"title":"Мини-тест: семья","qs":[{"q":"Как сказать «мама»?","options":["女儿","妈妈","爸爸"],"correct":1},{"q":"女儿 — это «сын».","tf":false,"explain":"女儿 — дочь."},{"q":"Какой ключ у 妈?","options":["亻","女","口"],"correct":1,"explain":"女 — «женщина»."}]}'),
  ('hsk1-05-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["爸爸","папа"],["妈妈","мама"],["儿子","сын"],["女儿","дочь"],["我妈妈","моя мама"]]}'),
  ('hsk1-05-1', 7, 'game', '{"type":"listen","title":"Слушаем семью","items":[{"say":"爸爸","options":["bāba","bǎba","bàba"],"correct":2},{"say":"妈妈","options":["mǎma","māma","mámá"],"correct":1},{"say":"儿子","options":["ěrzi","érzi","èrzi"],"correct":1},{"say":"女儿","options":["nǚ''ér","nǚ''èr","nǔ''ér"],"correct":0},{"say":"我妈妈","options":["wǒ bàba","wǒ māma"],"correct":1}]}'),
  ('hsk1-05-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","爸爸"],"hint":"«Мой папа.»"},{"answer":["他","是","我","儿子"],"hint":"«Он мой сын.»"},{"answer":["她","是","我","女儿"],"hint":"«Она моя дочь.»"}]}'),
  ('hsk1-05-1', 9, 'write', '{"title":"Пропись: родители и дети","items":[{"hanzi":"爸","pinyin":"bà","m":"папа","hint":"сверху 父, снизу 巴"},{"hanzi":"妈","pinyin":"mā","m":"мама","hint":"слева 女, справа 马"},{"hanzi":"儿","pinyin":"ér","m":"ребёнок, сын","hint":"две черты: короткая и длинная ломаная"}]}'),
  ('hsk1-05-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 儿子?","options":["дочь","сын","папа","мама"],"correct":1},{"q":"Как читается 妈妈?","options":["mámá","māma","mǎma"],"correct":1},{"q":"爸爸 произносится bàba.","tf":true},{"q":"Что значит 女儿?","options":["дочь","сын","мама"],"correct":0},{"q":"Какая пара «мама и папа»?","options":["妈妈爸爸吗","爸爸是妈妈","妈妈和爸爸"],"correct":2}]}'),
  ('hsk1-05-2', 1, 'fact', '{"emoji":"🔑","title":"Один глагол вместо «у меня есть» и «в семье есть»","text":"По-русски мы говорим «у меня есть». В китайском достаточно 有 «иметь»: 我有儿子 — «я имею сына». Отрицание особое: не 不有, а 没有. А для принадлежности служит маленькое 的: 我的 «мой», 老师的 «учителя»."}'),
  ('hsk1-05-2', 2, 'words', '{"title":"Три слова-помощника","items":[{"hanzi":"有","pinyin":"yǒu","m":"иметь, есть","emoji":"🤲","ex":{"zh":"我有儿子。","py":"Wǒ yǒu érzi.","m":"У меня есть сын."}},{"hanzi":"没有","pinyin":"méiyǒu","m":"не иметь, нет","emoji":"🚫","ex":{"zh":"我没有女儿。","py":"Wǒ méiyǒu nǚ''ér.","m":"У меня нет дочери."}},{"hanzi":"的","pinyin":"de","m":"частица принадлежности","emoji":"🔗","ex":{"zh":"我的朋友","py":"wǒ de péngyou","m":"мой друг"}}]}'),
  ('hsk1-05-2', 3, 'theory', '{"title":"有 и 没有","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["我有女儿。","Wǒ yǒu nǚ''ér.","У меня есть дочь."],["我没有儿子。","Wǒ méiyǒu érzi.","У меня нет сына."],["你有儿子吗？","Nǐ yǒu érzi ma?","У тебя есть сын?"]]},{"t":"p","text":"Для отрицания 有 всегда говорят 没有, никогда 不有. Вопрос задаётся частицей 吗, ответ: 有 или 没有."},{"t":"tip","text":"我有 звучит как wó yǒu: два третьих тона подряд, первый меняется."}]}'),
  ('hsk1-05-2', 4, 'game', '{"type":"build","title":"Соберите фразу с 有","items":[{"answer":["我","有","女儿"],"hint":"«У меня есть дочь.»"},{"answer":["我","没有","儿子"],"hint":"«У меня нет сына.»"},{"answer":["你","有","儿子","吗"],"hint":"«У тебя есть сын?»"}]}'),
  ('hsk1-05-2', 5, 'quiz', '{"title":"Мини-тест: 有","qs":[{"q":"Как сказать «У меня нет дочери»?","options":["我有不女儿。","我不有女儿。","我没有女儿。"],"correct":2},{"q":"Для отрицания 有 используют 不.","tf":false,"explain":"Нужно 没有."}]}'),
  ('hsk1-05-2', 6, 'theory', '{"title":"Принадлежность: 的","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我的朋友","мой друг"],["老师的名字","имя учителя"],["我爸爸","мой папа (的 не нужно)"],["我家","мой дом (的 не нужно)"]]},{"t":"p","text":"Между «мой» и родственником или домом 的 обычно опускают: 我爸爸, 我妈妈, 我家. Для остальных предметов 的 ставят."}]}'),
  ('hsk1-05-2', 7, 'game', '{"type":"listen","title":"Аудио: 有, 没有, 的","items":[{"say":"我有女儿","options":["wǒ yǒu nǚ''ér","wǒ méiyǒu nǚ''ér"],"correct":0},{"say":"我没有儿子","options":["wǒ yǒu érzi","wǒ méiyǒu érzi"],"correct":1},{"say":"我的朋友","options":["wǒ shì péngyou","wǒ de péngyou"],"correct":1},{"say":"你有儿子吗","options":["nǐ yǒu érzi ma","nǐ méiyǒu érzi"],"correct":0}]}'),
  ('hsk1-05-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["有","иметь, есть"],["没有","не иметь, нет"],["的","частица принадлежности"],["我的","мой"],["我爸爸","мой папа"]]}'),
  ('hsk1-05-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: 有 и 的","cases":[{"buggyText":"我不有儿子。","context":"Сказать «У меня нет сына»","options":["我有不儿子。","我儿子不有。","我没有儿子。"],"correct":2},{"buggyText":"我的爸爸和我的妈妈。","context":"Сказать «Мои папа и мама» естественнее","options":["我爸爸的和妈妈。","我和爸爸妈妈的。","我爸爸和我妈妈。"],"correct":2,"explain":"Для близких 的 опускают."}]}'),
  ('hsk1-05-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Какое слово значит «иметь»?","options":["的","有","没"],"correct":1},{"q":"Как читается 没有?","options":["mèiyǒu","méiyóu","méiyǒu"],"correct":2},{"q":"我的朋友 — «мой друг».","tf":true},{"q":"Как спросить «У тебя есть дочь?»","options":["你不有女儿吗？","你女儿有吗？","你有女儿吗？"],"correct":2},{"q":"Что значит 我家?","options":["мой дом, моя семья","я дома","я учитель"],"correct":0}]}'),
  ('hsk1-05-3', 1, 'fact', '{"emoji":"🏠","title":"Дом со свиньёй","text":"В знаке 家 «дом» крыша 宀 прикрывает 豕 «свинью». В старину свинья была признаком достатка, а жили люди в одном доме с животными. Поэтому 家 значит и «дом», и «семья». А слово 朋友 «друг» состоит из двух 月: две луны рядом, как два друга."}'),
  ('hsk1-05-3', 2, 'words', '{"title":"Дом, друг и «и»","items":[{"hanzi":"家","pinyin":"jiā","m":"дом, семья","emoji":"🏠","ex":{"zh":"我家有三个人。","py":"Wǒ jiā yǒu sān gè rén.","m":"В моей семье три человека."}},{"hanzi":"朋友","pinyin":"péngyou","m":"друг","emoji":"🤝","ex":{"zh":"他是我朋友。","py":"Tā shì wǒ péngyou.","m":"Он мой друг."}},{"hanzi":"和","pinyin":"hé","m":"и, с","emoji":"➕","ex":{"zh":"爸爸和妈妈","py":"bàba hé māma","m":"папа и мама"}}]}'),
  ('hsk1-05-3', 3, 'game', '{"type":"listen","title":"Слушаем: дом и друзья","items":[{"say":"家","options":["jiá","jiǎ","jiā"],"correct":2},{"say":"朋友","options":["péngyou","pēngyou","péngyǒu"],"correct":0},{"say":"和","options":["hě","hé","hè"],"correct":1},{"say":"爸爸和妈妈","options":["bàba hé māma","bàba hé mǎma"],"correct":0},{"say":"我家有四个人","options":["wǒ jiā yǒu sān gè rén","wǒ jiā yǒu sì gè rén"],"correct":1}]}'),
  ('hsk1-05-3', 4, 'game', '{"type":"tone_visualizer","initialTone":2,"title":"Тренажёр голоса: повторите «péng» (2 тон)"}'),
  ('hsk1-05-3', 5, 'theory', '{"title":"Как перечислять: 和","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["爸爸和妈妈","папа и мама"],["我和你","я и ты"],["我和朋友","я и друг"]]},{"t":"p","text":"和 соединяет только существительные и местоимения. Не используйте его, чтобы соединить два глагола."},{"t":"tip","text":"У 和 здесь тон второй: hé."}]}'),
  ('hsk1-05-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🏠","options":["朋友","和","家"],"correct":2},{"emoji":"🤝","options":["家","和","朋友"],"correct":2},{"emoji":"➕","options":["家","有","和"],"correct":2}]}'),
  ('hsk1-05-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["家","дом, семья"],["朋友","друг"],["和","и, с"],["我家","моя семья"],["我朋友","мой друг"]]}'),
  ('hsk1-05-3', 8, 'game', '{"type":"chatsim","title":"WeChat: про семью","messages":[{"speaker":"Ли Мин","text":"你家有几个人？","pinyin":"Nǐ jiā yǒu jǐ gè rén?","translation":"Сколько человек в твоей семье?","options":["我家四岁。","我家有四个。","我家有四个人。"],"correct":2},{"speaker":"Ли Мин","text":"你有朋友吗？","pinyin":"Nǐ yǒu péngyou ma?","translation":"У тебя есть друзья?","options":["没有，我朋友。","有，我是朋友。","有，我有朋友。"],"correct":2},{"speaker":"Ли Мин","text":"你爸爸妈妈好吗？","pinyin":"Nǐ bàba māma hǎo ma?","translation":"Как твои родители?","options":["我爸爸很大。","他们很好。","谢谢你的家。"],"correct":1,"explain":"他们 «они» — новое слово."}]}'),
  ('hsk1-05-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","家","有","三","个","人"],"hint":"«В моей семье три человека.»"},{"answer":["我","和","朋友"],"hint":"«Я и друг.»"},{"answer":["爸爸","和","妈妈"],"hint":"«Папа и мама.»"}]}'),
  ('hsk1-05-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 家?","options":["и","дом, семья","дочь","друг"],"correct":1},{"q":"Какое слово значит «и»?","options":["的","有","和"],"correct":2},{"q":"Из каких частей состоит 朋?","options":["女 + 子","две 月","亻 + 也"],"correct":1},{"q":"家 и «дом», и «семья».","tf":true},{"q":"Как сказать «Мой друг»?","options":["我朋友","我是朋友","朋友我"],"correct":0}]}'),
  ('hsk1-05-4', 1, 'fact', '{"emoji":"👨‍👩‍👧‍👦","title":"Семья по-китайски","text":"В китайской семье часто живут вместе родители, дети и бабушки с дедушками. Учитель Ван рассказывает студентке о своей семье."}'),
  ('hsk1-05-4', 2, 'text', '{"title":"Семья учителя Ван","lines":[{"zh":"安娜：王老师，您家有几个人？","py":"Ānnà: Wáng lǎoshī, nín jiā yǒu jǐ gè rén?","m":"Анна: Учитель Ван, сколько человек в Вашей семье?"},{"zh":"王老师：我家有四个人：爸爸、妈妈、我和女儿。","py":"Wáng lǎoshī: Wǒ jiā yǒu sì gè rén: bàba, māma, wǒ hé nǚ''ér.","m":"Учитель Ван: Нас четверо: папа, мама, я и дочь."},{"zh":"安娜：您有儿子吗？","py":"Ānnà: Nín yǒu érzi ma?","m":"Анна: У Вас есть сын?"},{"zh":"王老师：没有。我有一个女儿。","py":"Wáng lǎoshī: Méiyǒu. Wǒ yǒu yí gè nǚ''ér.","m":"Учитель Ван: Нет. У меня одна дочь."},{"zh":"安娜：您的女儿几岁？","py":"Ānnà: Nín de nǚ''ér jǐ suì?","m":"Анна: Сколько лет Вашей дочери?"},{"zh":"王老师：她七岁。","py":"Wáng lǎoshī: Tā qī suì.","m":"Учитель Ван: Ей семь лет."},{"zh":"安娜：很好！谢谢老师！","py":"Ānnà: Hěn hǎo! Xièxie lǎoshī!","m":"Анна: Прекрасно! Спасибо, учитель!"}],"qs":[{"q":"Сколько человек в семье учителя?","options":["четыре","семь","три"],"correct":0},{"q":"У учителя Ван есть сын.","tf":false,"explain":"Она отвечает 没有."},{"q":"Сколько лет дочери?","options":["17","4","7"],"correct":2},{"q":"Вставьте слово: 我有一个___。","options":["老师","女儿","名字"],"correct":1},{"q":"Анна говорит учителю 您.","tf":true},{"q":"Как Анна спрашивает, есть ли сын?","options":["您是儿子吗？","您的儿子几个？","您有儿子吗？"],"correct":2},{"q":"Кто живёт в семье кроме учителя и дочери?","options":["брат и сестра","дедушка","папа и мама"],"correct":2}]}'),
  ('hsk1-05-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["您家有几个人？","Сколько человек в Вашей семье?"],["我家有四个人","Нас четверо"],["我没有儿子","У меня нет сына"],["她七岁","Ей семь лет"],["您的女儿","Ваша дочь"]]}'),
  ('hsk1-05-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"您家有几个人","options":["nín jiā yǒu jǐ gè rén","nǐ jiā yǒu jǐ gè rén"],"correct":0},{"say":"我没有儿子","options":["wǒ yǒu érzi","wǒ méiyǒu érzi"],"correct":1},{"say":"她七岁","options":["tā bā suì","tā qī suì"],"correct":1},{"say":"您的女儿","options":["nín de nǚ''ér","nǐ de nǚ''ér"],"correct":0}]}'),
  ('hsk1-05-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: ошибки в разговоре","cases":[{"buggyText":"老师，你家有几个人？","context":"Вопрос учителю","options":["老师，您家有几个人？","老师，你们有几个人？","老师，您家几个？"],"correct":0},{"buggyText":"我有不儿子。","context":"«У меня нет сына»","options":["我儿子没有。","我没有儿子。","我不有儿子。"],"correct":1},{"buggyText":"我的家有四个人。","context":"Естественнее","options":["我家有四个人。","我有四个人家。","我家的有四个人。"],"correct":0,"explain":"Перед 家 «мой» 的 опускают."}]}'),
  ('hsk1-05-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «У меня одна дочь»?","options":["我是一个女儿。","我女儿有一。","我有一个女儿。"],"correct":2},{"q":"Как читается 您的?","options":["nín dì","nín de","nǐ de"],"correct":1},{"q":"Анна благодарит учителя.","tf":true}]}'),
  ('hsk1-05-5', 1, 'fact', '{"emoji":"🌳","title":"Нарисуйте семейное древо","text":"Сегодня вы составляете «карточки семьи»: кто есть кто, сколько кому лет, у кого что есть. Только слова из глав 1–5."}'),
  ('hsk1-05-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"家","correctRadicals":["宀","豕"],"title":"Пазл: соберите 家"}'),
  ('hsk1-05-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"妈","radicals":["女","马","亻"],"correctOrder":["女","马"],"explain":"Слева 女, справа 马."},{"targetHanzi":"好","radicals":["女","子","亻"],"correctOrder":["女","子"],"explain":"女 + 子 — «хорошо»."},{"targetHanzi":"朋","radicals":["月","月","日"],"correctOrder":["月","月"],"explain":"Две «луны» рядом."}]}'),
  ('hsk1-05-5', 4, 'game', '{"type":"build","title":"Мастерская карточек","items":[{"target":"(Карточка)","answer":["我","家","有","四","个","人"],"hint":"«В моей семье четыре человека.»"},{"target":"(Карточка)","answer":["我","有","一","个","朋友"],"hint":"«У меня один друг.»"},{"target":"(Карточка)","answer":["我","爸爸","四","十","岁"],"hint":"«Моему папе сорок лет.»"},{"target":"(Карточка)","answer":["我","妈妈","和","我","爸爸"],"hint":"«Мои мама и папа.»"}]}'),
  ('hsk1-05-5', 5, 'theory', '{"title":"Шаблон рассказа о семье","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Сколько человек","我家有…个人。"],["Кто","爸爸、妈妈、我…"],["Возраст","爸爸…岁。"],["Друг","我有一个朋友。"]]}]}'),
  ('hsk1-05-5', 6, 'game', '{"type":"chatsim","title":"WeChat: расскажите о семье","messages":[{"speaker":"Друг","text":"你家有几个人？","pinyin":"Nǐ jiā yǒu jǐ gè rén?","translation":"Сколько человек в твоей семье?","options":["我三岁。","我家有三个人。","我家三个。"],"correct":1},{"speaker":"Друг","text":"你有女儿吗？","pinyin":"Nǐ yǒu nǚ''ér ma?","translation":"У тебя есть дочь?","options":["没有。","不是。","不有。"],"correct":0},{"speaker":"Друг","text":"你的爸爸几岁？","pinyin":"Nǐ de bàba jǐ suì?","translation":"Сколько лет твоему папе?","options":["我爸爸五十岁。","爸爸我五十。","我爸爸五十个。"],"correct":0,"explain":"五十 — «пять десять»."}]}'),
  ('hsk1-05-5', 7, 'game', '{"type":"match","title":"Какой знак получится","pairs":[["女 + 马","妈"],["女 + 子","好"],["宀 + 豕","家"],["月 + 月","朋"]]}'),
  ('hsk1-05-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"家","pinyin":"jiā","m":"дом","hint":"сначала крыша 宀, потом внутри"},{"hanzi":"有","pinyin":"yǒu","m":"иметь","hint":"сверху откидная, потом 月"},{"hanzi":"友","pinyin":"yǒu","m":"друг","hint":"сверху 又 с чертой"}]}'),
  ('hsk1-05-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Какой знак состоит из 宀 и 豕?","options":["妈","朋","家"],"correct":2},{"q":"Как сказать «Мой папа и мама»?","options":["我爸爸妈妈有","我爸爸有妈妈","我爸爸和我妈妈"],"correct":2},{"q":"У меня нет сына — 我没有儿子.","tf":true}]}'),
  ('hsk1-05-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 5","text":"Семья, 有 и 没有, частица 的, союз 和 и счёт. Не набрали проходной балл — повторите уроки."}'),
  ('hsk1-05-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"爸爸","options":["bǎba","bàba","bāba"],"correct":1},{"say":"妈妈和爸爸","options":["māma hé bàba","māma hé bāba"],"correct":0},{"say":"我有女儿","options":["wǒ yǒu nǚ''ér","wǒ méiyǒu nǚ''ér"],"correct":0},{"say":"我没有儿子","options":["wǒ méiyǒu érzi","wǒ yǒu érzi"],"correct":0},{"say":"我家有三个人","options":["wǒ jiā yǒu sì gè rén","wǒ jiā yǒu sān gè rén"],"correct":1},{"say":"他是我朋友","options":["tā shì wǒ tóngxué","tā shì wǒ péngyou"],"correct":1}]}'),
  ('hsk1-05-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"👨","options":["朋友","儿子","爸爸"],"correct":2},{"emoji":"👧","options":["家","女儿","妈妈"],"correct":1},{"emoji":"🏠","options":["和","有","家"],"correct":2},{"emoji":"🤝","options":["儿子","朋友","爸爸"],"correct":1}]}'),
  ('hsk1-05-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["爸爸","папа"],["妈妈","мама"],["儿子","сын"],["女儿","дочь"],["有","иметь"],["没有","не иметь"],["的","частица принадлежности"],["家","дом, семья"],["朋友","друг"],["和","и"]]}'),
  ('hsk1-05-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «У меня нет дочери»?","options":["我不有女儿。","我有不女儿。","我没有女儿。"],"correct":2},{"q":"Как спросить «У тебя есть сын?»","options":["你有儿子吗？","你儿子有？","你有儿子什么？"],"correct":0},{"q":"Как сказать «мой друг»?","options":["朋友我","我吗朋友","我朋友"],"correct":2},{"q":"Перед 爸爸 в «мой папа» 的 обычно опускают.","tf":true},{"q":"Как читается 没有?","options":["méiyóu","mèiyǒu","méiyǒu"],"correct":2},{"q":"Что значит 我家?","options":["я студент","моя семья","я дома"],"correct":1},{"q":"和 соединяет глаголы.","tf":false},{"q":"Как сказать «Папа и мама»?","options":["爸爸有妈妈","爸爸和妈妈","爸爸的妈妈"],"correct":1},{"q":"Как сказать «Нас трое»?","options":["我家三岁。","我家有三个人。","我有三家。"],"correct":1},{"q":"Что значит 儿子?","options":["друг","сын","дочь"],"correct":1}]}'),
  ('hsk1-05-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","有","女儿"],"hint":"«У меня есть дочь.»"},{"answer":["我","没有","儿子"],"hint":"«У меня нет сына.»"},{"answer":["他","是","我","朋友"],"hint":"«Он мой друг.»"},{"answer":["爸爸","和","妈妈"],"hint":"«Папа и мама.»"}]}'),
  ('hsk1-05-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我不有儿子。","context":"«У меня нет сына»","options":["我没有儿子。","我儿子不有。","我有不儿子。"],"correct":0},{"buggyText":"我的爸爸。","context":"Естественнее","options":["我爸爸的。","爸爸我。","我爸爸。"],"correct":2},{"buggyText":"我家有四岁人。","context":"«В семье четыре человека»","options":["我家四有人。","我家有四人个。","我家有四个人。"],"correct":2}]}'),
  ('hsk1-05-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Ли Мин","text":"你家有几个人？","pinyin":"Nǐ jiā yǒu jǐ gè rén?","translation":"Сколько человек в твоей семье?","options":["我家三岁。","我有三个家。","我家有三个人。"],"correct":2},{"speaker":"Ли Мин","text":"你有女儿吗？","pinyin":"Nǐ yǒu nǚ''ér ma?","translation":"У тебя есть дочь?","options":["不是。","没有。","不有。"],"correct":1}]}'),
  ('hsk1-05-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"家","pinyin":"jiā","m":"дом","hint":"宀 + 豕"},{"hanzi":"妈","pinyin":"mā","m":"мама","hint":"女 + 马"},{"hanzi":"友","pinyin":"yǒu","m":"друг","hint":"верхняя часть 又"}]}'),
  ('hsk1-05-6', 10, 'recall', '{"words":[{"hanzi":"爸爸","pinyin":"bàba","m":"папа"},{"hanzi":"妈妈","pinyin":"māma","m":"мама"},{"hanzi":"儿子","pinyin":"érzi","m":"сын"},{"hanzi":"女儿","pinyin":"nǚ''ér","m":"дочь"},{"hanzi":"有","pinyin":"yǒu","m":"иметь"},{"hanzi":"没有","pinyin":"méiyǒu","m":"не иметь"},{"hanzi":"的","pinyin":"de","m":"принадлежность"},{"hanzi":"家","pinyin":"jiā","m":"дом, семья"},{"hanzi":"朋友","pinyin":"péngyou","m":"друг"},{"hanzi":"和","pinyin":"hé","m":"и"},{"hanzi":"个","pinyin":"gè","m":"счётное слово"},{"hanzi":"岁","pinyin":"suì","m":"год жизни"}],"tf":[{"zh":"我不有儿子。","py":"wǒ bù yǒu érzi.","m":"У меня нет сына.","ok":false,"explain":"Правильно: 我没有儿子."},{"zh":"我家有三个人。","py":"wǒ jiā yǒu sān gè rén.","m":"В семье три человека.","ok":true}],"sentences":[{"zh":"我有一个女儿。","tokens":["我","有","一个","女儿"],"m":"У меня одна дочь."},{"zh":"爸爸和妈妈","tokens":["爸爸","和","妈妈"],"m":"Папа и мама."},{"zh":"他是我朋友。","tokens":["他","是","我","朋友"],"m":"Он мой друг."}]}'),
  ('hsk1-06-1', 1, 'fact', '{"emoji":"💴","title":"«Кусочек» вместо «юаня»","text":"В разговоре юань называют 块 kuài, буквально «кусок, комок». Раньше деньги были слитками серебра, и название осталось. Знак 钱 «деньги» содержит ключ 钅 «металл»: монеты были из металла. А «сколько стоит?» звучит как «сколько денег?»: 多少钱？"}'),
  ('hsk1-06-1', 2, 'words', '{"title":"Четыре слова про деньги","items":[{"hanzi":"钱","pinyin":"qián","m":"деньги","emoji":"💰","ex":{"zh":"多少钱？","py":"Duōshao qián?","m":"Сколько стоит?"}},{"hanzi":"块","pinyin":"kuài","m":"юань (в речи)","emoji":"💴","ex":{"zh":"五块钱","py":"wǔ kuài qián","m":"пять юаней"}},{"hanzi":"买","pinyin":"mǎi","m":"покупать","emoji":"🛒","ex":{"zh":"我买苹果。","py":"Wǒ mǎi píngguǒ.","m":"Я покупаю яблоки."}},{"hanzi":"多少","pinyin":"duōshao","m":"сколько (много)","emoji":"🔢","ex":{"zh":"多少钱？","py":"Duōshao qián?","m":"Сколько стоит?"}}]}'),
  ('hsk1-06-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"💰","options":["买","块","钱"],"correct":2},{"emoji":"💴","options":["块","多少","钱"],"correct":0},{"emoji":"🛒","options":["买","块","钱"],"correct":0},{"emoji":"🔢","options":["几","买","多少"],"correct":2}]}'),
  ('hsk1-06-1', 4, 'theory', '{"title":"Как спрашивать цену","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["多少钱？","Duōshao qián?","Сколько стоит?"],["五块。","Wǔ kuài.","Пять юаней."],["二十块钱。","Èrshí kuài qián.","Двадцать юаней."]]},{"t":"p","text":"Цену называют числом + 块: 十块, 二十五块. Слово 钱 можно добавить в конце, но можно и опустить."},{"t":"tip","text":"Вспомните: 几 — «сколько» до десяти, 多少 — «сколько» вообще, для цен всегда 多少."}]}'),
  ('hsk1-06-1', 5, 'quiz', '{"title":"Мини-тест: цена","qs":[{"q":"Как спросить «Сколько стоит?»","options":["几钱？","多少钱？","钱多少吗？"],"correct":1},{"q":"块 в разговоре значит «юань».","tf":true},{"q":"Какой ключ в знаке 钱?","options":["亻","钅","女"],"correct":1,"explain":"钅 — «металл»."}]}'),
  ('hsk1-06-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["钱","деньги"],["块","юань (разг.)"],["买","покупать"],["多少","сколько"],["多少钱","сколько стоит"]]}'),
  ('hsk1-06-1', 7, 'game', '{"type":"listen","title":"Слушаем цены","items":[{"say":"钱","options":["qiàn","qián","qiǎn"],"correct":1},{"say":"块","options":["kuāi","kuǎi","kuài"],"correct":2},{"say":"买","options":["mǎi","mài","mái"],"correct":0,"explain":"Не путайте 买 mǎi «покупать» и 卖 mài «продавать»."},{"say":"多少钱","options":["duōshǎo qián","duōshao qián"],"correct":1},{"say":"五块钱","options":["wǔ guài qián","wǔ kuài qián"],"correct":1}]}'),
  ('hsk1-06-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["多少","钱"],"hint":"«Сколько стоит?»"},{"answer":["二","十","块"],"hint":"«Двадцать юаней.»"},{"answer":["我","买","苹果"],"hint":"«Я покупаю яблоки.»"}]}'),
  ('hsk1-06-1', 9, 'write', '{"title":"Пропись: деньги","items":[{"hanzi":"买","pinyin":"mǎi","m":"покупать","hint":"сверху 乛, внизу 头 без точки"},{"hanzi":"块","pinyin":"kuài","m":"юань","hint":"слева 土, справа 夬"},{"hanzi":"钱","pinyin":"qián","m":"деньги","hint":"слева 钅, справа 戋"}]}'),
  ('hsk1-06-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 买?","options":["деньги","продавать","сколько","покупать"],"correct":3},{"q":"Как читается 买?","options":["mài","mái","mǎi"],"correct":2},{"q":"Как назвать «десять юаней»?","options":["块十","十块块","十块"],"correct":2},{"q":"多少钱 — «Сколько стоит?»","tf":true},{"q":"Что значит 钱?","options":["юань","покупать","деньги"],"correct":2}]}'),
  ('hsk1-06-2', 1, 'fact', '{"emoji":"📏","title":"Прилагательные — это глаголы","text":"В китайском прилагательное само служит сказуемым: 我很高兴 «я очень рад», без «есть». Поэтому «много» — 多 duō, «мало» — 少 shǎo, «большой» — 大 dà, «маленький» — 小 xiǎo. Эти четыре слова вы будете слышать в магазине каждый день."}'),
  ('hsk1-06-2', 2, 'words', '{"title":"Четыре прилагательных","items":[{"hanzi":"多","pinyin":"duō","m":"много","emoji":"➕","ex":{"zh":"人很多。","py":"Rén hěn duō.","m":"Людей много."}},{"hanzi":"少","pinyin":"shǎo","m":"мало","emoji":"➖","ex":{"zh":"钱很少。","py":"Qián hěn shǎo.","m":"Денег мало."}},{"hanzi":"大","pinyin":"dà","m":"большой","emoji":"🐘","ex":{"zh":"学校很大。","py":"Xuéxiào hěn dà.","m":"Школа большая."}},{"hanzi":"小","pinyin":"xiǎo","m":"маленький","emoji":"🐭","ex":{"zh":"家很小。","py":"Jiā hěn xiǎo.","m":"Дом маленький."}}]}'),
  ('hsk1-06-2', 3, 'theory', '{"title":"Схема «предмет + 很 + прилагательное»","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["学校很大。","Xuéxiào hěn dà.","Школа большая."],["钱很多。","Qián hěn duō.","Денег много."],["家不大。","Jiā bú dà.","Дом небольшой."]]},{"t":"p","text":"Прилагательное не требует 是: говорите 很大, а не 是大. Для отрицания ставьте 不 перед прилагательным: 不大 bú dà (大 — 4 тон), 不多 bù duō (多 — 1 тон), 不少 bù shǎo, 不小 bù xiǎo."},{"t":"tip","text":"Пары-противоположности: 大 — 小, 多 — 少. Выучите их вместе."}]}'),
  ('hsk1-06-2', 4, 'game', '{"type":"build","title":"Соберите предложение","items":[{"answer":["学校","很","大"],"hint":"«Школа большая.»"},{"answer":["家","不","大"],"hint":"«Дом небольшой.»"},{"answer":["钱","很","少"],"hint":"«Денег мало.»"}]}'),
  ('hsk1-06-2', 5, 'quiz', '{"title":"Мини-тест: прилагательные","qs":[{"q":"Как сказать «Школа большая»?","options":["大学校是。","学校很大。","学校是大。"],"correct":1},{"q":"Как читается 不 в 不大?","options":["bǔ","bú","bù"],"correct":1},{"q":"Перед прилагательным нужна связка 是.","tf":false,"explain":"Не нужна, ставят 很."}]}'),
  ('hsk1-06-2', 6, 'game', '{"type":"match","title":"Слова-противоположности","pairs":[["多","много"],["少","мало"],["大","большой"],["小","маленький"],["很大","очень большой"]]}'),
  ('hsk1-06-2', 7, 'game', '{"type":"listen","title":"Слушаем: размер и количество","items":[{"say":"大","options":["dà","dǎ","dá"],"correct":0},{"say":"小","options":["xiào","xiǎo","xiāo"],"correct":1},{"say":"多","options":["duō","duǒ","duó"],"correct":0},{"say":"少","options":["shāo","shǎo","shào"],"correct":1},{"say":"不大","options":["bù dà","bú dà"],"correct":1,"explain":"大 — 4 тон: 不 → bú."},{"say":"不多","options":["bú duō","bù duō"],"correct":1,"explain":"多 — 1 тон: 不 остаётся bù."}]}'),
  ('hsk1-06-2', 8, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🐘","options":["多","大","小"],"correct":1},{"emoji":"🐭","options":["少","小","大"],"correct":1},{"emoji":"➕","options":["多","少","大"],"correct":0},{"emoji":"➖","options":["小","多","少"],"correct":2}]}'),
  ('hsk1-06-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: прилагательные","cases":[{"buggyText":"学校是很大。","context":"«Школа большая»","options":["学校很是大。","是学校大。","学校很大。"],"correct":2,"explain":"是 здесь не нужен."},{"buggyText":"钱很多不。","context":"«Денег немного»","options":["不钱多。","钱不多。","钱不很多。"],"correct":1}]}'),
  ('hsk1-06-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 少?","options":["мало","много","большой"],"correct":0},{"q":"Что значит 小?","options":["много","маленький","большой"],"correct":1},{"q":"Как сказать «Дом не очень большой» кратко?","options":["家不大。","家大不。","不家大。"],"correct":0},{"q":"很 ставится перед прилагательным.","tf":true},{"q":"Как читается 大?","options":["dǎ","dá","dà"],"correct":2}]}'),
  ('hsk1-06-3', 1, 'fact', '{"emoji":"🏪","title":"Магазин — «торговая лавка»","text":"商店 — это «торговля + лавка». А слово 东西 «вещь, предмет» буквально значит «восток и запад»: говорят, что на старых рынках Лояна и Чанъаня стороны света использовали, чтобы указать вещи. Указательное слово 这 zhè «это» вы будете использовать каждый день."}'),
  ('hsk1-06-3', 2, 'words', '{"title":"Три слова для магазина","items":[{"hanzi":"商店","pinyin":"shāngdiàn","m":"магазин","emoji":"🏪","ex":{"zh":"我去商店。","py":"Wǒ qù shāngdiàn.","m":"Я иду в магазин."}},{"hanzi":"东西","pinyin":"dōngxi","m":"вещь, предмет","emoji":"📦","ex":{"zh":"买东西","py":"mǎi dōngxi","m":"покупать вещи"}},{"hanzi":"这","pinyin":"zhè","m":"это, этот","emoji":"👉","ex":{"zh":"这个多少钱？","py":"Zhège duōshao qián?","m":"Сколько стоит это?"}}]}'),
  ('hsk1-06-3', 3, 'game', '{"type":"listen","title":"Слушаем в магазине","items":[{"say":"商店","options":["shāngdiàn","shàngdiàn","shāngdián"],"correct":0},{"say":"东西","options":["dōngxī","dōngxi","dóngxi"],"correct":1,"explain":"Второй слог безударный."},{"say":"这","options":["zhě","zhé","zhè"],"correct":2},{"say":"这个多少钱","options":["zhège jǐ qián","zhège duōshao qián"],"correct":1},{"say":"买东西","options":["mài dōngxi","mǎi dōngxi"],"correct":1}]}'),
  ('hsk1-06-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «zhè» (4 тон)"}'),
  ('hsk1-06-3', 5, 'theory', '{"title":"Схема «这个 + вопрос о цене»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["这个多少钱？","Сколько стоит это?"],["这个五块。","Это стоит пять юаней."],["这个很大。","Это большое."]]},{"t":"p","text":"这个 буквально «этот штука»: 这 «это» плюс счётное слово 个. Говорите 这个, когда показываете на предмет."},{"t":"tip","text":"В речи 这个 часто читают zhèige: оба варианта правильные."}]}'),
  ('hsk1-06-3', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["商店","магазин"],["东西","вещь"],["这","это"],["这个","этот предмет"],["买东西","покупать вещи"]]}'),
  ('hsk1-06-3', 7, 'game', '{"type":"chatsim","title":"WeChat: в магазине","messages":[{"speaker":"Продавец","text":"你好！你买什么？","pinyin":"Nǐ hǎo! Nǐ mǎi shénme?","translation":"Здравствуйте! Что покупаете?","options":["我叫苹果。","我买苹果。","我是苹果。"],"correct":1,"explain":"买 + предмет."},{"speaker":"Продавец","text":"这个很好。","pinyin":"Zhège hěn hǎo.","translation":"Это очень хорошее.","options":["你多少钱？","这个是什么吗？","这个多少钱？"],"correct":2},{"speaker":"Продавец","text":"十五块。","pinyin":"Shíwǔ kuài.","translation":"Пятнадцать юаней.","options":["不多！我买三个。","你很多。","我是三个。"],"correct":0}]}'),
  ('hsk1-06-3', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["这个","多少","钱"],"hint":"«Сколько стоит это?»"},{"answer":["我","买","这个"],"hint":"«Я куплю это.»"},{"answer":["我","去","商店"],"hint":"«Я иду в магазин.»"}]}'),
  ('hsk1-06-3', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 商店?","options":["вещь","деньги","магазин"],"correct":2},{"q":"Что значит 东西?","options":["восток","магазин","вещь, предмет"],"correct":2},{"q":"Как сказать «Сколько стоит это?»","options":["多少这个钱？","这多少个钱？","这个多少钱？"],"correct":2},{"q":"这 значит «это».","tf":true},{"q":"Как читается 这?","options":["zhè","zhé","zhě"],"correct":0}]}'),
  ('hsk1-06-4', 1, 'fact', '{"emoji":"🛍️","title":"Как торгуются в Китае","text":"В маленьких лавках цену часто называют «на пробу», а покупатель отвечает 太多了 «слишком много». Но сегодня у нас простая покупка: Анна и Ли Мин в магазине."}'),
  ('hsk1-06-4', 2, 'text', '{"title":"В магазине","lines":[{"zh":"安娜：你好！这个多少钱？","py":"Ānnà: Nǐ hǎo! Zhège duōshao qián?","m":"Анна: Здравствуйте! Сколько стоит это?"},{"zh":"店员：十五块。","py":"Diànyuán: Shíwǔ kuài.","m":"Продавец: Пятнадцать юаней."},{"zh":"安娜：不多！我买三个。","py":"Ānnà: Bù duō! Wǒ mǎi sān gè.","m":"Анна: Недорого! Я куплю три."},{"zh":"李明：你买几个？","py":"Lǐ Míng: Nǐ mǎi jǐ gè?","m":"Ли Мин: Сколько ты покупаешь?"},{"zh":"安娜：三个。多少钱？","py":"Ānnà: Sān gè. Duōshao qián?","m":"Анна: Три. Сколько?"},{"zh":"店员：四十五块。","py":"Diànyuán: Sìshíwǔ kuài.","m":"Продавец: Сорок пять юаней."},{"zh":"安娜：谢谢！再见！","py":"Ānnà: Xièxie! Zàijiàn!","m":"Анна: Спасибо! До свидания!"}],"qs":[{"q":"Сколько стоит одна штука?","options":["5 юаней","45 юаней","15 юаней"],"correct":2},{"q":"Сколько штук покупает Анна?","options":["три","пять","две"],"correct":0},{"q":"Анна считает цену слишком высокой.","tf":false,"explain":"Она говорит 不多."},{"q":"Сколько нужно заплатить всего?","options":["15 юаней","45 юаней","30 юаней"],"correct":1},{"q":"Вставьте слово: 你买___个？","options":["几","什么","吗"],"correct":0},{"q":"Продавец называет цену числом + 块.","tf":true},{"q":"Что значит 不多?","options":["нет денег","очень много","недорого, немного"],"correct":2}]}'),
  ('hsk1-06-4', 3, 'game', '{"type":"match","title":"Фраза и смысл","pairs":[["十五块","15 юаней"],["四十五块","45 юаней"],["我买三个","Я куплю три"],["不多","недорого"],["这个多少钱","Сколько стоит это"]]}'),
  ('hsk1-06-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"十五块","options":["shísì kuài","shíwǔ kuài"],"correct":1},{"say":"四十五块","options":["sānshíwǔ kuài","sìshíwǔ kuài"],"correct":1},{"say":"我买三个","options":["wǒ mǎi sì gè","wǒ mǎi sān gè"],"correct":1},{"say":"你买几个","options":["nǐ mǎi jǐ gè","nǐ mǎi shénme"],"correct":0}]}'),
  ('hsk1-06-4', 5, 'theory', '{"title":"Умножение по-китайски","blocks":[{"t":"table","head":["Расчёт","Результат"],"rows":[["15 × 3","45 — 四十五"],["20 × 2","40 — 四十"],["10 × 5","50 — 五十"]]},{"t":"p","text":"Считайте как обычно, а число называйте по схеме десятки + 十 + единицы."}]}'),
  ('hsk1-06-4', 6, 'game', '{"type":"bughunt","title":"Китайский детектив: покупки","cases":[{"buggyText":"这个钱多少？","context":"Спросить цену","options":["多少这个钱？","这个多少钱？","钱这个多少？"],"correct":1},{"buggyText":"我买三。","context":"«Я куплю три штуки»","options":["我买个三。","三我买。","我买三个。"],"correct":2},{"buggyText":"四十五块钱岁。","context":"«45 юаней»","options":["四十五岁块。","块四十五。","四十五块钱。"],"correct":2}]}'),
  ('hsk1-06-4', 7, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 不多?","options":["нет","очень много","недорого"],"correct":2},{"q":"Как будет «45»?","options":["五十四","四五","四十五"],"correct":2},{"q":"Анна благодарит продавца.","tf":true},{"q":"Как читается 十五?","options":["shíwú","shíwǔ","shìwǔ"],"correct":1}]}'),
  ('hsk1-06-5', 1, 'fact', '{"emoji":"🧺","title":"Открываем виртуальный магазин","text":"Вы продаёте и покупаете, считаете сдачу и называете цены. Слова из глав 1–6."}'),
  ('hsk1-06-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"钱","correctRadicals":["钅","戋"],"title":"Пазл: соберите 钱"}'),
  ('hsk1-06-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"钱","radicals":["钅","戋","亻"],"correctOrder":["钅","戋"],"explain":"Слева «металл» 钅, справа 戋."},{"targetHanzi":"块","radicals":["土","夬","女"],"correctOrder":["土","夬"],"explain":"Слева 土, справа 夬."},{"targetHanzi":"买","radicals":["乛","头","口"],"correctOrder":["乛","头"],"explain":"Сверху 乛, внизу 头."}]}'),
  ('hsk1-06-5', 4, 'game', '{"type":"build","title":"Мастерская ценников","items":[{"target":"(Ценник)","answer":["这个","五","块"],"hint":"«Это стоит пять юаней.»"},{"target":"(Ценник)","answer":["这个","二","十","五","块"],"hint":"«Это стоит 25 юаней.»"},{"target":"(Покупка)","answer":["我","买","四","个"],"hint":"«Я куплю четыре.»"},{"target":"(Вопрос)","answer":["你","买","什么"],"hint":"«Что ты покупаешь?»"}]}'),
  ('hsk1-06-5', 5, 'theory', '{"title":"Алгоритм покупки","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["1. Приветствие","你好！"],["2. Цена","这个多少钱？"],["3. Решение","我买…个。"],["4. Благодарность","谢谢！再见！"]]}]}'),
  ('hsk1-06-5', 6, 'game', '{"type":"chatsim","title":"WeChat: торг","messages":[{"speaker":"Продавец","text":"你买什么？","pinyin":"Nǐ mǎi shénme?","translation":"Что вы покупаете?","options":["我是这个。","我买这个。","我叫这个。"],"correct":1},{"speaker":"Продавец","text":"二十块。","pinyin":"Èrshí kuài.","translation":"Двадцать юаней.","options":["再见。","很多！","不客气。"],"correct":1,"explain":"Скажите, что дорого."},{"speaker":"Продавец","text":"十五块。","pinyin":"Shíwǔ kuài.","translation":"Пятнадцать юаней.","options":["好，我买。","没关系。","对不起。"],"correct":0}]}'),
  ('hsk1-06-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["钅 + 戋","钱"],["土 + 夬","块"],["乛 + 头","买"],["多少钱","сколько стоит"]]}'),
