  ('hsk1-06-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как спросить цену?","options":["这个多少钱？","多少这个钱？","这个几钱？"],"correct":0},{"q":"Как сказать «Школа большая»?","options":["学校大很。","学校是大。","学校很大。"],"correct":2},{"q":"Как читается 不 в 不大?","options":["bù","bǔ","bú"],"correct":2},{"q":"Как читается 不 в 不多?","options":["bú","bù","bǔ"],"correct":1},{"q":"买 и 卖 читаются одинаково.","tf":false,"explain":"买 mǎi, 卖 mài."},{"q":"Как будет «двадцать пять юаней»?","options":["五十二块","二十五块","二五块"],"correct":1},{"q":"块 — юань в разговорной речи.","tf":true},{"q":"Что значит 东西?","options":["вещь","деньги","восток"],"correct":0},{"q":"Как сказать «Я куплю три»?","options":["三我买个。","我买个三。","我买三个。"],"correct":2},{"q":"Какое слово значит «мало»?","options":["多","少","大"],"correct":1}]}'),
  ('hsk1-06-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["这个","多少","钱"],"hint":"«Сколько стоит это?»"},{"answer":["这个","十","五","块"],"hint":"«Это стоит 15 юаней.»"},{"answer":["我","买","三","个"],"hint":"«Я куплю три.»"},{"answer":["学校","很","大"],"hint":"«Школа большая.»"}]}'),
  ('hsk1-06-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"这个钱多少？","context":"Спросить цену","options":["这个多少钱？","钱这个多少？","多少这个钱？"],"correct":0},{"buggyText":"学校是很大。","context":"«Школа большая»","options":["学校很大。","是学校很大。","学校很是大。"],"correct":0},{"buggyText":"我买三。","context":"«Я куплю три штуки»","options":["我买个三。","三我买。","我买三个。"],"correct":2}]}'),
  ('hsk1-06-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Продавец","text":"你买什么？","pinyin":"Nǐ mǎi shénme?","translation":"Что вы покупаете?","options":["我买这个。","我叫这个。","我是这个。"],"correct":0},{"speaker":"Продавец","text":"十块。","pinyin":"Shí kuài.","translation":"Десять юаней.","options":["好，我买三个。","对不起。","没关系。"],"correct":0}]}'),
  ('hsk1-06-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"钱","pinyin":"qián","m":"деньги","hint":"钅 + 戋"},{"hanzi":"大","pinyin":"dà","m":"большой","hint":"три черты"},{"hanzi":"小","pinyin":"xiǎo","m":"маленький","hint":"три черты"}]}'),
  ('hsk1-06-6', 10, 'recall', '{"words":[{"hanzi":"钱","pinyin":"qián","m":"деньги"},{"hanzi":"块","pinyin":"kuài","m":"юань"},{"hanzi":"买","pinyin":"mǎi","m":"покупать"},{"hanzi":"多少","pinyin":"duōshao","m":"сколько"},{"hanzi":"多","pinyin":"duō","m":"много"},{"hanzi":"少","pinyin":"shǎo","m":"мало"},{"hanzi":"大","pinyin":"dà","m":"большой"},{"hanzi":"小","pinyin":"xiǎo","m":"маленький"},{"hanzi":"商店","pinyin":"shāngdiàn","m":"магазин"},{"hanzi":"东西","pinyin":"dōngxi","m":"вещь"},{"hanzi":"这","pinyin":"zhè","m":"это"}],"tf":[{"zh":"学校是很大。","py":"xuéxiào shì hěn dà.","m":"Школа большая.","ok":false,"explain":"Правильно: 学校很大."},{"zh":"这个多少钱？","py":"zhège duōshao qián?","m":"Сколько стоит это?","ok":true}],"sentences":[{"zh":"这个多少钱？","tokens":["这个","多少","钱"],"m":"Сколько стоит это?"},{"zh":"我买三个。","tokens":["我","买","三个"],"m":"Я куплю три."},{"zh":"学校很大。","tokens":["学校","很","大"],"m":"Школа большая."}]}'),
  ('hsk1-07-1', 1, 'fact', '{"emoji":"📅","title":"Китайская дата идёт от большого к малому","text":"Сначала год, потом месяц, потом число, потом день недели: 2026 год, ноябрь, 25-е, среда. Как будто вы наводите зум. Знак 月 нарисован как полумесяц и означает и «луну», и «месяц»: китайский календарь был лунным. Месяцы называются просто «первый месяц», «второй месяц»..."}'),
  ('hsk1-07-1', 2, 'words', '{"title":"Календарные слова","items":[{"hanzi":"年","pinyin":"nián","m":"год","emoji":"🗓️","ex":{"zh":"二零二六年","py":"èr líng èr liù nián","m":"2026 год"}},{"hanzi":"月","pinyin":"yuè","m":"месяц, луна","emoji":"🌙","ex":{"zh":"十一月","py":"shíyī yuè","m":"ноябрь"}},{"hanzi":"号","pinyin":"hào","m":"число (дата)","emoji":"🔢","ex":{"zh":"二十五号","py":"èrshíwǔ hào","m":"25-е число"}},{"hanzi":"星期","pinyin":"xīngqī","m":"неделя, день недели","emoji":"📆","ex":{"zh":"星期三","py":"xīngqī sān","m":"среда"}}]}'),
  ('hsk1-07-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🗓️","options":["月","年","号"],"correct":1},{"emoji":"🌙","options":["星期","年","月"],"correct":2},{"emoji":"🔢","options":["号","年","月"],"correct":0},{"emoji":"📆","options":["月","号","星期"],"correct":2}]}'),
  ('hsk1-07-1', 4, 'theory', '{"title":"Как говорить дату","blocks":[{"t":"table","head":["Часть","Пример","Перевод"],"rows":[["Год","二零二六年","2026 год (цифры по одной)"],["Месяц","十一月","ноябрь (число + 月)"],["Число","二十五号","25-е (число + 号)"],["День недели","星期三","среда (星期 + число)"]]},{"t":"p","text":"Год читают по цифрам: 二零二六年. Нуль называется 零 líng. Месяцы: 一月, 二月... 十二月. Дни недели: 星期一, 星期二 ... 星期六, а воскресенье — 星期天."},{"t":"tip","text":"Полная дата: 二零二六年十一月二十五号，星期三."}]}'),
  ('hsk1-07-1', 5, 'quiz', '{"title":"Мини-тест: календарь","qs":[{"q":"Как сказать «ноябрь»?","options":["月十一","一十月","十一月"],"correct":2},{"q":"Какой день недели 星期三?","options":["среда","вторник","пятница"],"correct":0},{"q":"Китайская дата начинается с года.","tf":true}]}'),
  ('hsk1-07-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["年","год"],["月","месяц, луна"],["号","число"],["星期","неделя"],["星期三","среда"]]}'),
  ('hsk1-07-1', 7, 'game', '{"type":"listen","title":"Слушаем календарь","items":[{"say":"年","options":["niǎn","niàn","nián"],"correct":2},{"say":"月","options":["yuě","yuè","yué"],"correct":1},{"say":"号","options":["háo","hào","hǎo"],"correct":1},{"say":"星期三","options":["xīngqī sì","xīngqī sān"],"correct":1},{"say":"十一月","options":["shíyī yuè","shí''èr yuè"],"correct":0}]}'),
  ('hsk1-07-1', 8, 'game', '{"type":"build","title":"Соберите дату","items":[{"answer":["十","一","月"],"hint":"«Ноябрь.»"},{"answer":["二","十","五","号"],"hint":"«25-е число.»"},{"answer":["星期","三"],"hint":"«Среда.»"},{"answer":["十","二","月"],"hint":"«Декабрь.»"}]}'),
  ('hsk1-07-1', 9, 'write', '{"title":"Пропись: календарь","items":[{"hanzi":"年","pinyin":"nián","m":"год","hint":"горизонталь, вертикаль, потом нижние линии"},{"hanzi":"月","pinyin":"yuè","m":"месяц","hint":"рамка с двумя чертами внутри"},{"hanzi":"号","pinyin":"hào","m":"число","hint":"сверху 口, внизу 丂"}]}'),
  ('hsk1-07-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 年?","options":["год","месяц","неделя"],"correct":0},{"q":"Как читается 月?","options":["yuè","yué","yuě"],"correct":0},{"q":"Как сказать «пятое число»?","options":["五月","五号","号五"],"correct":1},{"q":"Воскресенье называется 星期天.","tf":true},{"q":"Как будет «январь»?","options":["月一","一年","一月"],"correct":2}]}'),
  ('hsk1-07-2', 1, 'fact', '{"emoji":"⏳","title":"Глагол «быть» в датах не нужен","text":"По-русски мы говорим «Сегодня среда». По-китайски тоже: 今天星期三, без 是. Слова 今天, 明天, 昨天 ставятся в начало предложения, до глагола. А вопрос про дату звучит как «какой сегодня номер?»: 今天几号？"}'),
  ('hsk1-07-2', 2, 'words', '{"title":"Три слова времени","items":[{"hanzi":"今天","pinyin":"jīntiān","m":"сегодня","emoji":"☀️","ex":{"zh":"今天星期三。","py":"Jīntiān xīngqī sān.","m":"Сегодня среда."}},{"hanzi":"明天","pinyin":"míngtiān","m":"завтра","emoji":"🌅","ex":{"zh":"明天星期四。","py":"Míngtiān xīngqī sì.","m":"Завтра четверг."}},{"hanzi":"昨天","pinyin":"zuótiān","m":"вчера","emoji":"🌇","ex":{"zh":"昨天星期二。","py":"Zuótiān xīngqī èr.","m":"Вчера был вторник."}}]}'),
  ('hsk1-07-2', 3, 'theory', '{"title":"Вопросы о дате","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["今天几号？","今天二十五号。"],["今天星期几？","今天星期三。"],["明天星期几？","明天星期四。"]]},{"t":"p","text":"几 здесь «какой по номеру». Отвечаем, подставляя число на место 几. Глагол 是 не нужен, но для отрицания он обязателен: 今天不是星期四."},{"t":"tip","text":"Для утверждения можно сказать и 今天是星期三 — это вежливее и чуть формальнее."}]}'),
  ('hsk1-07-2', 4, 'game', '{"type":"build","title":"Соберите вопрос","items":[{"answer":["今天","几","号"],"hint":"«Какое сегодня число?»"},{"answer":["明天","星期","几"],"hint":"«Какой завтра день недели?»"},{"answer":["今天","不","是","星期","四"],"hint":"«Сегодня не четверг.»"}]}'),
  ('hsk1-07-2', 5, 'quiz', '{"title":"Мини-тест: сегодня, завтра","qs":[{"q":"Как спросить «Какой сегодня день недели?»","options":["今天星期几？","今天几星期？","星期几今天？"],"correct":0},{"q":"Как сказать «Вчера был вторник»?","options":["昨天是二星期。","星期二昨天是。","昨天星期二。"],"correct":2},{"q":"К вопросу 今天几号？ нужна частица 吗.","tf":false,"explain":"Вопросительное слово 几 уже задаёт вопрос."}]}'),
  ('hsk1-07-2', 6, 'theory', '{"title":"Время стоит перед глаголом","blocks":[{"t":"table","head":["Русский порядок","Китайский порядок"],"rows":[["Я завтра куплю","我明天买"],["Он сегодня учится","他今天学习"],["Мы вчера покупали","我们昨天买"]]},{"t":"p","text":"Слово времени стоит после подлежащего и перед глаголом: 我明天买东西. Можно и поставить время в самое начало: 明天我买东西."}]}'),
  ('hsk1-07-2', 7, 'game', '{"type":"listen","title":"Слушаем: время","items":[{"say":"今天","options":["jīntián","jīntiān","jǐntiān"],"correct":1},{"say":"明天","options":["míngtián","míngtiān","mìngtiān"],"correct":1},{"say":"昨天","options":["zuòtiān","zuǒtiān","zuótiān"],"correct":2},{"say":"今天几号","options":["jīntiān jǐ hào","jīntiān jǐ yuè"],"correct":0},{"say":"明天星期四","options":["míngtiān xīngqī sān","míngtiān xīngqī sì"],"correct":1}]}'),
  ('hsk1-07-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["今天","сегодня"],["明天","завтра"],["昨天","вчера"],["几号","какое число"],["星期几","какой день недели"]]}'),
  ('hsk1-07-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: время","cases":[{"buggyText":"今天几号吗？","context":"Спросить число","options":["今天几吗号？","今天几号？","几号今天吗？"],"correct":1},{"buggyText":"今天是星期不四。","context":"«Сегодня не четверг»","options":["今天不是星期四。","今天星期不是四。","不今天是星期四。"],"correct":0},{"buggyText":"我买明天。","context":"«Я куплю завтра»","options":["我买东西明天。","我明天买。","买明天我。"],"correct":1,"explain":"Время ставится перед глаголом."}]}'),
  ('hsk1-07-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 昨天?","options":["сегодня","завтра","вчера"],"correct":2},{"q":"Что значит 明天?","options":["завтра","сегодня","вчера"],"correct":0},{"q":"Как читается 今天?","options":["jīntián","jǐntiān","jīntiān"],"correct":2},{"q":"Слово 今天 ставится перед глаголом.","tf":true},{"q":"Как спросить «Какое завтра число?»","options":["明天几？","几明天号？","明天几号？"],"correct":2}]}'),
  ('hsk1-07-3', 1, 'fact', '{"emoji":"🕐","title":"«Точка» времени и «минуты»","text":"Час называют 点 diǎn, буквально «точка»: на циферблате стрелка указывает на точку. А слово 分钟 «минута» состоит из 分 «часть» и 钟 «часы, колокол»: старые часы были колоколами. Не забудьте особенность: «два часа» — это 两点 liǎng diǎn, не 二点."}'),
  ('hsk1-07-3', 2, 'words', '{"title":"Три слова про часы","items":[{"hanzi":"现在","pinyin":"xiànzài","m":"сейчас","emoji":"⏱️","ex":{"zh":"现在几点？","py":"Xiànzài jǐ diǎn?","m":"Который сейчас час?"}},{"hanzi":"点","pinyin":"diǎn","m":"час (на часах)","emoji":"🕒","ex":{"zh":"现在三点。","py":"Xiànzài sān diǎn.","m":"Сейчас три часа."}},{"hanzi":"分钟","pinyin":"fēnzhōng","m":"минута (длительность)","emoji":"⌛","ex":{"zh":"十分钟","py":"shí fēnzhōng","m":"десять минут"}}]}'),
  ('hsk1-07-3', 3, 'game', '{"type":"listen","title":"Слушаем время","items":[{"say":"现在","options":["xiānzài","xiànzāi","xiànzài"],"correct":2},{"say":"点","options":["diǎn","dián","diàn"],"correct":0},{"say":"分钟","options":["fēnzhòng","fēnzhōng","fénzhōng"],"correct":1},{"say":"现在三点","options":["xiànzài sān diǎn","xiànzài sì diǎn"],"correct":0},{"say":"现在几点","options":["xiànzài jǐ diǎn","xiànzài jǐ hào"],"correct":0}]}'),
  ('hsk1-07-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «diǎn» (3 тон)"}'),
  ('hsk1-07-3', 5, 'theory', '{"title":"Как назвать время","blocks":[{"t":"table","head":["Время","Китайский"],"rows":[["3:00","三点"],["3:10","三点十分"],["2:00","两点 (не 二点)"],["3:30","三点半 (半 — «половина»)"]]},{"t":"p","text":"Формула: число + 点 + число + 分. Для длительности используют 分钟: 十分钟 «десять минут»."},{"t":"tip","text":"Спросить время: 现在几点？ Ответить: 现在三点。"}]}'),
  ('hsk1-07-3', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["现在","сейчас"],["点","час"],["分钟","минута"],["三点","три часа"],["十分钟","десять минут"]]}'),
  ('hsk1-07-3', 7, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"⏱️","options":["今天","分钟","现在"],"correct":2},{"emoji":"🕒","options":["三号","三月","三点"],"correct":2},{"emoji":"⌛","options":["分钟","现在","点"],"correct":0}]}'),
  ('hsk1-07-3', 8, 'game', '{"type":"chatsim","title":"WeChat: во сколько?","messages":[{"speaker":"Ли Мин","text":"现在几点？","pinyin":"Xiànzài jǐ diǎn?","translation":"Который сейчас час?","options":["现在三岁。","现在三点。","现在三号。"],"correct":1},{"speaker":"Ли Мин","text":"明天几点？","pinyin":"Míngtiān jǐ diǎn?","translation":"Во сколько завтра?","options":["明天五个。","明天五月。","明天五点。"],"correct":2},{"speaker":"Ли Мин","text":"你学习几分钟？","pinyin":"Nǐ xuéxí jǐ fēnzhōng?","translation":"Сколько минут ты учишься?","options":["我学习二十点。","我学习二十分钟。","我学习二十号。"],"correct":1}]}'),
  ('hsk1-07-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["现在","几","点"],"hint":"«Который час?»"},{"answer":["现在","三","点"],"hint":"«Сейчас три часа.»"},{"answer":["十","分钟"],"hint":"«Десять минут.»"},{"answer":["我","明天","三","点","学习"],"hint":"«Завтра в три я учусь.»"}]}'),
  ('hsk1-07-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 点 в 三点?","options":["точка","минута","час"],"correct":2},{"q":"Как читается 现在?","options":["xiānzài","xiànzài","xiànzāi"],"correct":1},{"q":"Как сказать «два часа»?","options":["二点","二个点","两点"],"correct":2},{"q":"分钟 — это «минута» как длительность.","tf":true},{"q":"Как спросить «Который час?»","options":["现在几分钟？","几现在点？","现在几点？"],"correct":2}]}'),
  ('hsk1-07-4', 1, 'fact', '{"emoji":"📆","title":"Договариваемся о завтрашнем дне","text":"Анна и Ли Мин уточняют дату и время. Фраза 明天见 «увидимся завтра» знакомая 见 из 再见 в новом сочетании."}'),
  ('hsk1-07-4', 2, 'text', '{"title":"Какой сегодня день","lines":[{"zh":"安娜：今天几号？","py":"Ānnà: Jīntiān jǐ hào?","m":"Анна: Какое сегодня число?"},{"zh":"李明：今天十一月二十五号，星期三。","py":"Lǐ Míng: Jīntiān shíyī yuè èrshíwǔ hào, xīngqī sān.","m":"Ли Мин: Сегодня 25 ноября, среда."},{"zh":"安娜：昨天是二十四号吗？","py":"Ānnà: Zuótiān shì èrshísì hào ma?","m":"Анна: Вчера было 24-е?"},{"zh":"李明：是。","py":"Lǐ Míng: Shì.","m":"Ли Мин: Да."},{"zh":"安娜：明天星期几？","py":"Ānnà: Míngtiān xīngqī jǐ?","m":"Анна: Какой завтра день недели?"},{"zh":"李明：明天星期四。现在三点。","py":"Lǐ Míng: Míngtiān xīngqī sì. Xiànzài sān diǎn.","m":"Ли Мин: Завтра четверг. Сейчас три часа."},{"zh":"安娜：明天见！","py":"Ānnà: Míngtiān jiàn!","m":"Анна: До завтра!"},{"zh":"李明：明天见！","py":"Lǐ Míng: Míngtiān jiàn!","m":"Ли Мин: До завтра!"}],"qs":[{"q":"Какое сегодня число?","options":["26","24","25"],"correct":2},{"q":"Какой завтра день недели?","options":["четверг","среда","пятница"],"correct":0},{"q":"Вчера было 24-е число.","tf":true},{"q":"Который сейчас час?","options":["четыре","три","два"],"correct":1},{"q":"Вставьте слово: 明天___！","options":["是","好","见"],"correct":2},{"q":"Сегодня четверг.","tf":false,"explain":"Сегодня среда."},{"q":"Какой вопрос задаёт Анна про завтра?","options":["明天星期几？","明天几号吗？","明天几点吗？"],"correct":0}]}'),
  ('hsk1-07-4', 3, 'game', '{"type":"match","title":"Фраза и смысл","pairs":[["十一月二十五号","25 ноября"],["星期三","среда"],["星期四","четверг"],["现在三点","сейчас три часа"],["明天见","до завтра"]]}'),
