  ('hsk1-08-1', 1, 'fact', '{"emoji":"🌞","title":"Полдень — точка отсчёта","text":"Знак 午 означает «полдень» (в старину — час лошади, 11–13 часов). От него сделаны слова: 上午 «верхняя половина дня» и 下午 «нижняя половина дня». Утро до полудня — 上午, день вокруг — 中午, после полудня — 下午. А 时候 «время, момент» вы встретите в вопросе «когда?»: 什么时候？"}'),
  ('hsk1-08-1', 2, 'words', '{"title":"Части дня","items":[{"hanzi":"上午","pinyin":"shàngwǔ","m":"утро, до полудня","emoji":"🌅","ex":{"zh":"上午九点","py":"shàngwǔ jiǔ diǎn","m":"девять утра"}},{"hanzi":"中午","pinyin":"zhōngwǔ","m":"полдень","emoji":"🌞","ex":{"zh":"中午十二点","py":"zhōngwǔ shí''èr diǎn","m":"двенадцать часов дня"}},{"hanzi":"下午","pinyin":"xiàwǔ","m":"вторая половина дня","emoji":"🌇","ex":{"zh":"下午三点","py":"xiàwǔ sān diǎn","m":"три часа дня"}},{"hanzi":"时候","pinyin":"shíhou","m":"время, момент","emoji":"⏰","ex":{"zh":"什么时候？","py":"Shénme shíhou?","m":"Когда?"}}]}'),
  ('hsk1-08-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🌅","options":["上午","中午","下午"],"correct":0},{"emoji":"🌞","options":["中午","时候","上午"],"correct":0},{"emoji":"🌇","options":["下午","中午","上午"],"correct":0},{"emoji":"⏰","options":["时候","现在","上午"],"correct":0}]}'),
  ('hsk1-08-1', 4, 'theory', '{"title":"Время суток и час","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["上午九点","9 утра"],["中午十二点","12 часов дня"],["下午三点","15:00"],["什么时候？","Когда?"]]},{"t":"p","text":"Часть дня ставится перед часом: 下午三点. В вопросе «когда?» используют 什么时候 буквально «в какое время»."},{"t":"tip","text":"Не забудьте: 12 часов — 十二点, а «два часа» — 两点."}]}'),
  ('hsk1-08-1', 5, 'quiz', '{"title":"Мини-тест: время суток","qs":[{"q":"Как сказать «три часа дня»?","options":["三点下午","下午三点","三下午点"],"correct":1},{"q":"上午 — это время до полудня.","tf":true},{"q":"Как спросить «Когда?»","options":["几时候？","什么时候？","时候什么？"],"correct":1}]}'),
