  ('hsk1-08-1', 7, 'game', '{"type":"listen","title":"Слушаем: части дня","items":[{"say":"上午","options":["shàngwǔ","shāngwǔ","shàngwú"],"correct":0},{"say":"中午","options":["zhòngwǔ","zhōngwǔ","zhōngwú"],"correct":1},{"say":"下午","options":["xiàwǔ","xiāwǔ","xiàwú"],"correct":0},{"say":"什么时候","options":["shénme shíhòu","shénme shíhou"],"correct":1},{"say":"下午三点","options":["shàngwǔ sān diǎn","xiàwǔ sān diǎn"],"correct":1}]}'),
  ('hsk1-08-1', 8, 'game', '{"type":"build","title":"Соберите время","items":[{"answer":["上午","九","点"],"hint":"«Девять утра.»"},{"answer":["下午","三","点"],"hint":"«Три часа дня.»"},{"answer":["什么","时候"],"hint":"«Когда?»"}]}'),
