  ('hsk1-08-2', 1, 'fact', '{"emoji":"🚶","title":"Движение без предлогов","text":"По-русски мы говорим «иду В школу», «возвращаюсь ДОМОЙ». В китайском предлог не нужен: 去学校 «пойти школа», 回家 «вернуться дом». Три глагола движения: 来 «приходить сюда», 去 «идти туда», 回 «возвращаться». А 能 «мочь» ставится перед другим глаголом, как знакомое 会."}'),
  ('hsk1-08-2', 2, 'words', '{"title":"Четыре глагола","items":[{"hanzi":"来","pinyin":"lái","m":"приходить","emoji":"🚪","ex":{"zh":"你来学校吗？","py":"Nǐ lái xuéxiào ma?","m":"Ты придёшь в школу?"}},{"hanzi":"去","pinyin":"qù","m":"идти, ехать (туда)","emoji":"🚶","ex":{"zh":"我去商店。","py":"Wǒ qù shāngdiàn.","m":"Я иду в магазин."}},{"hanzi":"回","pinyin":"huí","m":"возвращаться","emoji":"🏠","ex":{"zh":"我回家。","py":"Wǒ huí jiā.","m":"Я иду домой."}},{"hanzi":"能","pinyin":"néng","m":"мочь, быть в состоянии","emoji":"💪","ex":{"zh":"你能来吗？","py":"Nǐ néng lái ma?","m":"Ты можешь прийти?"}}]}'),
  ('hsk1-08-2', 3, 'theory', '{"title":"Глагол + место","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["我去学校。","Wǒ qù xuéxiào.","Я иду в школу."],["我回家。","Wǒ huí jiā.","Я иду домой."],["他来北京。","Tā lái Běijīng.","Он приезжает в Пекин."]]},{"t":"p","text":"来 используют, когда движение направлено к говорящему, 去 — от него. 回 — «вернуться» в привычное место (дом, школу)."},{"t":"tip","text":"Время стоит перед глаголом: 我明天去学校."}]}'),
  ('hsk1-08-2', 4, 'game', '{"type":"build","title":"Соберите предложение","items":[{"answer":["我","去","学校"],"hint":"«Я иду в школу.»"},{"answer":["我","回","家"],"hint":"«Я иду домой.»"},{"answer":["你","明天","来","吗"],"hint":"«Ты завтра придёшь?»"}]}'),
  ('hsk1-08-2', 5, 'quiz', '{"title":"Мини-тест: движение","qs":[{"q":"Как сказать «Я иду домой»?","options":["我去在家。","我回家。","我回到家。"],"correct":1},{"q":"Какой глагол значит «идти туда»?","options":["来","回","去"],"correct":2},{"q":"После 去 нужен предлог «в».","tf":false,"explain":"Китайский обходится без него."}]}'),
  ('hsk1-08-2', 6, 'theory', '{"title":"Скрытая фишка: 不 с глаголами движения","blocks":[{"t":"table","head":["Слово","Тон","С 不"],"rows":[["去 qù","4","不去 bú qù"],["来 lái","2","不来 bù lái"],["回 huí","2","不回 bù huí"],["能 néng","2","不能 bù néng"]]},{"t":"p","text":"Только перед 去 отрицание превращается в bú: это 4 тон. Во всех других случаях 不 остаётся bù."}]}'),
  ('hsk1-08-2', 7, 'game', '{"type":"listen","title":"Слушаем: 来, 去, 回, 能","items":[{"say":"去学校","options":["lái xuéxiào","qù xuéxiào"],"correct":1},{"say":"回家","options":["huì jiā","huí jiā"],"correct":1},{"say":"不去","options":["bú qù","bù qù"],"correct":0},{"say":"不来","options":["bù lái","bú lái"],"correct":0},{"say":"你能来吗","options":["nǐ néng lái ma","nǐ huì lái ma"],"correct":0}]}'),
  ('hsk1-08-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["来","приходить"],["去","идти туда"],["回","возвращаться"],["能","мочь"],["回家","идти домой"]]}'),
  ('hsk1-08-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: глаголы движения","cases":[{"buggyText":"我去在学校。","context":"«Я иду в школу»","options":["我在去学校。","我去的学校。","我去学校。"],"correct":2},{"buggyText":"我回去家。","context":"«Я иду домой»","options":["我家回。","我回在家。","我回家。"],"correct":2},{"buggyText":"你来能吗？","context":"«Ты можешь прийти?»","options":["你能来吗？","你来吗能？","能你来吗？"],"correct":0}]}'),
  ('hsk1-08-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 回?","options":["приходить","возвращаться","идти"],"correct":1},{"q":"Как читается 不去?","options":["bú qù","bù qù","bǔ qù"],"correct":0},{"q":"Как спросить «Ты можешь прийти?»","options":["你能来吗？","你来吗能？","你来能吗？"],"correct":0},{"q":"Перед 去 отрицание 不 читается bú.","tf":true},{"q":"Как сказать «Я завтра иду в школу»?","options":["明天学校我去。","我去明天学校。","我明天去学校。"],"correct":2}]}'),
  ('hsk1-08-3', 1, 'fact', '{"emoji":"👔","title":"«Родившийся раньше»","text":"先生 xiānsheng — «господин», «учитель», иногда и «муж». Буквально «родившийся раньше» (先 «раньше» + 生 «родиться»): уважительное обращение к старшим. 小姐 xiǎojiě — «госпожа, девушка»: «маленькая сестра». Слово 睡觉 «спать» разделяется: 觉 здесь читается jiào, а не jué."}'),
  ('hsk1-08-3', 2, 'words', '{"title":"Работа, сон, обращения","items":[{"hanzi":"睡觉","pinyin":"shuìjiào","m":"спать","emoji":"😴","ex":{"zh":"我十点睡觉。","py":"Wǒ shí diǎn shuìjiào.","m":"Я ложусь спать в десять."}},{"hanzi":"工作","pinyin":"gōngzuò","m":"работать, работа","emoji":"💼","ex":{"zh":"我下午工作。","py":"Wǒ xiàwǔ gōngzuò.","m":"Я работаю днём."}},{"hanzi":"先生","pinyin":"xiānsheng","m":"господин, Вы (к мужчине)","emoji":"👨‍💼","ex":{"zh":"王先生，您好！","py":"Wáng xiānsheng, nín hǎo!","m":"Здравствуйте, господин Ван!"}},{"hanzi":"小姐","pinyin":"xiǎojiě","m":"госпожа, девушка","emoji":"👩‍💼","ex":{"zh":"李小姐，您好！","py":"Lǐ xiǎojiě, nín hǎo!","m":"Здравствуйте, госпожа Ли!"}}]}'),
  ('hsk1-08-3', 3, 'game', '{"type":"listen","title":"Слушаем: работа и обращения","items":[{"say":"睡觉","options":["shuìjué","shuìjiào","shuǐjiào"],"correct":1},{"say":"工作","options":["gōngzuǒ","gōngzuò","góngzuò"],"correct":1},{"say":"先生","options":["xiānsheng","xiánsheng","xiānshēng"],"correct":0},{"say":"小姐","options":["xiǎojiě","xiǎojiè","xiáojiě"],"correct":0},{"say":"王先生，您好","options":["Wáng xiǎojiě, nín hǎo","Wáng xiānsheng, nín hǎo"],"correct":1}]}'),
  ('hsk1-08-3', 4, 'game', '{"type":"tone_visualizer","initialTone":1,"title":"Тренажёр голоса: повторите «gōng» (1 тон)"}'),
  ('hsk1-08-3', 5, 'theory', '{"title":"Как обращаться к людям","blocks":[{"t":"table","head":["Обращение","Когда"],"rows":[["王先生","господин Ван (к мужчине)"],["李小姐","госпожа Ли (к девушке)"],["王老师","учитель Ван"]]},{"t":"p","text":"Фамилия идёт перед обращением: 王先生, 李小姐, 王老师. К 先生 и 小姐 лучше добавлять 您, чтобы звучать вежливо."}]}'),
  ('hsk1-08-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"😴","options":["睡觉","来","工作"],"correct":0},{"emoji":"💼","options":["睡觉","回","工作"],"correct":2},{"emoji":"👨‍💼","options":["小姐","老师","先生"],"correct":2},{"emoji":"👩‍💼","options":["学生","小姐","先生"],"correct":1}]}'),
  ('hsk1-08-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["睡觉","спать"],["工作","работать"],["先生","господин"],["小姐","госпожа"],["王先生","господин Ван"]]}'),
  ('hsk1-08-3', 8, 'game', '{"type":"chatsim","title":"WeChat: распорядок","messages":[{"speaker":"Ли Мин","text":"你下午工作吗？","pinyin":"Nǐ xiàwǔ gōngzuò ma?","translation":"Ты днём работаешь?","options":["不工作，我是工作。","工作，我三点来。","工作，我三点睡。"],"correct":1},{"speaker":"Ли Мин","text":"你几点睡觉？","pinyin":"Nǐ jǐ diǎn shuìjiào?","translation":"Во сколько ты ложишься спать?","options":["我十个睡觉。","我十号睡觉。","我十点睡觉。"],"correct":2},{"speaker":"Ли Мин","text":"王先生好！","pinyin":"Wáng xiānsheng hǎo!","translation":"Здравствуйте, господин Ван!","options":["您好！","不客气。","再见！"],"correct":0}]}'),
  ('hsk1-08-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","下午","工作"],"hint":"«Днём я работаю.»"},{"answer":["我","十","点","睡觉"],"hint":"«В десять я ложусь спать.»"},{"answer":["王","先生","您好"],"hint":"«Здравствуйте, господин Ван!»"}]}'),
  ('hsk1-08-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 睡觉?","options":["спать","работать","приходить"],"correct":0},{"q":"Как читается 先生?","options":["xiǎnsheng","xiānsheng","xiānshēng"],"correct":1},{"q":"先生 буквально «родившийся раньше».","tf":true},{"q":"Как сказать «господин Ван»?","options":["王的先生","王先生","先生王"],"correct":1},{"q":"Что значит 小姐?","options":["госпожа, девушка","господин","учитель"],"correct":0}]}'),
  ('hsk1-08-4', 1, 'fact', '{"emoji":"📱","title":"Договорённость в чате","text":"Анна и Ли Мин решают, когда они придут в школу завтра. Все слова уже знакомы."}'),
  ('hsk1-08-4', 2, 'text', '{"title":"Договариваемся на завтра","lines":[{"zh":"李明：安娜，你明天上午来学校吗？","py":"Lǐ Míng: Ānnà, nǐ míngtiān shàngwǔ lái xuéxiào ma?","m":"Ли Мин: Анна, ты завтра утром придёшь в школу?"},{"zh":"安娜：不来。我下午去学校。","py":"Ānnà: Bù lái. Wǒ xiàwǔ qù xuéxiào.","m":"Анна: Нет. Я приду днём."},{"zh":"李明：什么时候？","py":"Lǐ Míng: Shénme shíhou?","m":"Ли Мин: Во сколько?"},{"zh":"安娜：下午三点。你能来吗？","py":"Ānnà: Xiàwǔ sān diǎn. Nǐ néng lái ma?","m":"Анна: В три часа дня. Ты можешь прийти?"},{"zh":"李明：能！我三点去学校。","py":"Lǐ Míng: Néng! Wǒ sān diǎn qù xuéxiào.","m":"Ли Мин: Могу! Я приду в три."},{"zh":"安娜：好，明天见！","py":"Ānnà: Hǎo, míngtiān jiàn!","m":"Анна: Хорошо, до завтра!"},{"zh":"李明：明天见！","py":"Lǐ Míng: Míngtiān jiàn!","m":"Ли Мин: До завтра!"}],"qs":[{"q":"Когда Анна придёт в школу?","options":["утром","в полдень","днём в три"],"correct":2},{"q":"Анна придёт в школу утром.","tf":false,"explain":"Она говорит 不来 про утро."},{"q":"Что отвечает Ли Мин на вопрос 你能来吗？","options":["不能","不去","能"],"correct":2},{"q":"Вставьте слово: 我下午___学校。","options":["来","去","回"],"correct":1},{"q":"Ли Мин тоже пойдёт в школу в три часа.","tf":true},{"q":"Как Ли Мин спрашивает про время?","options":["什么时候？","几号？","几个？"],"correct":0},{"q":"Чем заканчивается диалог?","options":["明天见","不客气","对不起"],"correct":0}]}'),
  ('hsk1-08-4', 3, 'game', '{"type":"match","title":"Фраза и смысл","pairs":[["你能来吗？","Ты можешь прийти?"],["不来","не приду"],["下午三点","в три часа дня"],["明天见","до завтра"],["什么时候？","когда?"]]}'),
  ('hsk1-08-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你明天上午来学校吗","options":["nǐ míngtiān shàngwǔ lái xuéxiào ma","nǐ míngtiān xiàwǔ lái xuéxiào ma"],"correct":0},{"say":"我下午去学校","options":["wǒ shàngwǔ qù xuéxiào","wǒ xiàwǔ qù xuéxiào"],"correct":1},{"say":"你能来吗","options":["nǐ huì lái ma","nǐ néng lái ma"],"correct":1},{"say":"明天见","options":["míngtiān zàijiàn","míngtiān jiàn"],"correct":1}]}'),
  ('hsk1-08-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: план","cases":[{"buggyText":"我下午学校去。","context":"«Днём я иду в школу»","options":["下午我学校去。","我下午去学校。","去我下午学校。"],"correct":1},{"buggyText":"你能不来吗？","context":"«Ты можешь прийти?»","options":["你来能吗？","你能来吗？","能来你吗？"],"correct":1},{"buggyText":"我三点来去学校。","context":"«В три я иду в школу»","options":["我去三点学校。","我三点去学校。","三点学校去我。"],"correct":1}]}'),
  ('hsk1-08-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Днём я иду домой»?","options":["我下午回家。","我回下午家。","下午回我家。"],"correct":0},{"q":"Как читается 不来?","options":["bú lái","bù lái","bǔ lái"],"correct":1},{"q":"Ли Мин и Анна встретятся в три часа.","tf":true}]}'),
  ('hsk1-08-5', 1, 'fact', '{"emoji":"🗓️","title":"Расскажите о своём дне","text":"Составьте расписание дня и расскажите, когда вы работаете, учитесь и спите. Слова глав 1–8."}'),
  ('hsk1-08-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"睡","correctRadicals":["目","垂"],"title":"Пазл: соберите 睡"}'),
  ('hsk1-08-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"睡","radicals":["目","垂","口"],"correctOrder":["目","垂"],"explain":"Слева 目 «глаз», справа 垂."},{"targetHanzi":"工","radicals":["一","丨","口"],"correctOrder":["一","丨","一"],"explain":"Три черты: верхняя, вертикаль, нижняя."},{"targetHanzi":"回","radicals":["囗","口","日"],"correctOrder":["囗","口"],"explain":"Рамка и внутри 口."}]}'),
  ('hsk1-08-5', 4, 'game', '{"type":"build","title":"Мастерская расписания","items":[{"target":"(Расписание)","answer":["上午","我","去","学校"],"hint":"«Утром я иду в школу.»"},{"target":"(Расписание)","answer":["中午","我","回","家"],"hint":"«В полдень я иду домой.»"},{"target":"(Расписание)","answer":["下午","我","工作"],"hint":"«Днём я работаю.»"},{"target":"(Расписание)","answer":["我","十","点","睡觉"],"hint":"«В десять я ложусь спать.»"}]}'),
  ('hsk1-08-5', 5, 'theory', '{"title":"Образец рассказа о дне","blocks":[{"t":"table","head":["Время","Фраза"],"rows":[["Утро","上午我去学校。"],["Полдень","中午我回家。"],["День","下午我工作。"],["Ночь","十点我睡觉。"]]}]}'),
  ('hsk1-08-5', 6, 'game', '{"type":"chatsim","title":"WeChat: мой день","messages":[{"speaker":"Друг","text":"你上午做什么？","pinyin":"Nǐ shàngwǔ zuò shénme?","translation":"Что ты делаешь утром? (做 «делать» — новое слово)","options":["我叫学校。","我去学校。","我是学校。"],"correct":1},{"speaker":"Друг","text":"你几点回家？","pinyin":"Nǐ jǐ diǎn huí jiā?","translation":"Во сколько ты идёшь домой?","options":["我五号回家。","我五个回家。","我五点回家。"],"correct":2},{"speaker":"Друг","text":"你几点睡觉？","pinyin":"Nǐ jǐ diǎn shuìjiào?","translation":"Во сколько ты ложишься спать?","options":["我十点睡觉。","我十岁睡觉。","我十个睡觉。"],"correct":0}]}'),
  ('hsk1-08-5', 7, 'game', '{"type":"match","title":"Знак и смысл","pairs":[["目 + 垂","睡"],["囗 + 口","回"],["上午","утро"],["下午","день"]]}'),
  ('hsk1-08-5', 8, 'write', '{"title":"Пропись: движение","items":[{"hanzi":"回","pinyin":"huí","m":"возвращаться","hint":"рамка, внутри ещё одна рамка"},{"hanzi":"去","pinyin":"qù","m":"идти","hint":"сверху 土, снизу 厶"},{"hanzi":"来","pinyin":"lái","m":"приходить","hint":"сверху 一, потом 木 с двумя точками"}]}'),
  ('hsk1-08-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «В десять я ложусь спать»?","options":["十我点睡觉。","我十点睡觉。","我睡觉十点。"],"correct":1},{"q":"Какой глагол значит «вернуться»?","options":["来","去","回"],"correct":2},{"q":"上午, 中午 и 下午 стоят перед глаголом.","tf":true}]}'),
  ('hsk1-08-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 8","text":"Части дня, глаголы 来, 去, 回, 能, работа и сон, обращения 先生 и 小姐."}'),
  ('hsk1-08-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"上午","options":["zhōngwǔ","xiàwǔ","shàngwǔ"],"correct":2},{"say":"下午三点","options":["xiàwǔ sān diǎn","shàngwǔ sān diǎn"],"correct":0},{"say":"我回家","options":["wǒ huí jiā","wǒ qù jiā"],"correct":0},{"say":"不去","options":["bù qù","bú qù"],"correct":1},{"say":"你能来吗","options":["nǐ huì lái ma","nǐ néng lái ma"],"correct":1},{"say":"王先生","options":["Wáng xiǎojiě","Wáng xiānsheng"],"correct":1}]}'),
  ('hsk1-08-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🌅","options":["下午","上午","中午"],"correct":1},{"emoji":"🚶","options":["来","去","回"],"correct":1},{"emoji":"😴","options":["工作","睡觉","能"],"correct":1},{"emoji":"💼","options":["先生","工作","睡觉"],"correct":1}]}'),
  ('hsk1-08-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["上午","утро"],["中午","полдень"],["下午","день"],["时候","время"],["来","приходить"],["去","идти"],["回","возвращаться"],["能","мочь"],["睡觉","спать"],["工作","работать"]]}'),
  ('hsk1-08-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Днём я иду домой»?","options":["我下午回家。","我回下午家。","下午回我家。"],"correct":0},{"q":"Как читается 不去?","options":["bú qù","bǔ qù","bù qù"],"correct":0},{"q":"Как спросить «Когда?»","options":["什么时候？","时候什么？","几时候？"],"correct":0},{"q":"Перед глаголом ставят слово времени.","tf":true},{"q":"Как сказать «Ты можешь прийти?»","options":["你能来吗？","吗你能来？","你来能吗？"],"correct":0},{"q":"Что значит 先生?","options":["госпожа","учитель","господин"],"correct":2},{"q":"После 去 нужен предлог.","tf":false},{"q":"Как сказать «В десять я ложусь спать»?","options":["我睡觉十点。","我十点睡觉。","十点我睡。"],"correct":1},{"q":"Как читается 不来?","options":["bù lái","bǔ lái","bú lái"],"correct":0},{"q":"Что значит 工作?","options":["работать","возвращаться","спать"],"correct":0}]}'),
  ('hsk1-08-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","去","学校"],"hint":"«Я иду в школу.»"},{"answer":["我","回","家"],"hint":"«Я иду домой.»"},{"answer":["下午","三","点","我","工作"],"hint":"«В три часа дня я работаю.»"},{"answer":["你","能","来","吗"],"hint":"«Ты можешь прийти?»"}]}'),
  ('hsk1-08-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我去在学校。","context":"«Я иду в школу»","options":["我去学校。","我在去学校。","我去的学校。"],"correct":0},{"buggyText":"我回去家。","context":"«Я иду домой»","options":["我回家。","我家回。","我回在家。"],"correct":0},{"buggyText":"你来能吗？","context":"«Ты можешь прийти?»","options":["你来吗能？","你能来吗？","能你来吗？"],"correct":1}]}'),
  ('hsk1-08-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你明天来学校吗？","pinyin":"Nǐ míngtiān lái xuéxiào ma?","translation":"Ты завтра придёшь в школу?","options":["来，下午三点。","来，是下午。","不是，我来。"],"correct":0},{"speaker":"Друг","text":"好，明天见！","pinyin":"Hǎo, míngtiān jiàn!","translation":"Хорошо, до завтра!","options":["对不起！","明天见！","没关系。"],"correct":1}]}'),
  ('hsk1-08-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"午","pinyin":"wǔ","m":"полдень","hint":"откидная, две горизонтали, вертикаль"},{"hanzi":"回","pinyin":"huí","m":"возвращаться","hint":"рамка в рамке"},{"hanzi":"来","pinyin":"lái","m":"приходить","hint":"木 с чертой"}]}'),
  ('hsk1-08-6', 10, 'recall', '{"words":[{"hanzi":"上午","pinyin":"shàngwǔ","m":"утро"},{"hanzi":"中午","pinyin":"zhōngwǔ","m":"полдень"},{"hanzi":"下午","pinyin":"xiàwǔ","m":"день после полудня"},{"hanzi":"时候","pinyin":"shíhou","m":"время"},{"hanzi":"来","pinyin":"lái","m":"приходить"},{"hanzi":"去","pinyin":"qù","m":"идти"},{"hanzi":"回","pinyin":"huí","m":"возвращаться"},{"hanzi":"能","pinyin":"néng","m":"мочь"},{"hanzi":"睡觉","pinyin":"shuìjiào","m":"спать"},{"hanzi":"工作","pinyin":"gōngzuò","m":"работать"},{"hanzi":"先生","pinyin":"xiānsheng","m":"господин"},{"hanzi":"小姐","pinyin":"xiǎojiě","m":"госпожа"}],"tf":[{"zh":"我去在学校。","py":"wǒ qù zài xuéxiào.","m":"Я иду в школу.","ok":false,"explain":"Правильно: 我去学校."},{"zh":"我回家。","py":"wǒ huí jiā.","m":"Я иду домой.","ok":true}],"sentences":[{"zh":"我下午去学校。","tokens":["我","下午","去","学校"],"m":"Днём я иду в школу."},{"zh":"你能来吗？","tokens":["你","能","来","吗"],"m":"Ты можешь прийти?"},{"zh":"我十点睡觉。","tokens":["我","十","点","睡觉"],"m":"В десять я ложусь спать."}]}'),
  ('hsk1-09-1', 1, 'fact', '{"emoji":"🍚","title":"Обед — это «рис плюс блюда»","text":"У китайцев еда делится на две части: 饭 «основа» (рис, лапша) и 菜 «блюда к ней» (овощи, мясо). Поэтому 米饭 — «варёный рис», 吃饭 — буквально «есть основу», то есть «обедать», а 菜 — и «овощи», и «блюдо». Знаки 吃 «есть» и 喝 «пить» оба начинаются с 口 «рот»."}'),
  ('hsk1-09-1', 2, 'words', '{"title":"Еда и глаголы","items":[{"hanzi":"吃","pinyin":"chī","m":"есть","emoji":"😋","ex":{"zh":"我吃米饭。","py":"Wǒ chī mǐfàn.","m":"Я ем рис."}},{"hanzi":"喝","pinyin":"hē","m":"пить","emoji":"🥤","ex":{"zh":"你喝什么？","py":"Nǐ hē shénme?","m":"Что ты пьёшь?"}},{"hanzi":"米饭","pinyin":"mǐfàn","m":"варёный рис","emoji":"🍚","ex":{"zh":"我想吃米饭。","py":"Wǒ xiǎng chī mǐfàn.","m":"Я хочу рис."}},{"hanzi":"菜","pinyin":"cài","m":"овощи, блюдо","emoji":"🥬","ex":{"zh":"这个菜很好。","py":"Zhège cài hěn hǎo.","m":"Это блюдо очень хорошее."}}]}'),
  ('hsk1-09-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🍚","options":["吃","菜","米饭"],"correct":2},{"emoji":"🥬","options":["米饭","喝","菜"],"correct":2},{"emoji":"😋","options":["吃","菜","喝"],"correct":0},{"emoji":"🥤","options":["菜","吃","喝"],"correct":2}]}'),
  ('hsk1-09-1', 4, 'theory', '{"title":"吃 и 喝: что с чем","blocks":[{"t":"table","head":["Глагол","Что можно","Пример"],"rows":[["吃 chī","еда: рис, овощи","吃米饭, 吃菜"],["喝 hē","напитки","喝水, 喝茶"]]},{"t":"p","text":"Глагол ставится перед тем, что едят или пьют: 吃米饭, 喝茶. Перепутать глаголы нельзя: воду «не едят»."},{"t":"tip","text":"Оба слога 吃 chī и 喝 hē — в первом тоне: ровный и высокий."}]}'),
  ('hsk1-09-1', 5, 'quiz', '{"title":"Мини-тест: еда","qs":[{"q":"Какой глагол сочетается с 米饭?","options":["吃","喝","买"],"correct":0},{"q":"喝 используют с едой, например 喝米饭.","tf":false,"explain":"С едой нужен 吃."},{"q":"Какой ключ в знаках 吃 и 喝?","options":["亻","口","女"],"correct":1}]}'),
  ('hsk1-09-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["吃","есть"],["喝","пить"],["米饭","варёный рис"],["菜","овощи, блюдо"],["吃米饭","есть рис"]]}'),
  ('hsk1-09-1', 7, 'game', '{"type":"listen","title":"Слушаем: еда и глаголы","items":[{"say":"吃","options":["chī","chǐ","chí"],"correct":0},{"say":"喝","options":["hè","hé","hē"],"correct":2},{"say":"米饭","options":["mífàn","mǐfàn","mǐfān"],"correct":1},{"say":"菜","options":["cài","cāi","cǎi"],"correct":0},{"say":"我吃米饭","options":["wǒ chī mǐfàn","wǒ hē mǐfàn"],"correct":0}]}'),
  ('hsk1-09-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","吃","米饭"],"hint":"«Я ем рис.»"},{"answer":["我","吃","菜"],"hint":"«Я ем овощи.»"},{"answer":["你","喝","什么"],"hint":"«Что ты пьёшь?»"}]}'),
  ('hsk1-09-1', 9, 'write', '{"title":"Пропись: еда","items":[{"hanzi":"吃","pinyin":"chī","m":"есть","hint":"слева 口, справа 乞"},{"hanzi":"喝","pinyin":"hē","m":"пить","hint":"слева 口, справа 曷"},{"hanzi":"菜","pinyin":"cài","m":"овощи","hint":"сверху 艹, снизу 采"}]}'),
  ('hsk1-09-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 菜?","options":["рис","овощи, блюдо","пить"],"correct":1},{"q":"Как читается 吃?","options":["chǐ","chí","chī"],"correct":2},{"q":"Как сказать «Я ем рис»?","options":["我喝米饭。","我吃米饭。","米饭吃我。"],"correct":1},{"q":"米饭 — это варёный рис.","tf":true},{"q":"Что значит 喝?","options":["есть","покупать","пить"],"correct":2}]}'),
  ('hsk1-09-2', 1, 'fact', '{"emoji":"💧","title":"Знак 水 — это ручей","text":"Иероглиф 水 «вода» нарисован как течение с брызгами по бокам. В сложных знаках у воды есть сокращённая форма 氵 (три капли слева). Вы встречали её в 汉. А 茶 «чай» — это 艹 «трава» над 人 «человек» и 木 «дерево»: человек среди листьев и ветвей."}'),
  ('hsk1-09-2', 2, 'words', '{"title":"Два напитка","items":[{"hanzi":"水","pinyin":"shuǐ","m":"вода","emoji":"💧","ex":{"zh":"我喝水。","py":"Wǒ hē shuǐ.","m":"Я пью воду."}},{"hanzi":"茶","pinyin":"chá","m":"чай","emoji":"🍵","ex":{"zh":"你喝茶吗？","py":"Nǐ hē chá ma?","m":"Ты пьёшь чай?"}}]}'),
  ('hsk1-09-2', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"💧","options":["水","茶","喝"],"correct":0},{"emoji":"🍵","options":["茶","水","菜"],"correct":0}]}'),
  ('hsk1-09-2', 4, 'theory', '{"title":"Вопросы с 什么 и с 吗","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["你吃什么？","我吃米饭。"],["你喝什么？","我喝水。"],["你喝茶吗？","喝。 / 不喝。"]]},{"t":"p","text":"Чтобы ответить «да» или «нет», повторяют глагол: 喝 или 不喝. Вспомните: 什么 встаёт на место ответа и 吗 не нужен."},{"t":"tip","text":"И 吃, и 喝 в первом тоне, поэтому 不 остаётся bù: 不吃 bù chī, 不喝 bù hē."}]}'),
  ('hsk1-09-2', 5, 'game', '{"type":"build","title":"Соберите предложение","items":[{"answer":["你","喝","什么"],"hint":"«Что ты пьёшь?»"},{"answer":["我","喝","茶"],"hint":"«Я пью чай.»"},{"answer":["你","喝","茶","吗"],"hint":"«Ты пьёшь чай?»"},{"answer":["我","不","喝","水"],"hint":"«Я не пью воду.»"}]}'),
  ('hsk1-09-2', 6, 'quiz', '{"title":"Мини-тест: ответы","qs":[{"q":"Как ответить «нет» на 你喝茶吗？","options":["不喝。","不是。","没有。"],"correct":0},{"q":"Как читается 不喝?","options":["bǔ hē","bù hē","bú hē"],"correct":1},{"q":"К вопросу 你喝什么？ добавляют 吗.","tf":false,"explain":"Вопросительное слово 什么 заменяет 吗."}]}'),
  ('hsk1-09-2', 7, 'theory', '{"title":"Перечисляем: 和","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["米饭和菜","рис и овощи"],["水和茶","вода и чай"],["我吃米饭和菜。","Я ем рис и овощи."]]},{"t":"p","text":"和 соединяет предметы, а не действия. Два глагола одним 和 не связывают."}]}'),
  ('hsk1-09-2', 8, 'game', '{"type":"listen","title":"Слушаем: вода и чай","items":[{"say":"水","options":["shuí","shuǐ","shuì"],"correct":1},{"say":"茶","options":["chǎ","chá","chà"],"correct":1},{"say":"不喝","options":["bú hē","bù hē"],"correct":1},{"say":"你喝茶吗","options":["nǐ hē chá ma","nǐ chī chá ma"],"correct":0},{"say":"我喝水","options":["wǒ hē shuǐ","wǒ chī shuǐ"],"correct":0}]}'),
  ('hsk1-09-2', 9, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["水","вода"],["茶","чай"],["不喝","не пью"],["你喝什么？","Что ты пьёшь?"],["米饭和菜","рис и овощи"]]}'),
  ('hsk1-09-2', 10, 'game', '{"type":"bughunt","title":"Китайский детектив: еда и напитки","cases":[{"buggyText":"我吃水。","context":"«Я пью воду»","options":["我喝水。","喝我水。","我水喝。"],"correct":0,"explain":"Воду пьют, а не едят."},{"buggyText":"你喝什么吗？","context":"«Что ты пьёшь?»","options":["你吗喝什么？","什么你喝吗？","你喝什么？"],"correct":2},{"buggyText":"我吃米饭吃菜。","context":"«Я ем рис и овощи»","options":["我吃饭菜和。","我吃米饭和菜。","我吃米饭有菜。"],"correct":1}]}'),
  ('hsk1-09-2', 11, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «чай»?","options":["水","菜","茶"],"correct":2},{"q":"Как сказать «Я пью воду»?","options":["我喝水。","我吃水。","水我吃。"],"correct":0},{"q":"喝 и 吃 читаются в первом тоне.","tf":true},{"q":"Как спросить «Ты пьёшь чай?»","options":["你喝茶吗？","你吗喝茶？","你茶喝吗？"],"correct":0},{"q":"Что значит 水?","options":["рис","чай","вода"],"correct":2}]}'),
  ('hsk1-09-3', 1, 'fact', '{"emoji":"🍎","title":"Яблоко — пожелание мира","text":"苹果 píngguǒ звучит почти как 平安 píng''ān «мир и безопасность». Поэтому в канун Рождества китайцы дарят друг другу яблоки (平安夜 «ночь мира»). 水果 «фрукты» — буквально «водяной плод». А 饭店 — «ресторан», а часто и «большой отель»."}'),
  ('hsk1-09-3', 2, 'words', '{"title":"Четыре слова","items":[{"hanzi":"苹果","pinyin":"píngguǒ","m":"яблоко","emoji":"🍎","ex":{"zh":"我吃苹果。","py":"Wǒ chī píngguǒ.","m":"Я ем яблоко."}},{"hanzi":"水果","pinyin":"shuǐguǒ","m":"фрукты","emoji":"🍇","ex":{"zh":"我喜欢水果。","py":"Wǒ xǐhuan shuǐguǒ.","m":"Я люблю фрукты."}},{"hanzi":"饭店","pinyin":"fàndiàn","m":"ресторан, отель","emoji":"🏨","ex":{"zh":"我们去饭店。","py":"Wǒmen qù fàndiàn.","m":"Мы идём в ресторан."}},{"hanzi":"杯子","pinyin":"bēizi","m":"стакан, чашка","emoji":"🥛","ex":{"zh":"一个杯子","py":"yí gè bēizi","m":"один стакан"}}]}'),
  ('hsk1-09-3', 3, 'game', '{"type":"listen","title":"Слушаем: фрукты и ресторан","items":[{"say":"苹果","options":["píngguǒ","píngguò","pínggǔo"],"correct":0},{"say":"水果","options":["shuǐguó","shuǐguǒ","shuíguǒ"],"correct":1},{"say":"饭店","options":["fāndiàn","fàndiàn","fàndián"],"correct":1},{"say":"杯子","options":["bēizi","běizi","bèizi"],"correct":0},{"say":"我们去饭店","options":["wǒmen qù fàndiàn","wǒmen huí fàndiàn"],"correct":0}]}'),
  ('hsk1-09-3', 4, 'game', '{"type":"tone_visualizer","initialTone":2,"title":"Тренажёр голоса: повторите «píng» (2 тон)"}'),
  ('hsk1-09-3', 5, 'theory', '{"title":"Измерение напитков: 一杯","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["一杯水","стакан воды"],["一杯茶","чашка чая"],["一个苹果","одно яблоко"]]},{"t":"p","text":"Для жидкостей используют 杯 «стакан, чашка» вместо 个: 一杯茶. Перед 杯 четвёртого тона 一 читается yì: yì bēi (杯 в 1 тоне)."},{"t":"tip","text":"Для фруктов подходит 个: 一个苹果 yí gè píngguǒ."}]}'),
  ('hsk1-09-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🍎","options":["苹果","杯子","饭店"],"correct":0},{"emoji":"🍇","options":["水果","苹果","茶"],"correct":0},{"emoji":"🏨","options":["饭店","水果","杯子"],"correct":0},{"emoji":"🥛","options":["菜","水","杯子"],"correct":2}]}'),
  ('hsk1-09-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["苹果","яблоко"],["水果","фрукты"],["饭店","ресторан, отель"],["杯子","стакан, чашка"],["一杯茶","чашка чая"]]}'),
  ('hsk1-09-3', 8, 'game', '{"type":"chatsim","title":"В ресторане","messages":[{"speaker":"Официант","text":"你们喝什么？","pinyin":"Nǐmen hē shénme?","translation":"Что вы будете пить?","options":["我喝一杯茶。","我茶是一杯。","我吃一杯茶。"],"correct":0,"explain":"Для жидкости — 杯."},{"speaker":"Официант","text":"你吃什么？","pinyin":"Nǐ chī shénme?","translation":"Что вы будете есть?","options":["我吃米饭和菜。","我杯子米饭。","我喝米饭。"],"correct":0},{"speaker":"Официант","text":"你吃水果吗？","pinyin":"Nǐ chī shuǐguǒ ma?","translation":"Вы будете фрукты?","options":["不喝，我是水果。","我没有水果的。","不吃，我吃菜。"],"correct":2}]}'),
  ('hsk1-09-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","喝","一","杯","水"],"hint":"«Я пью стакан воды.»"},{"answer":["我","吃","一个","苹果"],"hint":"«Я ем яблоко.»"},{"answer":["我们","去","饭店"],"hint":"«Мы идём в ресторан.»"}]}'),
  ('hsk1-09-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 水果?","options":["яблоко","фрукты","вода"],"correct":1},{"q":"Какое слово подходит для «стакан»?","options":["饭店","苹果","杯子"],"correct":2},{"q":"饭店 может значить и «ресторан», и «отель».","tf":true},{"q":"Как читается 苹果?","options":["pínggǔo","píngguǒ","píngguò"],"correct":1},{"q":"Как сказать «чашка чая»?","options":["一杯茶","一个茶","一茶杯"],"correct":0}]}'),
  ('hsk1-09-4', 1, 'fact', '{"emoji":"🍽️","title":"Мамин вопрос: «Что ты будешь есть?»","text":"Китайские мамы кормят детей без пауз. Мама Ли Мина предлагает и еду, и напитки, и фрукты. Читайте, как он выбирает."}'),
  ('hsk1-09-4', 2, 'text', '{"title":"Ужин дома","lines":[{"zh":"妈妈：李明，你吃什么？","py":"Māma: Lǐ Míng, nǐ chī shénme?","m":"Мама: Ли Мин, что ты будешь есть?"},{"zh":"李明：我吃米饭和菜。","py":"Lǐ Míng: Wǒ chī mǐfàn hé cài.","m":"Ли Мин: Я буду рис и овощи."},{"zh":"妈妈：你喝什么？","py":"Māma: Nǐ hē shénme?","m":"Мама: Что ты будешь пить?"},{"zh":"李明：我喝水。","py":"Lǐ Míng: Wǒ hē shuǐ.","m":"Ли Мин: Я буду воду."},{"zh":"妈妈：你喝茶吗？","py":"Māma: Nǐ hē chá ma?","m":"Мама: Ты будешь чай?"},{"zh":"李明：不喝。","py":"Lǐ Míng: Bù hē.","m":"Ли Мин: Не буду."},{"zh":"妈妈：吃苹果吗？","py":"Māma: Chī píngguǒ ma?","m":"Мама: Будешь яблоко?"},{"zh":"李明：吃！谢谢妈妈！","py":"Lǐ Míng: Chī! Xièxie māma!","m":"Ли Мин: Буду! Спасибо, мама!"}],"qs":[{"q":"Что ест Ли Мин?","options":["только рис","яблоко и чай","рис и овощи"],"correct":2},{"q":"Ли Мин пьёт чай.","tf":false,"explain":"Он говорит 不喝."},{"q":"Что он пьёт?","options":["чай","ничего","воду"],"correct":2},{"q":"Вставьте слово: 你喝___吗？","options":["菜","茶","米饭"],"correct":1},{"q":"Ли Мин соглашается съесть яблоко.","tf":true},{"q":"Как Ли Мин отвечает «да» на вопрос о яблоке?","options":["是","吃","喝"],"correct":1},{"q":"Как Ли Мин благодарит маму?","options":["对不起，妈妈","再见，妈妈","谢谢妈妈"],"correct":2}]}'),
  ('hsk1-09-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我吃米饭和菜","Я ем рис и овощи"],["我喝水","Я пью воду"],["不喝","Не буду пить"],["吃苹果吗？","Будешь яблоко?"],["谢谢妈妈","Спасибо, мама"]]}'),
  ('hsk1-09-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你吃什么","options":["nǐ chī shénme","nǐ hē shénme"],"correct":0},{"say":"我喝水","options":["wǒ chī shuǐ","wǒ hē shuǐ"],"correct":1},{"say":"不喝","options":["bù hē","bú hē"],"correct":0},{"say":"吃苹果吗","options":["chī píngguǒ ma","hē píngguǒ ma"],"correct":0}]}'),
  ('hsk1-09-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: за столом","cases":[{"buggyText":"我吃茶。","context":"Сказать «Я пью чай»","options":["我茶吃。","吃我茶。","我喝茶。"],"correct":2},{"buggyText":"我吃米饭菜。","context":"«Я ем рис и овощи»","options":["我吃米饭有菜。","我米饭和菜吃。","我吃米饭和菜。"],"correct":2},{"buggyText":"不吃苹果吗？","context":"Спросить «Будешь яблоко?»","options":["吃苹果吗？","吃吗苹果？","苹果吃吗？"],"correct":0}]}'),
  ('hsk1-09-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как отказаться от чая?","options":["没有。","不喝。","不吃。"],"correct":1},{"q":"Как читается 不吃?","options":["bú chī","bù chī","bǔ chī"],"correct":1},{"q":"Мама предлагает три разных блюда или напитка.","tf":true},{"q":"Как сказать «Я пью воду»?","options":["我水喝。","我吃水。","我喝水。"],"correct":2}]}'),
  ('hsk1-09-5', 1, 'fact', '{"emoji":"📋","title":"Составьте меню","text":"Сегодня вы придумываете завтрак и обед, собираете знаки еды из частей и разговариваете с «официантом». Слова глав 1–9."}'),
  ('hsk1-09-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"吃","correctRadicals":["口","乞"],"title":"Пазл: соберите 吃"}'),
  ('hsk1-09-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"饭","radicals":["饣","反","亻"],"correctOrder":["饣","反"],"explain":"Слева «еда» 饣, справа 反."},{"targetHanzi":"果","radicals":["田","木","日"],"correctOrder":["田","木"],"explain":"Плод 田 сверху, дерево 木 снизу."},{"targetHanzi":"茶","radicals":["艹","人","木"],"correctOrder":["艹","人","木"],"explain":"Сверху трава, в середине человек, снизу дерево."}]}'),
  ('hsk1-09-5', 4, 'game', '{"type":"build","title":"Мастерская меню","items":[{"target":"(Завтрак)","answer":["我","吃","苹果"],"hint":"«Я ем яблоко.»"},{"target":"(Завтрак)","answer":["我","喝","一","杯","茶"],"hint":"«Я пью чашку чая.»"},{"target":"(Обед)","answer":["我","吃","米饭","和","菜"],"hint":"«Я ем рис и овощи.»"},{"target":"(Ужин)","answer":["我们","去","饭店"],"hint":"«Мы идём в ресторан.»"}]}'),
  ('hsk1-09-5', 5, 'theory', '{"title":"Меню на день","blocks":[{"t":"table","head":["Время","Фраза"],"rows":[["Утро","上午我喝茶。"],["Полдень","中午我吃米饭和菜。"],["День","下午我吃苹果。"],["Вечер","我们去饭店。"]]}]}'),
  ('hsk1-09-5', 6, 'game', '{"type":"chatsim","title":"В ресторане: сделайте заказ","messages":[{"speaker":"Официант","text":"你吃什么？","pinyin":"Nǐ chī shénme?","translation":"Что вы будете есть?","options":["我吃水。","我吃米饭。","我喝米饭。"],"correct":1},{"speaker":"Официант","text":"你喝什么？","pinyin":"Nǐ hē shénme?","translation":"Что вы будете пить?","options":["我茶是喝。","我吃茶。","我喝茶。"],"correct":2},{"speaker":"Официант","text":"还要什么？","pinyin":"Hái yào shénme?","translation":"Что-нибудь ещё? (还要 «ещё хотите» — новое выражение)","options":["苹果杯子。","我是苹果。","我吃苹果。"],"correct":2}]}'),
  ('hsk1-09-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["口 + 乞","吃"],["饣 + 反","饭"],["田 + 木","果"],["艹 + 人 + 木","茶"]]}'),
  ('hsk1-09-5', 8, 'write', '{"title":"Пропись: вода, чай, плод","items":[{"hanzi":"水","pinyin":"shuǐ","m":"вода","hint":"вертикаль, потом две стороны"},{"hanzi":"茶","pinyin":"chá","m":"чай","hint":"艹 сверху, 人 в середине, 木 снизу"},{"hanzi":"果","pinyin":"guǒ","m":"плод","hint":"田 сверху, 木 снизу"}]}'),
  ('hsk1-09-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Какие части в знаке 饭?","options":["艹 и 木","口 и 乞","饣 и 反"],"correct":2},{"q":"Как сказать «Я пью чашку чая»?","options":["我喝一个茶。","我喝一杯茶。","我吃一杯茶。"],"correct":1},{"q":"Для воды и чая счётное слово — 杯.","tf":true}]}'),
  ('hsk1-09-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 9","text":"Еда, напитки, 吃 и 喝, 一杯 и вопросы за столом."}'),
  ('hsk1-09-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"米饭","options":["mífàn","mǐfān","mǐfàn"],"correct":2},{"say":"我吃菜","options":["wǒ hē cài","wǒ chī cài"],"correct":1},{"say":"喝水","options":["hē shuǐ","chī shuǐ"],"correct":0},{"say":"苹果","options":["píngguò","pínggǔo","píngguǒ"],"correct":2},{"say":"不喝","options":["bù hē","bú hē"],"correct":0},{"say":"我们去饭店","options":["wǒmen huí fàndiàn","wǒmen qù fàndiàn"],"correct":1}]}'),
  ('hsk1-09-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🍚","options":["米饭","水","菜"],"correct":0},{"emoji":"🍵","options":["杯子","水","茶"],"correct":2},{"emoji":"🍎","options":["水果","饭店","苹果"],"correct":2},{"emoji":"🥛","options":["饭店","菜","杯子"],"correct":2}]}'),
  ('hsk1-09-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["吃","есть"],["喝","пить"],["米饭","рис"],["菜","блюдо"],["水","вода"],["茶","чай"],["苹果","яблоко"],["水果","фрукты"],["饭店","ресторан"],["杯子","стакан"]]}'),
  ('hsk1-09-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Я пью чай»?","options":["我喝茶。","我茶喝。","我吃茶。"],"correct":0},{"q":"Как спросить «Что ты ешь?»","options":["什么你吃？","你吃什么吗？","你吃什么？"],"correct":2},{"q":"Как читается 不吃?","options":["bù chī","bǔ chī","bú chī"],"correct":0},{"q":"Воду «едят» с глаголом 吃.","tf":false},{"q":"Как сказать «чашка чая»?","options":["一个茶","杯一茶","一杯茶"],"correct":2},{"q":"Что значит 饭店?","options":["стакан","яблоко","ресторан, отель"],"correct":2},{"q":"和 соединяет предметы, например 米饭和菜.","tf":true},{"q":"Как ответить «нет» на 你喝茶吗？","options":["没有。","不是。","不喝。"],"correct":2},{"q":"Какой ключ у 吃?","options":["女","亻","口"],"correct":2},{"q":"Как сказать «Мы идём в ресторан»?","options":["我们去饭店。","我们饭店去。","我们回饭店。"],"correct":0}]}'),
  ('hsk1-09-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","吃","米饭"],"hint":"«Я ем рис.»"},{"answer":["我","喝","水"],"hint":"«Я пью воду.»"},{"answer":["你","喝","什么"],"hint":"«Что ты пьёшь?»"},{"answer":["我","吃","一个","苹果"],"hint":"«Я ем яблоко.»"}]}'),
  ('hsk1-09-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我吃水。","context":"«Я пью воду»","options":["我喝水。","我水喝。","喝我水。"],"correct":0},{"buggyText":"你吃什么吗？","context":"«Что ты ешь?»","options":["你吃什么？","你吃什么吗？","什么吃你？"],"correct":0},{"buggyText":"我喝一个茶。","context":"«Я пью чашку чая»","options":["我杯一喝茶。","我喝一茶杯。","我喝一杯茶。"],"correct":2}]}'),
  ('hsk1-09-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Официант","text":"你喝什么？","pinyin":"Nǐ hē shénme?","translation":"Что вы будете пить?","options":["我喝茶。","我吃茶。","我茶喝。"],"correct":0},{"speaker":"Официант","text":"你吃什么？","pinyin":"Nǐ chī shénme?","translation":"Что вы будете есть?","options":["我吃米饭和菜。","我吃喝菜。","我喝米饭。"],"correct":0}]}'),
  ('hsk1-09-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"吃","pinyin":"chī","m":"есть","hint":"口 + 乞"},{"hanzi":"水","pinyin":"shuǐ","m":"вода","hint":"вертикаль и брызги"},{"hanzi":"果","pinyin":"guǒ","m":"плод","hint":"田 + 木"}]}'),
  ('hsk1-09-6', 10, 'recall', '{"words":[{"hanzi":"吃","pinyin":"chī","m":"есть"},{"hanzi":"喝","pinyin":"hē","m":"пить"},{"hanzi":"米饭","pinyin":"mǐfàn","m":"рис"},{"hanzi":"菜","pinyin":"cài","m":"блюдо"},{"hanzi":"水","pinyin":"shuǐ","m":"вода"},{"hanzi":"茶","pinyin":"chá","m":"чай"},{"hanzi":"苹果","pinyin":"píngguǒ","m":"яблоко"},{"hanzi":"水果","pinyin":"shuǐguǒ","m":"фрукты"},{"hanzi":"饭店","pinyin":"fàndiàn","m":"ресторан"},{"hanzi":"杯子","pinyin":"bēizi","m":"стакан"}],"tf":[{"zh":"我吃水。","py":"wǒ chī shuǐ.","m":"Я пью воду.","ok":false,"explain":"Воду пьют: 我喝水."},{"zh":"我喝一杯茶。","py":"wǒ hē yì bēi chá.","m":"Я пью чашку чая.","ok":true}],"sentences":[{"zh":"我吃米饭和菜。","tokens":["我","吃","米饭","和","菜"],"m":"Я ем рис и овощи."},{"zh":"你喝什么？","tokens":["你","喝","什么"],"m":"Что ты пьёшь?"},{"zh":"我喝一杯茶。","tokens":["我","喝","一杯","茶"],"m":"Я пью чашку чая."}]}'),
  ('hsk1-10-1', 1, 'fact', '{"emoji":"💖","title":"Сердце потерялось","text":"В традиционном 愛 «любовь» посередине есть 心 «сердце». В упрощённом 爱 сердце убрали, и по этому поводу китайцы до сих пор шутят: «любовь без сердца». Знак 想 «хотеть, думать» зато сохранил 心 внизу: мысль живёт в сердце. А 请 qǐng — слово вежливости, как «пожалуйста» перед просьбой."}'),
  ('hsk1-10-1', 2, 'words', '{"title":"Четыре слова чувств","items":[{"hanzi":"请","pinyin":"qǐng","m":"просить, пожалуйста","emoji":"🙏","ex":{"zh":"请喝茶。","py":"Qǐng hē chá.","m":"Пожалуйста, выпейте чаю."}},{"hanzi":"想","pinyin":"xiǎng","m":"хотеть, думать","emoji":"💭","ex":{"zh":"我想吃米饭。","py":"Wǒ xiǎng chī mǐfàn.","m":"Я хочу рис."}},{"hanzi":"喜欢","pinyin":"xǐhuan","m":"любить, нравиться","emoji":"😍","ex":{"zh":"我喜欢茶。","py":"Wǒ xǐhuan chá.","m":"Я люблю чай."}},{"hanzi":"爱","pinyin":"ài","m":"любить (сильно)","emoji":"❤️","ex":{"zh":"我爱妈妈。","py":"Wǒ ài māma.","m":"Я люблю маму."}}]}'),
  ('hsk1-10-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🙏","options":["请","想","喜欢"],"correct":0},{"emoji":"💭","options":["请","想","爱"],"correct":1},{"emoji":"😍","options":["爱","喜欢","请"],"correct":1},{"emoji":"❤️","options":["爱","想","请"],"correct":0}]}'),
  ('hsk1-10-1', 4, 'theory', '{"title":"喜欢 или 爱?","blocks":[{"t":"table","head":["Слово","Сила","Пример"],"rows":[["喜欢 xǐhuan","нравится, люблю (вещи, занятия)","我喜欢茶。"],["爱 ài","люблю (людей, родину)","我爱妈妈。"],["想 xiǎng","хочу (что-то сделать)","我想喝水。"]]},{"t":"p","text":"喜欢 безопасно: им говорят о еде, фильмах, людях. 爱 серьёзнее. 想 ставят перед глаголом: 想吃, 想喝."},{"t":"tip","text":"请 ставят в начале просьбы: 请喝茶 «Пожалуйста, пейте чай»."}]}'),
  ('hsk1-10-1', 5, 'quiz', '{"title":"Мини-тест: чувства","qs":[{"q":"Как сказать «Я хочу есть рис»?","options":["我吃想米饭。","我想吃米饭。","想我吃米饭。"],"correct":1},{"q":"爱 используют для самых тёплых чувств к людям.","tf":true},{"q":"Какое слово ставят перед просьбой?","options":["请","喜欢","爱"],"correct":0}]}'),
  ('hsk1-10-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["请","пожалуйста"],["想","хотеть"],["喜欢","любить, нравиться"],["爱","любить (сильно)"],["我想喝茶","Я хочу чай"]]}'),
  ('hsk1-10-1', 7, 'game', '{"type":"listen","title":"Слушаем: чувства и просьбы","items":[{"say":"请","options":["qíng","qǐng","qìng"],"correct":1},{"say":"想","options":["xiàng","xiǎng","xiāng"],"correct":1},{"say":"喜欢","options":["xíhuan","xìhuan","xǐhuan"],"correct":2},{"say":"爱","options":["āi","ǎi","ài"],"correct":2},{"say":"我想吃米饭","options":["wǒ xiǎng chī mǐfàn","wǒ xǐhuan chī mǐfàn"],"correct":0}]}'),
  ('hsk1-10-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","想","喝","茶"],"hint":"«Я хочу чай.»"},{"answer":["我","喜欢","苹果"],"hint":"«Я люблю яблоки.»"},{"answer":["我","爱","妈妈"],"hint":"«Я люблю маму.»"}]}'),
  ('hsk1-10-1', 9, 'write', '{"title":"Пропись: чувства","items":[{"hanzi":"想","pinyin":"xiǎng","m":"хотеть","hint":"сверху 相, внизу 心"},{"hanzi":"爱","pinyin":"ài","m":"любить","hint":"сверху 爫, внизу 友"},{"hanzi":"请","pinyin":"qǐng","m":"просить","hint":"слева 讠, справа 青"}]}'),
  ('hsk1-10-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 请?","options":["любить","пожалуйста, просить","хотеть"],"correct":1},{"q":"Как читается 喜欢?","options":["xìhuan","xǐhuan","xíhuan"],"correct":1},{"q":"Как сказать «Я люблю маму»?","options":["我喜欢爱妈妈。","我爱妈妈。","妈妈我爱是。"],"correct":1},{"q":"想 ставится перед глаголом.","tf":true},{"q":"Какой ключ в знаке 想 внизу?","options":["女","口","心"],"correct":2}]}'),
  ('hsk1-10-2', 1, 'fact', '{"emoji":"🧩","title":"Три маленьких помощника","text":"Частица 呢 сокращает вопрос: вместо «А ты что будешь?» хватает 你呢？ Слово 都 «все» ставится перед глаголом и делает фразу общей. А 太 «слишком» вместе с 了 даёт эмоцию: 太好了！ «Как здорово!»"}'),
  ('hsk1-10-2', 2, 'words', '{"title":"Три маленьких слова","items":[{"hanzi":"呢","pinyin":"ne","m":"а ты? а как насчёт…","emoji":"🔄","ex":{"zh":"我喝茶，你呢？","py":"Wǒ hē chá, nǐ ne?","m":"Я пью чай, а ты?"}},{"hanzi":"都","pinyin":"dōu","m":"все, всё","emoji":"👥","ex":{"zh":"我们都喝茶。","py":"Wǒmen dōu hē chá.","m":"Мы все пьём чай."}},{"hanzi":"太","pinyin":"tài","m":"слишком, очень","emoji":"💥","ex":{"zh":"太好了！","py":"Tài hǎo le!","m":"Как здорово!"}}]}'),
  ('hsk1-10-2', 3, 'theory', '{"title":"Частица 呢: «а ты?»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我吃米饭，你呢？","Я ем рис, а ты?"],["我很好，你呢？","У меня всё хорошо, а у тебя?"],["他呢？","А он?"]]},{"t":"p","text":"呢 ставится в конце и повторяет предыдущую тему вопроса. Без исходного вопроса его не используют."}]}'),
  ('hsk1-10-2', 4, 'game', '{"type":"build","title":"Соберите фразу с 呢","items":[{"answer":["我","喝","茶","，","你","呢"],"hint":"«Я пью чай, а ты?»"},{"answer":["我","很","好","，","你","呢"],"hint":"«Я в порядке, а ты?»"},{"answer":["他","呢"],"hint":"«А он?»"}]}'),
  ('hsk1-10-2', 5, 'quiz', '{"title":"Мини-тест: 呢 и 都","qs":[{"q":"Как спросить «А ты?» после своей реплики?","options":["你呢？","你吗？","你什么？"],"correct":0},{"q":"呢 произносится без тона.","tf":true},{"q":"Где стоит 都?","options":["перед глаголом","после глагола","в конце фразы"],"correct":0}]}'),
  ('hsk1-10-2', 6, 'theory', '{"title":"都 «все» и 太 «слишком»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我们都是学生。","Мы все студенты."],["他们都喝茶。","Они все пьют чай."],["太多了！","Слишком много!"],["太好了！","Как здорово!"]]},{"t":"p","text":"都 ставится перед глаголом и после подлежащего. 太…了 — шаблон: 太 перед прилагательным, 了 в конце."},{"t":"tip","text":"Не говорите 太好 без 了 в таких восклицаниях: звучит неполно."}]}'),
  ('hsk1-10-2', 7, 'game', '{"type":"listen","title":"Слушаем: 呢, 都, 太","items":[{"say":"你呢","options":["nǐ ne","nǐ ma"],"correct":0},{"say":"我们都喝茶","options":["wǒmen dōu hē chá","wǒmen dōu chī chá"],"correct":0},{"say":"太好了","options":["tài hǎo le","tǎi hǎo le"],"correct":0},{"say":"太多了","options":["tài shǎo le","tài duō le"],"correct":1},{"say":"都","options":["dōu","dóu","dǒu"],"correct":0}]}'),
  ('hsk1-10-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["呢","а ты?"],["都","все"],["太","слишком"],["太好了","как здорово"],["我们都喝茶","мы все пьём чай"]]}'),
  ('hsk1-10-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: 呢, 都, 太","cases":[{"buggyText":"我们喝都茶。","context":"«Мы все пьём чай»","options":["我们都喝茶。","都我们喝茶。","我们喝茶都。"],"correct":0,"explain":"都 перед глаголом."},{"buggyText":"太好。","context":"«Как здорово!»","options":["太好了！","太是好！","太好吗！"],"correct":0},{"buggyText":"我喝茶，你吗？","context":"«Я пью чай, а ты?»","options":["我喝茶，你呢？","我喝茶，你什么？","我喝茶，你好？"],"correct":0}]}'),
  ('hsk1-10-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 都?","options":["слишком","а ты","все"],"correct":2},{"q":"Как сказать «Мы все студенты»?","options":["都我们是学生。","我们是都学生。","我们都是学生。"],"correct":2},{"q":"太好了 значит «Как здорово!»","tf":true},{"q":"Как читается 太?","options":["tài","tāi","tǎi"],"correct":0},{"q":"Для чего служит 呢?","options":["для числа","для вопроса «а ты?»","для отрицания"],"correct":1}]}'),
  ('hsk1-10-3', 1, 'fact', '{"emoji":"🔎","title":"Слово «как» в двух ролях","text":"Китайцы различают «как это?» и «каким образом?». 怎么样 zěnmeyàng спрашивает про качество («как тебе это?»), а 怎么 zěnme — про способ («как это сделать, сказать?»). И ещё одно полезное слово: 一点儿 yìdiǎnr «немного»: 我会说一点儿汉语."}'),
  ('hsk1-10-3', 2, 'words', '{"title":"Три слова","items":[{"hanzi":"怎么样","pinyin":"zěnmeyàng","m":"как, каково","emoji":"❓","ex":{"zh":"这个菜怎么样？","py":"Zhège cài zěnmeyàng?","m":"Как это блюдо?"}},{"hanzi":"怎么","pinyin":"zěnme","m":"как (каким образом)","emoji":"🛠️","ex":{"zh":"汉语怎么说？","py":"Hànyǔ zěnme shuō?","m":"Как это сказать по-китайски?"}},{"hanzi":"一点儿","pinyin":"yìdiǎnr","m":"немного","emoji":"🤏","ex":{"zh":"我会说一点儿汉语。","py":"Wǒ huì shuō yìdiǎnr Hànyǔ.","m":"Я говорю немного по-китайски."}}]}'),
  ('hsk1-10-3', 3, 'game', '{"type":"listen","title":"Слушаем: как?","items":[{"say":"怎么样","options":["zěnmeyàng","zěnmeyǎng","zénmeyàng"],"correct":0},{"say":"怎么","options":["zénme","zěnme","zèmne"],"correct":1},{"say":"一点儿","options":["yǐdiǎnr","yìdiǎnr","yīdiǎnr"],"correct":1,"explain":"Перед 3 тоном 一 читается yì."},{"say":"汉语怎么说","options":["Hànyǔ zěnme shuō","Hànyǔ zěnmeyàng shuō"],"correct":0},{"say":"这个菜怎么样","options":["zhège cài zěnme shuō","zhège cài zěnmeyàng"],"correct":1}]}'),
  ('hsk1-10-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «zěn» (3 тон)"}'),
  ('hsk1-10-3', 5, 'theory', '{"title":"怎么样 и 怎么","blocks":[{"t":"table","head":["Слово","О чём спрашивает","Пример"],"rows":[["怎么样","качество, оценка","你好吗？ → 你怎么样？"],["怎么","способ действия","怎么说？ «Как сказать?»"]]},{"t":"p","text":"怎么样 часто ставится в конце: 这个菜怎么样？ А 怎么 перед глаголом: 汉语怎么说？ 怎么写？"},{"t":"tip","text":"一点儿 стоит перед существительным или в конце фразы: 吃一点儿, 喝一点儿水."}]}'),
  ('hsk1-10-3', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["怎么样","как, каково"],["怎么","как (способ)"],["一点儿","немного"],["汉语怎么说","как сказать по-китайски"],["我会说一点儿","я говорю немного"]]}'),
  ('hsk1-10-3', 7, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🤏","options":["怎么","太","一点儿"],"correct":2},{"emoji":"🛠️","options":["一点儿","怎么样","怎么"],"correct":2},{"emoji":"❓","options":["怎么样","怎么","一点儿"],"correct":0}]}'),
  ('hsk1-10-3', 8, 'game', '{"type":"chatsim","title":"WeChat: как сказать?","messages":[{"speaker":"Друг","text":"这个菜怎么样？","pinyin":"Zhège cài zěnmeyàng?","translation":"Как тебе это блюдо?","options":["很好，太好了！","很是菜。","我怎么样。"],"correct":0},{"speaker":"Друг","text":"你会说汉语吗？","pinyin":"Nǐ huì shuō Hànyǔ ma?","translation":"Ты говоришь по-китайски?","options":["会，我会说一点儿。","我怎么说。","不是，我汉语。"],"correct":0},{"speaker":"Друг","text":"「谢谢」汉语怎么说？","pinyin":"“Thanks” Hànyǔ zěnme shuō?","translation":"Как сказать «спасибо» по-китайски?","options":["谢谢。","怎么样。","不客气。"],"correct":0,"explain":"Ответ — само слово: 谢谢."}]}'),
  ('hsk1-10-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["这个","菜","怎么样"],"hint":"«Как тебе это блюдо?»"},{"answer":["汉语","怎么","说"],"hint":"«Как сказать по-китайски?»"},{"answer":["我","会","说","一点儿","汉语"],"hint":"«Я говорю немного по-китайски.»"}]}'),
  ('hsk1-10-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как спросить «Как тебе это блюдо?»","options":["这个菜怎么样？","这个菜怎么？","这个菜怎么吗？"],"correct":0},{"q":"Как читается 一点儿?","options":["yǐdiǎnr","yīdiǎnr","yìdiǎnr"],"correct":2},{"q":"怎么 спрашивает про способ действия.","tf":true},{"q":"Как сказать «немного»?","options":["一点儿","很","太"],"correct":0},{"q":"Какая фраза значит «Как сказать по-китайски?»","options":["汉语说怎么？","汉语怎么说？","怎么汉语说？"],"correct":1}]}'),
  ('hsk1-10-4', 1, 'fact', '{"emoji":"🍜","title":"Как заказывают в Китае","text":"В ресторане меню читают всем столом, а заказ делает тот, кто «хозяин». Сегодня у нас Анна и Ли Мин, а у стола стоит официант."}'),
  ('hsk1-10-4', 2, 'text', '{"title":"В ресторане","lines":[{"zh":"服务员：你们好！你们想吃什么？","py":"Fúwùyuán: Nǐmen hǎo! Nǐmen xiǎng chī shénme?","m":"Официант: Здравствуйте! Что вы хотите?"},{"zh":"李明：我想吃米饭和菜。安娜，你呢？","py":"Lǐ Míng: Wǒ xiǎng chī mǐfàn hé cài. Ānnà, nǐ ne?","m":"Ли Мин: Я хочу рис и овощи. Анна, а ты?"},{"zh":"安娜：我想吃一点儿菜。","py":"Ānnà: Wǒ xiǎng chī yìdiǎnr cài.","m":"Анна: Я хочу немного овощей."},{"zh":"服务员：你们想喝什么？","py":"Fúwùyuán: Nǐmen xiǎng hē shénme?","m":"Официант: Что хотите пить?"},{"zh":"李明：我们都想喝茶。","py":"Lǐ Míng: Wǒmen dōu xiǎng hē chá.","m":"Ли Мин: Мы оба хотим чай."},{"zh":"安娜：这个菜怎么样？","py":"Ānnà: Zhège cài zěnmeyàng?","m":"Анна: Как это блюдо?"},{"zh":"服务员：很好。","py":"Fúwùyuán: Hěn hǎo.","m":"Официант: Очень хорошее."},{"zh":"安娜：太好了！谢谢！","py":"Ānnà: Tài hǎo le! Xièxie!","m":"Анна: Как здорово! Спасибо!"}],"qs":[{"q":"Что хочет Ли Мин?","options":["чай и яблоко","только воду","рис и овощи"],"correct":2},{"q":"Что хочет Анна?","options":["много риса","немного овощей","яблоко"],"correct":1},{"q":"Анна и Ли Мин хотят разные напитки.","tf":false,"explain":"Они оба хотят чай."},{"q":"Вставьте слово: 我们___想喝茶。","options":["太","都","也"],"correct":1},{"q":"Официант говорит, что блюдо очень хорошее.","tf":true},{"q":"Что значит 你呢？","options":["ты хочешь?","кто ты?","а ты?"],"correct":2},{"q":"Какое восклицание произносит Анна?","options":["太好了","太多了","不客气"],"correct":0}]}'),
  ('hsk1-10-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["你们想吃什么？","Что вы хотите?"],["你呢？","А ты?"],["我们都想喝茶","Мы оба хотим чай"],["这个菜怎么样？","Как это блюдо?"],["太好了","Как здорово"]]}'),
  ('hsk1-10-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你们想吃什么","options":["nǐmen xiǎng chī shénme","nǐmen xiǎng hē shénme"],"correct":0},{"say":"我想吃一点儿菜","options":["wǒ xiǎng chī yìdiǎnr cài","wǒ xiǎng hē yìdiǎnr cài"],"correct":0},{"say":"我们都想喝茶","options":["wǒmen dōu xiǎng chī chá","wǒmen dōu xiǎng hē chá"],"correct":1},{"say":"太好了","options":["tài hǎo le","tài duō le"],"correct":0}]}'),
  ('hsk1-10-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: в ресторане","cases":[{"buggyText":"我们想都喝茶。","context":"«Мы оба хотим чай»","options":["我们都想喝茶。","都我们想喝茶。","我们想喝茶都。"],"correct":0},{"buggyText":"你吃什么呢吗？","context":"«А ты что хочешь?»","options":["你呢吃什么？","你想吃什么？","吃什么你吗？"],"correct":1},{"buggyText":"太好！","context":"«Как здорово!»","options":["太好了！","太好是！","太好吗！"],"correct":0}]}'),
  ('hsk1-10-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я хочу рис»?","options":["我想吃米饭。","我想喝米饭。","想我米饭。"],"correct":0},{"q":"Как читается 想?","options":["xiǎng","xiāng","xiàng"],"correct":0},{"q":"В диалоге Анна заказывает много риса.","tf":false},{"q":"Как сказать «Мы оба хотим чай»?","options":["都我们想喝茶。","我们都想喝茶。","我们想都喝茶。"],"correct":1}]}'),
  ('hsk1-10-5', 1, 'fact', '{"emoji":"🥢","title":"Расскажите о вкусах","text":"Сегодня вы рассказываете, что вам нравится, и спрашиваете у собеседника «а ты?». Слова глав 1–10."}'),
  ('hsk1-10-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"想","correctRadicals":["相","心"],"title":"Пазл: соберите 想"}'),
  ('hsk1-10-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"请","radicals":["讠","青","亻"],"correctOrder":["讠","青"],"explain":"Слева «речь» 讠, справа 青."},{"targetHanzi":"爱","radicals":["爫","友","心"],"correctOrder":["爫","友"],"explain":"Сверху 爫, снизу 友."},{"targetHanzi":"喜","radicals":["十","口","豆"],"correctOrder":["十","口","豆"],"explain":"Сверху 十, потом 口, снизу 豆."}]}'),
  ('hsk1-10-5', 4, 'game', '{"type":"build","title":"Мастерская вкусов","items":[{"target":"(Любимое)","answer":["我","喜欢","茶"],"hint":"«Я люблю чай.»"},{"target":"(Любимое)","answer":["我","喜欢","吃","苹果"],"hint":"«Я люблю есть яблоки.»"},{"target":"(Вопрос)","answer":["你","喜欢","什么","菜"],"hint":"«Какие блюда ты любишь?»"},{"target":"(Ответ)","answer":["我们","都","喜欢","米饭"],"hint":"«Мы все любим рис.»"}]}'),
  ('hsk1-10-5', 5, 'theory', '{"title":"Алгоритм разговора о вкусах","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["1. Вопрос","你喜欢什么？"],["2. Ответ","我喜欢…"],["3. А ты?","你呢？"],["4. Эмоция","太好了！"]]}]}'),
  ('hsk1-10-5', 6, 'game', '{"type":"chatsim","title":"WeChat: вкусы","messages":[{"speaker":"Друг","text":"你喜欢什么菜？","pinyin":"Nǐ xǐhuan shénme cài?","translation":"Какие блюда ты любишь?","options":["我喜欢什么。","我是菜。","我喜欢米饭。"],"correct":2},{"speaker":"Друг","text":"我也喜欢米饭！你喝茶吗？","pinyin":"Wǒ yě xǐhuan mǐfàn! Nǐ hē chá ma?","translation":"Я тоже люблю рис! Ты пьёшь чай? (也 «тоже» — новое слово)","options":["不是，我水。","不喝，我喝水。","不吃，我喝茶。"],"correct":1},{"speaker":"Друг","text":"太好了！我们去饭店吧！","pinyin":"Tài hǎo le! Wǒmen qù fàndiàn ba!","translation":"Как здорово! Пойдём в ресторан! (吧 — новая частица)","options":["不好，我吃。","好，我们去！","好，我去不。"],"correct":1}]}'),
  ('hsk1-10-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["相 + 心","想"],["讠 + 青","请"],["爫 + 友","爱"],["十 + 口 + 豆","喜"]]}'),
  ('hsk1-10-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"太","pinyin":"tài","m":"слишком","hint":"大 и точка внизу"},{"hanzi":"都","pinyin":"dōu","m":"все","hint":"слева 者, справа 阝"},{"hanzi":"喜","pinyin":"xǐ","m":"радость","hint":"сверху 士, потом 口, снизу 豆"}]}'),
  ('hsk1-10-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как спросить «А ты?» про вкус?","options":["你呢？","你吗？","你什么？"],"correct":0},{"q":"Как сказать «Мы все любим рис»?","options":["都我们喜欢米饭。","我们都喜欢米饭。","我们喜欢都米饭。"],"correct":1},{"q":"喜欢 безопаснее 爱 в обычном разговоре.","tf":true}]}'),
  ('hsk1-10-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 10","text":"请, 想, 喜欢, 爱, 呢, 都, 太, 怎么样, 怎么, 一点儿 и разговор в ресторане."}'),
  ('hsk1-10-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"我想吃米饭","options":["wǒ xiǎng hē mǐfàn","wǒ xiǎng chī mǐfàn"],"correct":1},{"say":"我喜欢茶","options":["wǒ ài chá","wǒ xǐhuan chá"],"correct":1},{"say":"你呢","options":["nǐ ne","nǐ ma"],"correct":0},{"say":"我们都喝茶","options":["wǒmen dōu chī chá","wǒmen dōu hē chá"],"correct":1},{"say":"太好了","options":["tài duō le","tài hǎo le"],"correct":1},{"say":"汉语怎么说","options":["Hànyǔ zěnmeyàng","Hànyǔ zěnme shuō"],"correct":1}]}'),
  ('hsk1-10-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🙏","options":["想","请","爱"],"correct":1},{"emoji":"💭","options":["想","喜欢","请"],"correct":0},{"emoji":"❤️","options":["爱","请","想"],"correct":0},{"emoji":"💥","options":["太","呢","都"],"correct":0}]}'),
  ('hsk1-10-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["请","пожалуйста"],["想","хотеть"],["喜欢","нравиться"],["爱","любить"],["呢","а ты?"],["都","все"],["太","слишком"],["怎么样","каково"],["怎么","как (способ)"],["一点儿","немного"]]}'),
  ('hsk1-10-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Я хочу чай»?","options":["我想茶。","我喝想茶。","我想喝茶。"],"correct":2},{"q":"Как спросить «А ты?»","options":["你什么？","你呢？","你吗？"],"correct":1},{"q":"Где стоит 都?","options":["после глагола","перед глаголом","в начале всего предложения"],"correct":1},{"q":"爱 слабее, чем 喜欢.","tf":false},{"q":"Как сказать «Как это блюдо?»","options":["怎么这个菜？","这个菜怎么？","这个菜怎么样？"],"correct":2},{"q":"Как читается 一点儿?","options":["yìdiǎnr","yǐdiǎnr","yīdiǎnr"],"correct":0},{"q":"太好了 — выражение радости.","tf":true},{"q":"Как сказать «Мы все любим чай»?","options":["都我们喜欢茶。","我们都喜欢茶。","我们喜欢都茶。"],"correct":1},{"q":"Что значит 请?","options":["хотеть","пожалуйста","любить"],"correct":1},{"q":"Как спросить «Как сказать по-китайски?»","options":["怎么汉语说？","汉语说怎么？","汉语怎么说？"],"correct":2}]}'),
  ('hsk1-10-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","想","吃","米饭"],"hint":"«Я хочу рис.»"},{"answer":["我们","都","喝","茶"],"hint":"«Мы все пьём чай.»"},{"answer":["这个","菜","怎么样"],"hint":"«Как это блюдо?»"},{"answer":["我","喜欢","水果"],"hint":"«Я люблю фрукты.»"}]}'),
  ('hsk1-10-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我想吃喝茶。","context":"«Я хочу чай»","options":["想我喝茶。","我想喝茶。","我喝想茶。"],"correct":1},{"buggyText":"太好。","context":"«Как здорово!»","options":["太好是！","太好了！","太好吗！"],"correct":1},{"buggyText":"我们喝都茶。","context":"«Мы все пьём чай»","options":["我们都喝茶。","都我们喝茶。","我们喝茶都。"],"correct":0}]}'),
  ('hsk1-10-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Официант","text":"你们想吃什么？","pinyin":"Nǐmen xiǎng chī shénme?","translation":"Что вы хотите?","options":["我们是米饭。","我们想吃米饭。","我们吃想米饭。"],"correct":1},{"speaker":"Официант","text":"你们想喝什么？","pinyin":"Nǐmen xiǎng hē shénme?","translation":"Что хотите пить?","options":["我们吃茶。","我们都想喝茶。","都我们茶。"],"correct":1}]}'),
  ('hsk1-10-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"想","pinyin":"xiǎng","m":"хотеть","hint":"相 + 心"},{"hanzi":"爱","pinyin":"ài","m":"любить","hint":"爫 + 友"},{"hanzi":"太","pinyin":"tài","m":"слишком","hint":"大 + точка"}]}'),
  ('hsk1-10-6', 10, 'recall', '{"words":[{"hanzi":"请","pinyin":"qǐng","m":"пожалуйста"},{"hanzi":"想","pinyin":"xiǎng","m":"хотеть"},{"hanzi":"喜欢","pinyin":"xǐhuan","m":"нравиться"},{"hanzi":"爱","pinyin":"ài","m":"любить"},{"hanzi":"呢","pinyin":"ne","m":"а ты?"},{"hanzi":"都","pinyin":"dōu","m":"все"},{"hanzi":"太","pinyin":"tài","m":"слишком"},{"hanzi":"怎么样","pinyin":"zěnmeyàng","m":"каково"},{"hanzi":"怎么","pinyin":"zěnme","m":"как"},{"hanzi":"一点儿","pinyin":"yìdiǎnr","m":"немного"}],"tf":[{"zh":"我们喝都茶。","py":"wǒmen hē dōu chá.","m":"Мы все пьём чай.","ok":false,"explain":"都 перед глаголом: 我们都喝茶."},{"zh":"太好了！","py":"tài hǎo le!","m":"Как здорово!","ok":true}],"sentences":[{"zh":"我想喝茶。","tokens":["我","想","喝","茶"],"m":"Я хочу чай."},{"zh":"我们都喜欢米饭。","tokens":["我们","都","喜欢","米饭"],"m":"Мы все любим рис."},{"zh":"汉语怎么说？","tokens":["汉语","怎么","说"],"m":"Как сказать по-китайски?"}]}'),
  ('hsk1-11-1', 1, 'fact', '{"emoji":"🌦️","title":"Погода — это «дыхание неба»","text":"天气 буквально «небо + дыхание»: 天 «небо», 气 «воздух, дух». А ещё в китайском есть чёткая картина: 冷 «холодно» имеет слева 冫 «лёд», а 热 «жарко» — четыре точки 灬 «огонь» внизу. Знак 雨 «дождь» нарисован как окно неба, из которого падают капли."}'),
  ('hsk1-11-1', 2, 'words', '{"title":"Погода","items":[{"hanzi":"天气","pinyin":"tiānqì","m":"погода","emoji":"🌤️","ex":{"zh":"今天天气很好。","py":"Jīntiān tiānqì hěn hǎo.","m":"Сегодня хорошая погода."}},{"hanzi":"冷","pinyin":"lěng","m":"холодный","emoji":"🥶","ex":{"zh":"北京很冷。","py":"Běijīng hěn lěng.","m":"В Пекине холодно."}},{"hanzi":"热","pinyin":"rè","m":"горячий, жаркий","emoji":"🥵","ex":{"zh":"今天很热。","py":"Jīntiān hěn rè.","m":"Сегодня жарко."}},{"hanzi":"下雨","pinyin":"xiàyǔ","m":"идёт дождь","emoji":"🌧️","ex":{"zh":"今天下雨。","py":"Jīntiān xiàyǔ.","m":"Сегодня дождь."}}]}'),
  ('hsk1-11-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🥶","options":["冷","热","下雨"],"correct":0},{"emoji":"🥵","options":["热","天气","冷"],"correct":0},{"emoji":"🌧️","options":["天气","下雨","冷"],"correct":1},{"emoji":"🌤️","options":["下雨","热","天气"],"correct":2}]}'),
  ('hsk1-11-1', 4, 'theory', '{"title":"Как говорить о погоде","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["今天天气很好。","Jīntiān tiānqì hěn hǎo.","Сегодня хорошая погода."],["今天很冷。","Jīntiān hěn lěng.","Сегодня холодно."],["今天下雨。","Jīntiān xiàyǔ.","Сегодня дождь."],["北京天气怎么样？","Běijīng tiānqì zěnmeyàng?","Какая погода в Пекине?"]]},{"t":"p","text":"Погоду описывают без связки 是: 天气很好, 今天很冷. Вопрос — 天气怎么样？"},{"t":"tip","text":"下雨 — это целое слово «идти дождю»: 下 «падать» + 雨 «дождь»."}]}'),
  ('hsk1-11-1', 5, 'quiz', '{"title":"Мини-тест: погода","qs":[{"q":"Как спросить «Какая погода?»","options":["天气几？","怎么样天气？","天气怎么样？"],"correct":2},{"q":"热 значит «холодный».","tf":false,"explain":"热 — жаркий, 冷 — холодный."},{"q":"Какой ключ слева у 冷?","options":["冫","氵","亻"],"correct":0}]}'),
  ('hsk1-11-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["天气","погода"],["冷","холодный"],["热","жаркий"],["下雨","идёт дождь"],["天气很好","погода хорошая"]]}'),
  ('hsk1-11-1', 7, 'game', '{"type":"listen","title":"Слушаем погоду","items":[{"say":"天气","options":["tiānqí","tiānqì","tiánqì"],"correct":1},{"say":"冷","options":["lèng","lěng","léng"],"correct":1},{"say":"热","options":["rě","ré","rè"],"correct":2},{"say":"下雨","options":["xiàyú","xiàyǔ","xiāyǔ"],"correct":1},{"say":"今天很冷","options":["jīntiān hěn rè","jīntiān hěn lěng"],"correct":1}]}'),
  ('hsk1-11-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["今天","天气","很","好"],"hint":"«Сегодня хорошая погода.»"},{"answer":["今天","很","冷"],"hint":"«Сегодня холодно.»"},{"answer":["今天","下雨"],"hint":"«Сегодня дождь.»"}]}'),
  ('hsk1-11-1', 9, 'write', '{"title":"Пропись: погода","items":[{"hanzi":"冷","pinyin":"lěng","m":"холодный","hint":"слева 冫, справа 令"},{"hanzi":"热","pinyin":"rè","m":"жаркий","hint":"сверху 执, внизу 灬"},{"hanzi":"雨","pinyin":"yǔ","m":"дождь","hint":"сверху 一, рамка, внутри капли"}]}'),
  ('hsk1-11-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 天气?","options":["небо","погода","воздух"],"correct":1},{"q":"Как читается 热?","options":["ré","rě","rè"],"correct":2},{"q":"Как сказать «Сегодня холодно»?","options":["今天很冷。","今天冷是。","今天是很冷。"],"correct":0},{"q":"下雨 — это «идёт дождь».","tf":true},{"q":"Что значит 冷?","options":["дождь","холодный","жаркий"],"correct":1}]}'),
  ('hsk1-11-2', 1, 'fact', '{"emoji":"🔄","title":"Маленькая частица 了 — «уже теперь»","text":"Частица 了 в конце фразы сообщает: «ситуация изменилась». 下雨了 — «пошёл дождь» (раньше не шёл). 在 — глагол «находиться»: 我在家. А 里 «внутри» превращает место в «пространство внутри»: 家里 «в доме», 学校里 «в школе»."}'),
  ('hsk1-11-2', 2, 'words', '{"title":"Три маленьких слова","items":[{"hanzi":"了","pinyin":"le","m":"частица изменения","emoji":"🔄","ex":{"zh":"下雨了。","py":"Xiàyǔ le.","m":"Пошёл дождь."}},{"hanzi":"在","pinyin":"zài","m":"находиться, в","emoji":"📍","ex":{"zh":"我在家。","py":"Wǒ zài jiā.","m":"Я дома."}},{"hanzi":"里","pinyin":"lǐ","m":"внутри","emoji":"📦","ex":{"zh":"学校里","py":"xuéxiào lǐ","m":"в школе"}}]}'),
  ('hsk1-11-2', 3, 'theory', '{"title":"了 в конце: новая ситуация","blocks":[{"t":"table","head":["Фраза","Смысл"],"rows":[["下雨了。","Пошёл дождь (раньше не шёл)."],["冷了。","Похолодало."],["太好了！","Как здорово!"]]},{"t":"p","text":"了 ставят в конце, когда что-то только что произошло или изменилось. Без了 фраза описывает постоянное состояние: 很冷 — «холодно» как факт, 冷了 — «стало холодно»."}]}'),
  ('hsk1-11-2', 4, 'quiz', '{"title":"Мини-тест: 了","qs":[{"q":"Как сказать «Пошёл дождь»?","options":["下雨是。","下雨了。","了下雨。"],"correct":1},{"q":"了 ставится в начале фразы.","tf":false,"explain":"Он стоит в конце."},{"q":"Что значит 冷了?","options":["не холодно","очень холодно","стало холодно"],"correct":2}]}'),
  ('hsk1-11-2', 5, 'theory', '{"title":"在 и 里: где находится","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我在家。","Я дома."],["我在学校。","Я в школе."],["他在商店里。","Он в магазине (внутри)."],["我在家学习。","Я учусь дома."]]},{"t":"p","text":"在 + место: «находиться»; а 在 + место + глагол: «делать где-то». Слово 里 ставится после места и уточняет «внутри»: 家里, 商店里, 学校里."},{"t":"tip","text":"Для названий городов и стран 里 не нужен: 他在北京."}]}'),
  ('hsk1-11-2', 6, 'game', '{"type":"build","title":"Соберите предложение","items":[{"answer":["我","在","家"],"hint":"«Я дома.»"},{"answer":["他","在","学校","里"],"hint":"«Он в школе.»"},{"answer":["我","在","家","学习"],"hint":"«Я учусь дома.»"}]}'),
  ('hsk1-11-2', 7, 'game', '{"type":"listen","title":"Слушаем: 了, 在, 里","items":[{"say":"下雨了","options":["xiàyǔ le","xiàyǔ ma"],"correct":0},{"say":"我在家","options":["wǒ qù jiā","wǒ zài jiā"],"correct":1},{"say":"在学校里","options":["zài xuéxiào lǐ","zài xuéxiào lì"],"correct":0},{"say":"他在北京","options":["tā zài Běijīng","tā lái Běijīng"],"correct":0},{"say":"冷了","options":["lěng le","lěng ne"],"correct":0}]}'),
  ('hsk1-11-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["了","частица изменения"],["在","находиться"],["里","внутри"],["在家","быть дома"],["商店里","внутри магазина"]]}'),
  ('hsk1-11-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: 在, 了, 里","cases":[{"buggyText":"我在去学校。","context":"«Я в школе»","options":["在我学校。","我在学校。","我去在学校。"],"correct":1},{"buggyText":"下雨是。","context":"«Пошёл дождь»","options":["下雨了。","了下雨。","下雨吗。"],"correct":0},{"buggyText":"他在里家。","context":"«Он дома, внутри»","options":["他在家里。","他在家在。","他里在家。"],"correct":0}]}'),
  ('hsk1-11-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 在?","options":["приходить","идти","находиться, в"],"correct":2},{"q":"Как сказать «Он в магазине»?","options":["他商店在里。","他去商店里。","他在商店里。"],"correct":2},{"q":"里 стоит после названия места.","tf":true},{"q":"Как читается 里?","options":["lì","lǐ","lí"],"correct":1},{"q":"Как сказать «Я дома учусь»?","options":["在家我学习。","我在家学习。","我学习在家。"],"correct":1}]}'),
  ('hsk1-11-3', 1, 'fact', '{"emoji":"🌸","title":"«Плывёт и сияет»","text":"漂亮 piàoliang «красивый» складывается из 漂 «плыть, парить» и 亮 «светлый»: красота, которая сияет. А 前面 «передняя сторона» и 后面 «задняя сторона» заканчиваются на 面 «лицо, сторона». Поэтому 前面 — «лицо вперёд», 后面 — «лицо назад»."}'),
  ('hsk1-11-3', 2, 'words', '{"title":"Красиво и где","items":[{"hanzi":"漂亮","pinyin":"piàoliang","m":"красивый","emoji":"🌸","ex":{"zh":"学校很漂亮。","py":"Xuéxiào hěn piàoliang.","m":"Школа красивая."}},{"hanzi":"前面","pinyin":"qiánmian","m":"впереди, перед","emoji":"⬆️","ex":{"zh":"学校前面","py":"xuéxiào qiánmian","m":"перед школой"}},{"hanzi":"后面","pinyin":"hòumian","m":"позади, сзади","emoji":"⬇️","ex":{"zh":"商店后面","py":"shāngdiàn hòumian","m":"за магазином"}}]}'),
  ('hsk1-11-3', 3, 'game', '{"type":"listen","title":"Слушаем: красота и место","items":[{"say":"漂亮","options":["piāoliang","piàoliang","piǎoliang"],"correct":1},{"say":"前面","options":["qiánmian","qiànmian","qiǎnmian"],"correct":0},{"say":"后面","options":["hǒumian","hòumian","hóumian"],"correct":1},{"say":"学校很漂亮","options":["xuéxiào hěn piàoliang","xuéxiào hěn dà"],"correct":0},{"say":"商店在学校前面","options":["shāngdiàn zài xuéxiào hòumian","shāngdiàn zài xuéxiào qiánmian"],"correct":1}]}'),
  ('hsk1-11-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «hòu» (4 тон)"}'),
  ('hsk1-11-3', 5, 'theory', '{"title":"Где находится предмет","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["商店在学校前面。","Магазин перед школой."],["饭店在学校后面。","Ресторан за школой."],["我家在北京。","Мой дом в Пекине."]]},{"t":"p","text":"Схема: предмет 在 место + 前面 / 后面. Слово места стоит ДО слова 前面: 学校前面, а не 前面学校."},{"t":"tip","text":"Второй слог 面 в этих словах безударный: qiánmian, hòumian."}]}'),
  ('hsk1-11-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🌸","options":["后面","前面","漂亮"],"correct":2},{"emoji":"⬆️","options":["漂亮","前面","后面"],"correct":1},{"emoji":"⬇️","options":["后面","漂亮","前面"],"correct":0}]}'),
  ('hsk1-11-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["漂亮","красивый"],["前面","впереди"],["后面","позади"],["学校前面","перед школой"],["商店后面","за магазином"]]}'),
  ('hsk1-11-3', 8, 'game', '{"type":"chatsim","title":"WeChat: где что?","messages":[{"speaker":"Друг","text":"你家漂亮吗？","pinyin":"Nǐ jiā piàoliang ma?","translation":"Твой дом красивый?","options":["家漂亮不是。","很漂亮。","我是漂亮。"],"correct":1},{"speaker":"Друг","text":"你家在哪儿？","pinyin":"Nǐ jiā zài nǎr?","translation":"Где твой дом? (哪儿 «где» — новое слово)","options":["我家在学校后面。","我家后面。","我家是学校。"],"correct":0},{"speaker":"Друг","text":"学校前面有什么？","pinyin":"Xuéxiào qiánmian yǒu shénme?","translation":"Что есть перед школой?","options":["有商店。","是商店吗。","商店在有。"],"correct":0}]}'),
  ('hsk1-11-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["学校","很","漂亮"],"hint":"«Школа красивая.»"},{"answer":["商店","在","学校","前面"],"hint":"«Магазин перед школой.»"},{"answer":["饭店","在","学校","后面"],"hint":"«Ресторан за школой.»"}]}'),
  ('hsk1-11-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 漂亮?","options":["большой","красивый","холодный"],"correct":1},{"q":"Что значит 后面?","options":["позади","впереди","внутри"],"correct":0},{"q":"Как сказать «Школа красивая»?","options":["学校很漂亮。","漂亮学校是。","学校是漂亮。"],"correct":0},{"q":"Слово места ставится перед 前面.","tf":true},{"q":"Как читается 后面?","options":["hòumian","hǒumian","hóumian"],"correct":0}]}'),
  ('hsk1-11-4', 1, 'fact', '{"emoji":"🧣","title":"Разговор о погоде","text":"Анна пишет Ли Мину и спрашивает про Пекин. Слова погоды и места встречаются здесь вместе."}'),
  ('hsk1-11-4', 2, 'text', '{"title":"Переписка о погоде","lines":[{"zh":"安娜：李明，北京今天天气怎么样？","py":"Ānnà: Lǐ Míng, Běijīng jīntiān tiānqì zěnmeyàng?","m":"Анна: Ли Мин, какая сегодня погода в Пекине?"},{"zh":"李明：很冷。下雨了。","py":"Lǐ Míng: Hěn lěng. Xiàyǔ le.","m":"Ли Мин: Очень холодно. Пошёл дождь."},{"zh":"安娜：你在家吗？","py":"Ānnà: Nǐ zài jiā ma?","m":"Анна: Ты дома?"},{"zh":"李明：在，我在家里。你呢？","py":"Lǐ Míng: Zài, wǒ zài jiā lǐ. Nǐ ne?","m":"Ли Мин: Да, я дома. А ты?"},{"zh":"安娜：我在学校。学校很漂亮。","py":"Ānnà: Wǒ zài xuéxiào. Xuéxiào hěn piàoliang.","m":"Анна: Я в школе. Школа красивая."},{"zh":"李明：学校前面有商店。","py":"Lǐ Míng: Xuéxiào qiánmian yǒu shāngdiàn.","m":"Ли Мин: Перед школой есть магазин."},{"zh":"安娜：太好了！我想去商店。","py":"Ānnà: Tài hǎo le! Wǒ xiǎng qù shāngdiàn.","m":"Анна: Как здорово! Я хочу пойти в магазин."}],"qs":[{"q":"Какая погода в Пекине?","options":["жарко","холодно и дождь","солнечно"],"correct":1},{"q":"Ли Мин в школе.","tf":false,"explain":"Он дома, 在家里."},{"q":"Где Анна?","options":["дома","в школе","в магазине"],"correct":1},{"q":"Что есть перед школой?","options":["ресторан","магазин","дом"],"correct":1},{"q":"Анна считает школу красивой.","tf":true},{"q":"Вставьте слово: 下雨___。","options":["吗","了","的"],"correct":1},{"q":"Что хочет сделать Анна?","options":["пойти в магазин","остаться дома","пойти в ресторан"],"correct":0}]}'),
  ('hsk1-11-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["很冷","очень холодно"],["下雨了","пошёл дождь"],["我在家里","я дома"],["学校很漂亮","школа красивая"],["学校前面有商店","перед школой есть магазин"]]}'),
