  ('hsk1-11-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как спросить «Какая погода?»","options":["怎么天气？","天气怎么样？","天气怎么？"],"correct":1},{"q":"Как сказать «Пошёл дождь»?","options":["下雨是。","了下雨。","下雨了。"],"correct":2},{"q":"Как сказать «Я дома»?","options":["我在家。","我家在。","我去在家。"],"correct":0},{"q":"了 в конце сообщает об изменении.","tf":true},{"q":"Где стоит слово места относительно 前面?","options":["после","в конце фразы","до"],"correct":2},{"q":"Как сказать «Он в магазине»?","options":["他里在商店。","他商店在里。","他在商店里。"],"correct":2},{"q":"里 ставится перед словом места.","tf":false},{"q":"Что значит 漂亮?","options":["красивый","холодный","жаркий"],"correct":0},{"q":"Как читается 前面?","options":["qiǎnmian","qiánmian","qiànmian"],"correct":1},{"q":"Как сказать «Магазин за школой»?","options":["商店后面学校。","商店在学校后面。","商店在学校前面。"],"correct":1}]}'),
