  ('hsk1-11-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"今天冷很。","context":"«Сегодня холодно»","options":["很今天冷。","今天很冷。","冷今天很。"],"correct":1},{"buggyText":"我在去学校。","context":"«Я в школе»","options":["我去在学校。","在我学校。","我在学校。"],"correct":2},{"buggyText":"商店在前面学校。","context":"«Магазин перед школой»","options":["商店在学校前面。","商店在前面学校。","商店前面学校在。"],"correct":0}]}'),
  ('hsk1-11-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"今天天气怎么样？","pinyin":"Jīntiān tiānqì zěnmeyàng?","translation":"Какая сегодня погода?","options":["天气是雨。","很冷，下雨了。","在冷。"],"correct":1},{"speaker":"Друг","text":"你在哪儿？","pinyin":"Nǐ zài nǎr?","translation":"Где ты? (哪儿 «где» — новое слово)","options":["我去里家。","我是家里。","我在家里。"],"correct":2}]}'),
