  ('hsk1-12-1', 1, 'fact', '{"emoji":"🚖","title":"Два человека на земле","text":"Знак 坐 «сидеть, ехать на чём-то» рисует двух человек 人人 на земле 土. Китайцы буквально «садятся на землю» и «едут» в одном слове. Другие слова транспорта тоже образные: 出租车 «выдаваемая в аренду машина», 飞机 «летающая машина», 火车站 «станция огненной повозки» (так когда-то называли паровоз)."}'),
  ('hsk1-12-1', 2, 'words', '{"title":"Транспорт","items":[{"hanzi":"出租车","pinyin":"chūzūchē","m":"такси","emoji":"🚖","ex":{"zh":"我坐出租车。","py":"Wǒ zuò chūzūchē.","m":"Я еду на такси."}},{"hanzi":"飞机","pinyin":"fēijī","m":"самолёт","emoji":"✈️","ex":{"zh":"我坐飞机去北京。","py":"Wǒ zuò fēijī qù Běijīng.","m":"Я лечу в Пекин."}},{"hanzi":"火车站","pinyin":"huǒchēzhàn","m":"железнодорожный вокзал","emoji":"🚉","ex":{"zh":"我去火车站。","py":"Wǒ qù huǒchēzhàn.","m":"Я иду на вокзал."}},{"hanzi":"坐","pinyin":"zuò","m":"сидеть, ехать (на)","emoji":"🪑","ex":{"zh":"我坐出租车。","py":"Wǒ zuò chūzūchē.","m":"Я еду на такси."}}]}'),
  ('hsk1-12-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🚖","options":["飞机","火车站","出租车"],"correct":2},{"emoji":"✈️","options":["飞机","火车站","坐"],"correct":0},{"emoji":"🚉","options":["飞机","火车站","出租车"],"correct":1},{"emoji":"🪑","options":["出租车","坐","飞机"],"correct":1}]}'),
  ('hsk1-12-1', 4, 'theory', '{"title":"Как ездить: 坐 + транспорт","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["我坐出租车。","Wǒ zuò chūzūchē.","Я еду на такси."],["我坐飞机。","Wǒ zuò fēijī.","Я лечу самолётом."],["我去火车站。","Wǒ qù huǒchēzhàn.","Я иду на вокзал."]]},{"t":"p","text":"坐 ставится перед транспортом: 坐飞机, 坐出租车. Никаких предлогов «на» не нужно."},{"t":"tip","text":"Звук 车 chē входит и в 出租车, и в 火车站: запомните «машина, повозка»."}]}'),
  ('hsk1-12-1', 5, 'quiz', '{"title":"Мини-тест: транспорт","qs":[{"q":"Как сказать «Я лечу самолётом»?","options":["我坐飞机。","坐我飞机。","我飞机坐。"],"correct":0},{"q":"坐 нужно, чтобы сказать «ехать на транспорте».","tf":true},{"q":"Из каких частей состоит 坐?","options":["女 и 子","口 и 木","人人 и 土"],"correct":2}]}'),
  ('hsk1-12-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["出租车","такси"],["飞机","самолёт"],["火车站","вокзал"],["坐","ехать, сидеть"],["坐飞机","лететь самолётом"]]}'),
  ('hsk1-12-1', 7, 'game', '{"type":"listen","title":"Слушаем транспорт","items":[{"say":"出租车","options":["chúzūchē","chūzǔchē","chūzūchē"],"correct":2},{"say":"飞机","options":["fēijì","féijī","fēijī"],"correct":2},{"say":"火车站","options":["huǒchēzhàn","huòchēzhàn","huǒchēzhān"],"correct":0},{"say":"坐","options":["zuó","zuǒ","zuò"],"correct":2},{"say":"我坐飞机","options":["wǒ qù fēijī","wǒ zuò fēijī"],"correct":1}]}'),
  ('hsk1-12-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","坐","出租车"],"hint":"«Я еду на такси.»"},{"answer":["我","坐","飞机","去","北京"],"hint":"«Я лечу в Пекин.»"},{"answer":["我","去","火车站"],"hint":"«Я иду на вокзал.»"}]}'),
  ('hsk1-12-1', 9, 'write', '{"title":"Пропись: транспорт","items":[{"hanzi":"坐","pinyin":"zuò","m":"сидеть, ехать","hint":"две 人 рядом, внизу 土"},{"hanzi":"车","pinyin":"chē","m":"машина, повозка","hint":"горизонтали и вертикаль"},{"hanzi":"机","pinyin":"jī","m":"машина, механизм","hint":"слева 木, справа 几"}]}'),
  ('hsk1-12-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 飞机?","options":["самолёт","вокзал","такси"],"correct":0},{"q":"Как читается 坐?","options":["zuò","zuǒ","zuó"],"correct":0},{"q":"Как сказать «Я еду на такси»?","options":["我出租车坐。","坐出租车我。","我坐出租车。"],"correct":2},{"q":"火车站 — это «аэропорт».","tf":false,"explain":"火车站 — железнодорожный вокзал."},{"q":"Что значит 火车站?","options":["вокзал","самолёт","такси"],"correct":0}]}'),
  ('hsk1-12-2', 1, 'fact', '{"emoji":"🔀","title":"哪 или 那? Решает тон","text":"Эти два знака похожи, но по звуку различаются: 哪 nǎ «какой?» в третьем тоне, а 那 nà «тот» в четвёртом. У 哪 слева 口 «рот»: вопрос задают ртом. Слово 哪儿 nǎr «где?» добавляет суффикс 儿, как в вашем знаке 儿 «ребёнок»: на севере его произносят как лёгкое «р»."}'),
  ('hsk1-12-2', 2, 'words', '{"title":"Где и какой","items":[{"hanzi":"开","pinyin":"kāi","m":"открывать, вести (машину)","emoji":"🔓","ex":{"zh":"我开车去学校。","py":"Wǒ kāi chē qù xuéxiào.","m":"Я еду в школу на машине."}},{"hanzi":"哪儿","pinyin":"nǎr","m":"где, куда","emoji":"📍","ex":{"zh":"你在哪儿？","py":"Nǐ zài nǎr?","m":"Где ты?"}},{"hanzi":"哪","pinyin":"nǎ","m":"какой","emoji":"❔","ex":{"zh":"你喜欢哪个？","py":"Nǐ xǐhuan nǎge?","m":"Какой тебе нравится?"}},{"hanzi":"那","pinyin":"nà","m":"тот, то","emoji":"👉","ex":{"zh":"那是什么？","py":"Nà shì shénme?","m":"Что это там?"}}]}'),
  ('hsk1-12-2', 3, 'theory', '{"title":"Вопрос «где?» и «куда?»","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["你在哪儿？","我在家。"],["你去哪儿？","我去学校。"],["火车站在哪儿？","火车站在学校后面。"]]},{"t":"p","text":"哪儿 ставится на место ответа. Вопросительное слово заменяет место, 吗 не нужен."},{"t":"tip","text":"Не путайте: 你在哪儿？ «Где ты?» и 你去哪儿？ «Куда ты идёшь?»"}]}'),
  ('hsk1-12-2', 4, 'quiz', '{"title":"Мини-тест: где","qs":[{"q":"Как спросить «Куда ты идёшь?»","options":["你去哪儿？","你什么去？","你在哪儿？"],"correct":0},{"q":"К вопросу с 哪儿 добавляют 吗.","tf":false,"explain":"Вопросительное слово заменяет 吗."},{"q":"Какой тон у 哪?","options":["второй","четвёртый","третий"],"correct":2}]}'),
  ('hsk1-12-2', 5, 'theory', '{"title":"这, 那 и 哪","blocks":[{"t":"table","head":["Слово","Тон","Смысл"],"rows":[["这 zhè","4","этот, это"],["那 nà","4","тот, то"],["哪 nǎ","3","какой?"]]},{"t":"p","text":"这个 «этот», 那个 «тот», 哪个 «какой». Они строятся одинаково: слово + 个."},{"t":"ex","zh":"这个好，那个不好。","py":"Zhège hǎo, nàge bù hǎo.","m":"Этот хороший, тот нет.","say":"这个好，那个不好"}]}'),
  ('hsk1-12-2', 6, 'theory', '{"title":"Порядок «на чём + куда»","blocks":[{"t":"table","head":["Русский","Китайский"],"rows":[["Я еду в школу на такси.","我坐出租车去学校。"],["Я езжу на работу на машине.","我开车去工作。"]]},{"t":"p","text":"Сначала способ, потом глагол движения: 坐出租车去, 开车去. Обратный порядок звучит странно."},{"t":"tip","text":"开 буквально «открывать, запускать», а 开车 «вести машину»: «запускать машину»."}]}'),
  ('hsk1-12-2', 7, 'game', '{"type":"listen","title":"Слушаем: где и какой","items":[{"say":"哪儿","options":["nàr","nǎr","nár"],"correct":1},{"say":"那","options":["nà","nǎ","ná"],"correct":0},{"say":"哪","options":["nǎ","nà","ná"],"correct":0},{"say":"你去哪儿","options":["nǐ qù nǎr","nǐ zài nǎr"],"correct":0},{"say":"开车","options":["kǎi chē","kāi chē"],"correct":1}]}'),
  ('hsk1-12-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["开","открывать, вести"],["哪儿","где, куда"],["哪","какой"],["那","тот"],["你去哪儿？","Куда ты идёшь?"]]}'),
  ('hsk1-12-2', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["你","去","哪儿"],"hint":"«Куда ты идёшь?»"},{"answer":["火车站","在","哪儿"],"hint":"«Где вокзал?»"},{"answer":["我","坐","出租车","去","学校"],"hint":"«Я еду в школу на такси.»"},{"answer":["我","开车","去","北京"],"hint":"«Я еду в Пекин на машине.»"}]}'),
  ('hsk1-12-2', 10, 'game', '{"type":"bughunt","title":"Китайский детектив: где и как","cases":[{"buggyText":"你哪儿去？","context":"«Куда ты идёшь?»","options":["哪儿你去？","你去哪儿？","你哪儿去？"],"correct":1},{"buggyText":"我去坐出租车学校。","context":"«Я еду в школу на такси»","options":["我去学校坐出租车。","我坐出租车去学校。","出租车我去学校坐。"],"correct":1},{"buggyText":"你在哪儿吗？","context":"«Где ты?»","options":["你在哪儿吗？","你在哪儿？","你哪儿在？"],"correct":1}]}'),
  ('hsk1-12-2', 11, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 哪儿?","options":["где, куда","тот","какой"],"correct":0},{"q":"Как читается 那?","options":["nǎ","nà","ná"],"correct":1},{"q":"Как сказать «Я еду в Пекин на машине»?","options":["我去开车北京。","我开车去北京。","我北京开车去。"],"correct":1},{"q":"那 читается в третьем тоне.","tf":false,"explain":"那 nà — 4 тон, 哪 nǎ — 3 тон."},{"q":"Что значит 开车?","options":["купить машину","вести машину","сидеть в машине"],"correct":1}]}'),
  ('hsk1-12-3', 1, 'fact', '{"emoji":"⬆️","title":"Верх и низ в одной паре","text":"Знаки 上 «верх, садиться» и 下 «низ, выходить» — настоящие противоположности: у 上 горизонталь снизу и вертикаль сверху, у 下 всё наоборот. Знакомые 上午 и 下午 «до и после полудня» вы уже учили. Теперь они работают как глаголы: 上车 «сесть в транспорт», 下车 «выйти из него»."}'),
  ('hsk1-12-3', 2, 'words', '{"title":"Верх и низ","items":[{"hanzi":"上","pinyin":"shàng","m":"верх, садиться","emoji":"⬆️","ex":{"zh":"上车","py":"shàng chē","m":"сесть в машину"}},{"hanzi":"下","pinyin":"xià","m":"низ, выходить","emoji":"⬇️","ex":{"zh":"下车","py":"xià chē","m":"выйти из машины"}}]}'),
  ('hsk1-12-3', 3, 'game', '{"type":"listen","title":"Слушаем: верх и низ","items":[{"say":"上","options":["shǎng","shāng","shàng"],"correct":2},{"say":"下","options":["xiā","xiǎ","xià"],"correct":2},{"say":"上车","options":["shàng chē","xià chē"],"correct":0},{"say":"下车","options":["xià chē","shàng chē"],"correct":0},{"say":"上午","options":["shàngwǔ","xiàwǔ"],"correct":0}]}'),
  ('hsk1-12-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «shàng» (4 тон)"}'),
  ('hsk1-12-3', 5, 'theory', '{"title":"上 и 下 в движении","blocks":[{"t":"table","head":["Слово","Фраза","Перевод"],"rows":[["上车","请上车。","Пожалуйста, садитесь."],["下车","我在这儿下车。","Я выхожу здесь."],["上","上面","верх, наверху"],["下","下面","низ, внизу"]]},{"t":"p","text":"上 и 下 сочетаются с 车: 上车 «сесть», 下车 «выйти». Те же иероглифы стоят в 上午, 下午, 下雨."},{"t":"tip","text":"Для самолёта говорят 上飞机 и 下飞机."}]}'),
  ('hsk1-12-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"⬆️","options":["上","下","坐"],"correct":0},{"emoji":"⬇️","options":["上","开","下"],"correct":2},{"emoji":"🚖","options":["飞机","火车站","出租车"],"correct":2}]}'),
  ('hsk1-12-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["上","верх, садиться"],["下","низ, выходить"],["上车","сесть в машину"],["下车","выйти из машины"],["上午","до полудня"]]}'),
  ('hsk1-12-3', 8, 'game', '{"type":"chatsim","title":"В такси","messages":[{"speaker":"Водитель","text":"你好！你去哪儿？","pinyin":"Nǐ hǎo! Nǐ qù nǎr?","translation":"Здравствуйте! Куда вам?","options":["我是火车站。","我在火车站。","我去火车站。"],"correct":2},{"speaker":"Водитель","text":"请上车。","pinyin":"Qǐng shàng chē.","translation":"Садитесь, пожалуйста.","options":["没关系。","对不起。","谢谢！"],"correct":2},{"speaker":"Водитель","text":"火车站到了。","pinyin":"Huǒchēzhàn dào le.","translation":"Вот и вокзал. (到 «прибыть» — новое слово)","options":["不客气，上车。","我去哪儿？","谢谢，再见！"],"correct":2}]}'),
  ('hsk1-12-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["请","上","车"],"hint":"«Пожалуйста, садитесь.»"},{"answer":["我","在","这儿","下车"],"hint":"«Я выхожу здесь.»"},{"answer":["我","上","飞机"],"hint":"«Я сажусь в самолёт.»"}]}'),
  ('hsk1-12-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 下车?","options":["вести машину","сесть в машину","выйти из машины"],"correct":2},{"q":"Как читается 上?","options":["shàng","shāng","shǎng"],"correct":0},{"q":"上 и 下 — противоположности.","tf":true},{"q":"Как сказать «Пожалуйста, садитесь»?","options":["请下车。","请上车。","请开车。"],"correct":1},{"q":"Что значит 上面?","options":["впереди","вверху","внизу"],"correct":1}]}'),
  ('hsk1-12-4', 1, 'fact', '{"emoji":"🛄","title":"Два друга планируют поездку","text":"Анна идёт на вокзал, а Ли Мин летит в Пекин. Каждый выбирает транспорт."}'),
  ('hsk1-12-4', 2, 'text', '{"title":"Куда ты едешь?","lines":[{"zh":"安娜：李明，你去哪儿？","py":"Ānnà: Lǐ Míng, nǐ qù nǎr?","m":"Анна: Ли Мин, куда ты едешь?"},{"zh":"李明：我去北京。你呢？","py":"Lǐ Míng: Wǒ qù Běijīng. Nǐ ne?","m":"Ли Мин: В Пекин. А ты?"},{"zh":"安娜：我去火车站。","py":"Ānnà: Wǒ qù huǒchēzhàn.","m":"Анна: На вокзал."},{"zh":"李明：火车站在哪儿？","py":"Lǐ Míng: Huǒchēzhàn zài nǎr?","m":"Ли Мин: Где вокзал?"},{"zh":"安娜：火车站在学校后面。","py":"Ānnà: Huǒchēzhàn zài xuéxiào hòumian.","m":"Анна: Вокзал за школой."},{"zh":"李明：你坐出租车去吗？","py":"Lǐ Míng: Nǐ zuò chūzūchē qù ma?","m":"Ли Мин: Ты поедешь на такси?"},{"zh":"安娜：是，我坐出租车。你坐飞机去北京吗？","py":"Ānnà: Shì, wǒ zuò chūzūchē. Nǐ zuò fēijī qù Běijīng ma?","m":"Анна: Да, на такси. Ты летишь в Пекин?"},{"zh":"李明：是，我坐飞机。明天见！","py":"Lǐ Míng: Shì, wǒ zuò fēijī. Míngtiān jiàn!","m":"Ли Мин: Да, самолётом. До завтра!"}],"qs":[{"q":"Куда едет Ли Мин?","options":["в Пекин","домой","на вокзал"],"correct":0},{"q":"Где находится вокзал?","options":["за школой","в школе","перед школой"],"correct":0},{"q":"Анна едет на вокзал на такси.","tf":true},{"q":"Как Ли Мин добирается в Пекин?","options":["на такси","на машине","самолётом"],"correct":2},{"q":"Ли Мин едет на вокзал.","tf":false,"explain":"Он летит в Пекин."},{"q":"Вставьте слово: 火车站在___？","options":["哪儿","什么","几"],"correct":0},{"q":"Чем заканчивается разговор?","options":["明天见","再见","对不起"],"correct":0}]}'),
  ('hsk1-12-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["你去哪儿？","Куда ты идёшь?"],["我去北京","Я еду в Пекин"],["火车站在学校后面","Вокзал за школой"],["我坐出租车","Я еду на такси"],["我坐飞机","Я лечу самолётом"]]}'),
  ('hsk1-12-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你去哪儿","options":["nǐ qù nǎr","nǐ zài nǎr"],"correct":0},{"say":"火车站在哪儿","options":["huǒchēzhàn zài nǎr","huǒchēzhàn zài nàr"],"correct":0},{"say":"我坐飞机去北京","options":["wǒ zuò chūzūchē qù Běijīng","wǒ zuò fēijī qù Běijīng"],"correct":1},{"say":"明天见","options":["míngtiān jiàn","míngtiān zàijiàn"],"correct":0}]}'),
  ('hsk1-12-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: куда и как","cases":[{"buggyText":"你哪儿去？","context":"«Куда ты едешь?»","options":["你哪儿去？","去你哪儿？","你去哪儿？"],"correct":2},{"buggyText":"我去北京飞机坐。","context":"«Я лечу в Пекин»","options":["我去北京飞机坐。","我坐飞机去北京。","我飞机坐去北京。"],"correct":1},{"buggyText":"火车站哪儿在？","context":"«Где вокзал?»","options":["火车站在哪儿？","火车站哪儿在？","哪儿火车站在？"],"correct":0}]}'),
  ('hsk1-12-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я еду на вокзал»?","options":["我在去火车站。","我火车站去。","我去火车站。"],"correct":2},{"q":"Как читается 哪儿?","options":["nàr","nár","nǎr"],"correct":2},{"q":"Анна и Ли Мин едут в разные места.","tf":true}]}'),
  ('hsk1-12-5', 1, 'fact', '{"emoji":"🗺️","title":"Спланируйте поездку","text":"Сегодня вы сами выбираете, куда и на чём ехать, и составляете маршрут. Слова глав 1–12."}'),
  ('hsk1-12-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"坐","correctRadicals":["人","人","土"],"title":"Пазл: соберите 坐"}'),
  ('hsk1-12-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"站","radicals":["立","占","木"],"correctOrder":["立","占"],"explain":"Слева 立 «стоять», справа 占."},{"targetHanzi":"机","radicals":["木","几","亻"],"correctOrder":["木","几"],"explain":"Слева 木, справа 几."},{"targetHanzi":"哪","radicals":["口","那","女"],"correctOrder":["口","那"],"explain":"Слева 口, справа 那."}]}'),
  ('hsk1-12-5', 4, 'game', '{"type":"build","title":"Мастерская маршрутов","items":[{"target":"(Маршрут)","answer":["我","坐","出租车","去","火车站"],"hint":"«Я еду на вокзал на такси.»"},{"target":"(Маршрут)","answer":["我","明天","坐","飞机","去","北京"],"hint":"«Завтра я лечу в Пекин.»"},{"target":"(Вопрос)","answer":["火车站","在","哪儿"],"hint":"«Где вокзал?»"},{"target":"(Вопрос)","answer":["你","坐","什么","去"],"hint":"«На чём ты едешь?»"}]}'),
  ('hsk1-12-5', 5, 'theory', '{"title":"Шаблон маршрута","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["Когда","明天"],["На чём","坐飞机 / 坐出租车"],["Куда","去北京 / 去火车站"],["Вопрос","你去哪儿？"]]}]}'),
  ('hsk1-12-5', 6, 'game', '{"type":"chatsim","title":"WeChat: поездка","messages":[{"speaker":"Друг","text":"你明天去哪儿？","pinyin":"Nǐ míngtiān qù nǎr?","translation":"Куда ты завтра?","options":["我去北京。","我在北京。","我是北京。"],"correct":0},{"speaker":"Друг","text":"你坐什么去？","pinyin":"Nǐ zuò shénme qù?","translation":"На чём ты поедешь?","options":["我坐飞机去。","我飞机坐去。","我去坐飞机吗。"],"correct":0},{"speaker":"Друг","text":"太好了！明天见！","pinyin":"Tài hǎo le! Míngtiān jiàn!","translation":"Здорово! До завтра!","options":["对不起！","明天见！","不客气。"],"correct":1}]}'),
  ('hsk1-12-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["立 + 占","站"],["木 + 几","机"],["口 + 那","哪"],["人人 + 土","坐"]]}'),
  ('hsk1-12-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"站","pinyin":"zhàn","m":"станция","hint":"слева 立, справа 占"},{"hanzi":"哪","pinyin":"nǎ","m":"какой","hint":"слева 口, справа 那"},{"hanzi":"上","pinyin":"shàng","m":"верх","hint":"вертикаль, две горизонтали"}]}'),
  ('hsk1-12-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Завтра я лечу в Пекин»?","options":["明天去我坐飞机北京。","我坐飞机明天去北京。","我明天坐飞机去北京。"],"correct":2},{"q":"Как спросить «На чём ты едешь?»","options":["你什么坐去？","什么你坐去？","你坐什么去？"],"correct":2},{"q":"В 站 есть 立 «стоять».","tf":true}]}'),
  ('hsk1-12-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 12","text":"Транспорт, 坐, 开, вопросы с 哪儿 и 哪, слово 那 и пара 上 / 下."}'),
  ('hsk1-12-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"出租车","options":["huǒchēzhàn","chūzūchē","fēijī"],"correct":1},{"say":"我坐飞机","options":["wǒ zuò fēijī","wǒ qù fēijī"],"correct":0},{"say":"你去哪儿","options":["nǐ qù nǎr","nǐ zài nǎr"],"correct":0},{"say":"那","options":["nǎ","ná","nà"],"correct":2},{"say":"哪","options":["ná","nǎ","nà"],"correct":1},{"say":"上车","options":["xià chē","shàng chē"],"correct":1}]}'),
  ('hsk1-12-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🚖","options":["飞机","出租车","火车站"],"correct":1},{"emoji":"✈️","options":["火车站","飞机","坐"],"correct":1},{"emoji":"🚉","options":["飞机","火车站","出租车"],"correct":1},{"emoji":"⬇️","options":["下","开","上"],"correct":0}]}'),
  ('hsk1-12-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["出租车","такси"],["飞机","самолёт"],["火车站","вокзал"],["坐","ехать"],["开","вести"],["哪儿","где"],["哪","какой"],["那","тот"],["上","садиться"],["下","выходить"]]}'),
  ('hsk1-12-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как спросить «Куда ты идёшь?»","options":["你去哪儿？","你在哪儿？","你哪儿去？"],"correct":0},{"q":"Как сказать «Я лечу в Пекин»?","options":["我坐飞机去北京。","我去坐飞机北京。","我飞机坐去北京。"],"correct":0},{"q":"Какой тон у 哪?","options":["третий","второй","четвёртый"],"correct":0},{"q":"К вопросу с 哪儿 добавляют 吗.","tf":false},{"q":"Что значит 开车?","options":["сидеть в машине","купить машину","вести машину"],"correct":2},{"q":"Как сказать «Выйти из машины»?","options":["下车","开车","上车"],"correct":0},{"q":"那 читается nà.","tf":true},{"q":"Что значит 火车站?","options":["такси","вокзал","самолёт"],"correct":1},{"q":"Как сказать «Где вокзал?»","options":["火车站在哪儿？","哪儿在火车站？","火车站哪儿？"],"correct":0},{"q":"Как сказать «Пожалуйста, садитесь»?","options":["请上车。","请开车。","请下车。"],"correct":0}]}'),
  ('hsk1-12-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","坐","出租车"],"hint":"«Я еду на такси.»"},{"answer":["你","去","哪儿"],"hint":"«Куда ты идёшь?»"},{"answer":["我","开车","去","学校"],"hint":"«Я еду в школу на машине.»"},{"answer":["请","上","车"],"hint":"«Пожалуйста, садитесь.»"}]}'),
  ('hsk1-12-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"你哪儿去？","context":"«Куда ты идёшь?»","options":["去你哪儿？","你去哪儿？","你哪儿去？"],"correct":1},{"buggyText":"我去坐出租车学校。","context":"«Я еду в школу на такси»","options":["我坐出租车去学校。","我去学校坐出租车。","出租车我去学校坐。"],"correct":0},{"buggyText":"你在哪儿吗？","context":"«Где ты?»","options":["你在哪儿吗？","你哪儿在？","你在哪儿？"],"correct":2}]}'),
  ('hsk1-12-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Водитель","text":"你去哪儿？","pinyin":"Nǐ qù nǎr?","translation":"Куда вам?","options":["我是火车站。","我去火车站。","我在火车站。"],"correct":1},{"speaker":"Водитель","text":"请上车。","pinyin":"Qǐng shàng chē.","translation":"Садитесь.","options":["没关系。","对不起。","谢谢！"],"correct":2}]}'),
  ('hsk1-12-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"坐","pinyin":"zuò","m":"сидеть, ехать","hint":"人人 + 土"},{"hanzi":"车","pinyin":"chē","m":"машина","hint":"четыре черты"},{"hanzi":"下","pinyin":"xià","m":"низ","hint":"горизонталь, вертикаль, точка"}]}'),
  ('hsk1-12-6', 10, 'recall', '{"words":[{"hanzi":"出租车","pinyin":"chūzūchē","m":"такси"},{"hanzi":"飞机","pinyin":"fēijī","m":"самолёт"},{"hanzi":"火车站","pinyin":"huǒchēzhàn","m":"вокзал"},{"hanzi":"坐","pinyin":"zuò","m":"ехать"},{"hanzi":"开","pinyin":"kāi","m":"вести"},{"hanzi":"哪儿","pinyin":"nǎr","m":"где"},{"hanzi":"哪","pinyin":"nǎ","m":"какой"},{"hanzi":"那","pinyin":"nà","m":"тот"},{"hanzi":"上","pinyin":"shàng","m":"садиться"},{"hanzi":"下","pinyin":"xià","m":"выходить"}],"tf":[{"zh":"你哪儿去？","py":"nǐ nǎr qù?","m":"Куда ты идёшь?","ok":false,"explain":"Правильно: 你去哪儿？"},{"zh":"我坐飞机去北京。","py":"wǒ zuò fēijī qù Běijīng.","m":"Я лечу в Пекин.","ok":true}],"sentences":[{"zh":"你去哪儿？","tokens":["你","去","哪儿"],"m":"Куда ты идёшь?"},{"zh":"我坐出租车去学校。","tokens":["我","坐","出租车","去","学校"],"m":"Я еду в школу на такси."},{"zh":"请上车。","tokens":["请","上","车"],"m":"Пожалуйста, садитесь."}]}'),
  ('hsk1-13-1', 1, 'fact', '{"emoji":"⚡","title":"Одна молния, много слов","text":"Знак 电 «электричество» нарисован как молния, а от него в китайском выросли целые «электрические» слова: 电脑 «электрический мозг» (компьютер), 电视 «электрическое зрение» (телевизор), 电影 «электрическая тень» (кино). А 打电话 буквально «ударить по телефону»: 打 «бить, ударять» плюс 电话 «электрический разговор»."}'),
  ('hsk1-13-1', 2, 'words', '{"title":"Электрические слова","items":[{"hanzi":"打电话","pinyin":"dǎ diànhuà","m":"звонить по телефону","emoji":"📞","ex":{"zh":"我打电话。","py":"Wǒ dǎ diànhuà.","m":"Я звоню."}},{"hanzi":"电脑","pinyin":"diànnǎo","m":"компьютер","emoji":"💻","ex":{"zh":"我有电脑。","py":"Wǒ yǒu diànnǎo.","m":"У меня есть компьютер."}},{"hanzi":"电视","pinyin":"diànshì","m":"телевизор","emoji":"📺","ex":{"zh":"电视很大。","py":"Diànshì hěn dà.","m":"Телевизор большой."}},{"hanzi":"电影","pinyin":"diànyǐng","m":"кино, фильм","emoji":"🎬","ex":{"zh":"我喜欢电影。","py":"Wǒ xǐhuan diànyǐng.","m":"Я люблю кино."}}]}'),
  ('hsk1-13-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"📞","options":["电脑","打电话","电视"],"correct":1},{"emoji":"💻","options":["电视","电影","电脑"],"correct":2},{"emoji":"📺","options":["电影","电视","打电话"],"correct":1},{"emoji":"🎬","options":["电影","电脑","电视"],"correct":0}]}'),
  ('hsk1-13-1', 4, 'theory', '{"title":"Как устроены «электрические» слова","blocks":[{"t":"table","head":["Слово","Дословно","Смысл"],"rows":[["电脑","электр. + мозг","компьютер"],["电视","электр. + зрение","телевизор"],["电影","электр. + тень","кино"],["打电话","ударить + эл. разговор","звонить"]]},{"t":"p","text":"Все четыре слова начинаются с 电 diàn. Запомните его, и новые слова вы будете угадывать сами."},{"t":"tip","text":"Для звонка говорят 打电话, а не «делать»: глагол 打 «бить» тут идиома."}]}'),
  ('hsk1-13-1', 5, 'quiz', '{"title":"Мини-тест: электрические слова","qs":[{"q":"Как сказать «компьютер»?","options":["电影","电脑","电视"],"correct":1},{"q":"电影 — это «телевизор».","tf":false,"explain":"电影 — кино, 电视 — телевизор."},{"q":"Что значит 打电话?","options":["играть","звонить","смотреть кино"],"correct":1}]}'),
  ('hsk1-13-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["电脑","компьютер"],["电视","телевизор"],["电影","кино"],["打电话","звонить"],["电","электричество"]]}'),
  ('hsk1-13-1', 7, 'game', '{"type":"listen","title":"Слушаем: электрические слова","items":[{"say":"电脑","options":["diānnǎo","diànnáo","diànnǎo"],"correct":2},{"say":"电视","options":["diànshǐ","diànshì","diānshì"],"correct":1},{"say":"电影","options":["diànyǐng","diànyìng","diányǐng"],"correct":0},{"say":"打电话","options":["dǎ diànhuà","dà diànhuà"],"correct":0},{"say":"我有电脑","options":["wǒ yǒu diànnǎo","wǒ yǒu diànshì"],"correct":0}]}'),
  ('hsk1-13-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","有","电脑"],"hint":"«У меня есть компьютер.»"},{"answer":["我","喜欢","电影"],"hint":"«Я люблю кино.»"},{"answer":["电视","很","大"],"hint":"«Телевизор большой.»"}]}'),
  ('hsk1-13-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"电","pinyin":"diàn","m":"электричество","hint":"рамка с вертикалью, внизу крючок"},{"hanzi":"打","pinyin":"dǎ","m":"бить","hint":"слева 扌, справа 丁"},{"hanzi":"脑","pinyin":"nǎo","m":"мозг","hint":"слева 月, справа 𠂉"}]}'),
  ('hsk1-13-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 电视?","options":["компьютер","кино","телевизор"],"correct":2},{"q":"Как читается 电影?","options":["diànyǐng","diànyìng","diányǐng"],"correct":0},{"q":"Как сказать «Я люблю кино»?","options":["我电影喜欢。","我喜欢电影。","喜欢我电影。"],"correct":1},{"q":"Все эти слова начинаются с 电.","tf":true},{"q":"Что значит 电脑 буквально?","options":["электрическая тень","электрический мозг","электрический разговор"],"correct":1}]}'),
  ('hsk1-13-2', 1, 'fact', '{"emoji":"👀","title":"Рука над глазом","text":"Знак 看 «смотреть» состоит из 手 «рука» над 目 «глаз»: так делает человек, прикрываясь от солнца. А 听 «слушать» содержит 口 «рот» и 斤 «топор»: слушает тот, кто «рубит» звуки на смысл. И любопытное слово 看见 «увидеть»: результат взгляда."}'),
  ('hsk1-13-2', 2, 'words', '{"title":"Смотреть и слушать","items":[{"hanzi":"喂","pinyin":"wèi","m":"алло","emoji":"📱","ex":{"zh":"喂，你好！","py":"Wèi, nǐ hǎo!","m":"Алло, здравствуйте!"}},{"hanzi":"看","pinyin":"kàn","m":"смотреть","emoji":"👀","ex":{"zh":"我看电影。","py":"Wǒ kàn diànyǐng.","m":"Я смотрю кино."}},{"hanzi":"看见","pinyin":"kànjiàn","m":"увидеть","emoji":"👁️","ex":{"zh":"我看见她了。","py":"Wǒ kànjiàn tā le.","m":"Я её увидел."}},{"hanzi":"听","pinyin":"tīng","m":"слушать","emoji":"👂","ex":{"zh":"我听老师说。","py":"Wǒ tīng lǎoshī shuō.","m":"Я слушаю учителя."}}]}'),
  ('hsk1-13-2', 3, 'theory', '{"title":"看 и 看见: в чём разница","blocks":[{"t":"table","head":["Глагол","Смысл","Пример"],"rows":[["看 kàn","направить взгляд, смотреть","我看电视。"],["看见 kànjiàn","увидеть (результат)","我看见他了。"],["听 tīng","слушать","我听老师说。"]]},{"t":"p","text":"看 — действие: «смотрю телевизор». 看见 — итог: «заметил, увидел». 见 здесь означает «воспринять»."},{"t":"tip","text":"По телефону сначала говорят 喂, а потом называют себя: 喂，我是安娜."}]}'),
  ('hsk1-13-2', 4, 'quiz', '{"title":"Мини-тест: смотреть и слушать","qs":[{"q":"Как сказать «Я смотрю кино»?","options":["我听电影。","我电影看。","我看电影。"],"correct":2},{"q":"看见 значит «заметить, увидеть».","tf":true},{"q":"Каким словом отвечают по телефону?","options":["请","喂","谢谢"],"correct":1}]}'),
  ('hsk1-13-2', 5, 'game', '{"type":"build","title":"Соберите предложение","items":[{"answer":["我","看","电视"],"hint":"«Я смотрю телевизор.»"},{"answer":["我","听","老师","说"],"hint":"«Я слушаю, как говорит учитель.»"},{"answer":["我","看见","她","了"],"hint":"«Я её увидел.»"}]}'),
  ('hsk1-13-2', 6, 'game', '{"type":"listen","title":"Слушаем: смотреть и слушать","items":[{"say":"喂","options":["wéi","wěi","wèi"],"correct":2},{"say":"看","options":["kǎn","kàn","kān"],"correct":1},{"say":"看见","options":["kānjiàn","kànjián","kànjiàn"],"correct":2},{"say":"听","options":["tǐng","tíng","tīng"],"correct":2},{"say":"我看电影","options":["wǒ kàn diànyǐng","wǒ tīng diànyǐng"],"correct":0}]}'),
  ('hsk1-13-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["喂","алло"],["看","смотреть"],["看见","увидеть"],["听","слушать"],["看电视","смотреть телевизор"]]}'),
  ('hsk1-13-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: смотреть и слушать","cases":[{"buggyText":"我听电视。","context":"«Я смотрю телевизор»","options":["我看电视。","我电视看。","看我电视。"],"correct":0},{"buggyText":"我看老师说。","context":"«Я слушаю учителя»","options":["听老师我说。","我老师听说。","我听老师说。"],"correct":2},{"buggyText":"我看她见了。","context":"«Я её увидел»","options":["我见看她了。","我看见她了。","我她看见了。"],"correct":1}]}'),
  ('hsk1-13-2', 9, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"👀","options":["听","喂","看"],"correct":2},{"emoji":"👂","options":["看见","看","听"],"correct":2},{"emoji":"👁️","options":["看见","看","喂"],"correct":0}]}'),
  ('hsk1-13-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 听?","options":["звонить","слушать","смотреть"],"correct":1},{"q":"Как читается 看见?","options":["kānjiàn","kànjián","kànjiàn"],"correct":2},{"q":"Как сказать «Я слушаю учителя»?","options":["我老师听。","听我老师。","我听老师。"],"correct":2},{"q":"看 состоит из 手 и 目.","tf":true},{"q":"Какой иероглиф означает «алло»?","options":["听","喂","看"],"correct":1}]}'),
  ('hsk1-13-3', 1, 'fact', '{"emoji":"✒️","title":"Ребёнок под крышей учится знакам","text":"Знак 字 «иероглиф, письменный знак» нарисован как 子 «ребёнок» под 宀 «крышей»: дети учат знаки дома или в школе. Знак 读 «читать вслух» содержит 讠 «речь» и 卖: читают то, что говорят. А 写 «писать» напоминает человека, склонившегося над бумагой."}'),
  ('hsk1-13-3', 2, 'words', '{"title":"Читать и писать","items":[{"hanzi":"读","pinyin":"dú","m":"читать","emoji":"📖","ex":{"zh":"我读汉语。","py":"Wǒ dú Hànyǔ.","m":"Я читаю по-китайски."}},{"hanzi":"写","pinyin":"xiě","m":"писать","emoji":"✍️","ex":{"zh":"我写汉字。","py":"Wǒ xiě Hànzì.","m":"Я пишу иероглифы."}},{"hanzi":"字","pinyin":"zì","m":"знак, иероглиф","emoji":"🔤","ex":{"zh":"这个字怎么读？","py":"Zhège zì zěnme dú?","m":"Как читается этот знак?"}}]}'),
  ('hsk1-13-3', 3, 'theory', '{"title":"Вопросы про знаки","blocks":[{"t":"table","head":["Вопрос","Перевод"],"rows":[["这个字怎么读？","Как читается этот знак?"],["这个字怎么写？","Как пишется этот знак?"],["汉语怎么说？","Как это сказать по-китайски?"]]},{"t":"p","text":"怎么 ставят перед глаголом: 怎么读, 怎么写, 怎么说. Вы уже знаете эту схему из главы 10."},{"t":"tip","text":"Слово 汉字 hànzì — «китайские иероглифы»: 汉 + 字."}]}'),
  ('hsk1-13-3', 4, 'game', '{"type":"listen","title":"Слушаем: читать и писать","items":[{"say":"读","options":["dú","dǔ","dù"],"correct":0},{"say":"写","options":["xié","xiè","xiě"],"correct":2},{"say":"字","options":["zǐ","zí","zì"],"correct":2},{"say":"汉字","options":["hànzì","hànzí","hánzì"],"correct":0},{"say":"这个字怎么读","options":["zhège zì zěnme xiě","zhège zì zěnme dú"],"correct":1}]}'),
  ('hsk1-13-3', 5, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «xiě» (3 тон)"}'),
  ('hsk1-13-3', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["读","читать"],["写","писать"],["字","знак, иероглиф"],["汉字","китайские иероглифы"],["怎么写","как пишется"]]}'),
  ('hsk1-13-3', 7, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"📖","options":["读","写","字"],"correct":0},{"emoji":"✍️","options":["读","字","写"],"correct":2},{"emoji":"🔤","options":["写","读","字"],"correct":2}]}'),
  ('hsk1-13-3', 8, 'game', '{"type":"chatsim","title":"WeChat: иероглифы","messages":[{"speaker":"Друг","text":"这个字怎么读？","pinyin":"Zhège zì zěnme dú?","translation":"Как читается этот знак?","options":["读 hǎo。","不客气。","好，好。"],"correct":0,"explain":"Ответ — чтение знака."},{"speaker":"Друг","text":"你会写汉字吗？","pinyin":"Nǐ huì xiě Hànzì ma?","translation":"Ты умеешь писать иероглифы?","options":["我是字。","会，我写一点儿。","不是，我汉字。"],"correct":1},{"speaker":"Друг","text":"太好了！","pinyin":"Tài hǎo le!","translation":"Как здорово!","options":["没关系。","对不起！","谢谢！"],"correct":2}]}'),
  ('hsk1-13-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","写","汉字"],"hint":"«Я пишу иероглифы.»"},{"answer":["我","读","汉语"],"hint":"«Я читаю по-китайски.»"},{"answer":["这个","字","怎么","读"],"hint":"«Как читается этот знак?»"}]}'),
  ('hsk1-13-3', 10, 'write', '{"title":"Пропись: знаки","items":[{"hanzi":"字","pinyin":"zì","m":"знак","hint":"сверху 宀, снизу 子"},{"hanzi":"写","pinyin":"xiě","m":"писать","hint":"сверху 冖, снизу 与"},{"hanzi":"读","pinyin":"dú","m":"читать","hint":"слева 讠, справа 卖"}]}'),
  ('hsk1-13-3', 11, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 字?","options":["знак, иероглиф","читать","писать"],"correct":0},{"q":"Как читается 写?","options":["xiě","xié","xiè"],"correct":0},{"q":"Как спросить «Как это читается?»","options":["这个字怎么读？","怎么这个字读？","这个字读怎么？"],"correct":0},{"q":"汉字 — это «китайские иероглифы».","tf":true},{"q":"Что значит 读?","options":["слушать","писать","читать"],"correct":2}]}'),
  ('hsk1-13-4', 1, 'fact', '{"emoji":"📱","title":"Звонок другу","text":"Анна звонит Ли Мину. По телефону сначала говорят 喂, потом называют имя. Читайте диалог целиком."}'),
  ('hsk1-13-4', 2, 'text', '{"title":"Звонок после занятий","lines":[{"zh":"安娜：喂，李明吗？","py":"Ānnà: Wèi, Lǐ Míng ma?","m":"Анна: Алло, это Ли Мин?"},{"zh":"李明：喂！你好，安娜。你在哪儿？","py":"Lǐ Míng: Wèi! Nǐ hǎo, Ānnà. Nǐ zài nǎr?","m":"Ли Мин: Алло! Привет, Анна. Где ты?"},{"zh":"安娜：我在学校。我想看电影。你呢？","py":"Ānnà: Wǒ zài xuéxiào. Wǒ xiǎng kàn diànyǐng. Nǐ ne?","m":"Анна: Я в школе. Хочу посмотреть кино. А ты?"},{"zh":"李明：我在家，我看电视。","py":"Lǐ Míng: Wǒ zài jiā, wǒ kàn diànshì.","m":"Ли Мин: Я дома, смотрю телевизор."},{"zh":"安娜：你想看电影吗？","py":"Ānnà: Nǐ xiǎng kàn diànyǐng ma?","m":"Анна: Хочешь посмотреть кино?"},{"zh":"李明：想！什么电影？","py":"Lǐ Míng: Xiǎng! Shénme diànyǐng?","m":"Ли Мин: Хочу! Какое кино?"},{"zh":"安娜：中国电影。明天见！","py":"Ānnà: Zhōngguó diànyǐng. Míngtiān jiàn!","m":"Анна: Китайское. До завтра!"},{"zh":"李明：好，明天见！","py":"Lǐ Míng: Hǎo, míngtiān jiàn!","m":"Ли Мин: Хорошо, до завтра!"}],"qs":[{"q":"Где сейчас Анна?","options":["в магазине","в школе","дома"],"correct":1},{"q":"Ли Мин смотрит кино.","tf":false,"explain":"Он смотрит телевизор."},{"q":"Какое кино хочет смотреть Анна?","options":["китайское","не сказано","американское"],"correct":0},{"q":"Вставьте слово: 喂，李明___？","options":["吗","了","的"],"correct":0},{"q":"Ли Мин хочет посмотреть кино.","tf":true},{"q":"Как Ли Мин спрашивает про фильм?","options":["几个电影？","哪个电影吗？","什么电影？"],"correct":2},{"q":"Чем заканчивается разговор?","options":["再见","谢谢","明天见"],"correct":2}]}'),
  ('hsk1-13-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["喂","алло"],["我想看电影","Я хочу посмотреть кино"],["我看电视","Я смотрю телевизор"],["中国电影","китайское кино"],["明天见","до завтра"]]}'),
  ('hsk1-13-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"喂，李明吗","options":["wèi, Lǐ Míng ne","wèi, Lǐ Míng ma"],"correct":1},{"say":"我想看电影","options":["wǒ xiǎng kàn diànshì","wǒ xiǎng kàn diànyǐng"],"correct":1},{"say":"我在家，我看电视","options":["wǒ zài jiā, wǒ kàn diànshì","wǒ zài jiā, wǒ tīng diànshì"],"correct":0},{"say":"什么电影","options":["shénme diànshì","shénme diànyǐng"],"correct":1}]}'),
  ('hsk1-13-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: звонок","cases":[{"buggyText":"喂，李明吗你？","context":"«Алло, это Ли Мин?»","options":["喂，李明吗？","喂，你李明吗？","喂吗李明？"],"correct":0},{"buggyText":"我想电影看。","context":"«Я хочу посмотреть кино»","options":["我想看电影。","想我看电影。","我看想电影。"],"correct":0},{"buggyText":"我看家电视。","context":"«Я дома смотрю телевизор»","options":["家我看电视。","我在家看电视。","我看电视在家。"],"correct":1}]}'),
  ('hsk1-13-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я хочу посмотреть кино»?","options":["我想看电影。","我看想电影。","想看我电影。"],"correct":0},{"q":"Как читается 电影?","options":["diànyìng","diányǐng","diànyǐng"],"correct":2},{"q":"Анна и Ли Мин договорились на завтра.","tf":true}]}'),
  ('hsk1-13-5', 1, 'fact', '{"emoji":"🍿","title":"Спланируйте вечер","text":"Сегодня вы выбираете фильм, звоните другу и пишете в чат. Слова глав 1–13."}'),
