  ('hsk1-13-5', 7, 'game', '{"type":"chatsim","title":"WeChat: приглашение","messages":[{"speaker":"Друг","text":"喂，你好！","pinyin":"Wèi, nǐ hǎo!","translation":"Алло, привет!","options":["不客气。","喂，你好！","再见！"],"correct":1},{"speaker":"Друг","text":"你想看电影吗？","pinyin":"Nǐ xiǎng kàn diànyǐng ma?","translation":"Хочешь посмотреть кино?","options":["对不起，没有。","不是，我看。","想！什么电影？"],"correct":2},{"speaker":"Друг","text":"中国电影。明天下午三点。","pinyin":"Zhōngguó diànyǐng. Míngtiān xiàwǔ sān diǎn.","translation":"Китайское. Завтра в три.","options":["不客气。","没关系。","好，明天见！"],"correct":2}]}'),
