  ('hsk1-13-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","看","电视"],"hint":"«Я смотрю телевизор.»"},{"answer":["我","想","看","电影"],"hint":"«Я хочу посмотреть кино.»"},{"answer":["我","写","汉字"],"hint":"«Я пишу иероглифы.»"},{"answer":["这个","字","怎么","读"],"hint":"«Как читается этот знак?»"}]}'),
  ('hsk1-13-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我听电视。","context":"«Я смотрю телевизор»","options":["我电视看。","我看电视。","看我电视。"],"correct":1},{"buggyText":"我想电影看。","context":"«Я хочу посмотреть кино»","options":["想我看电影。","我想看电影。","我看想电影。"],"correct":1},{"buggyText":"我看见她了了。","context":"«Я её увидел»","options":["我看见了她。","我见看她了。","我看她见了。"],"correct":0}]}'),
