  ('hsk1-13-6', 10, 'recall', '{"words":[{"hanzi":"打电话","pinyin":"dǎ diànhuà","m":"звонить"},{"hanzi":"电脑","pinyin":"diànnǎo","m":"компьютер"},{"hanzi":"电视","pinyin":"diànshì","m":"телевизор"},{"hanzi":"电影","pinyin":"diànyǐng","m":"кино"},{"hanzi":"喂","pinyin":"wèi","m":"алло"},{"hanzi":"看","pinyin":"kàn","m":"смотреть"},{"hanzi":"看见","pinyin":"kànjiàn","m":"увидеть"},{"hanzi":"听","pinyin":"tīng","m":"слушать"},{"hanzi":"读","pinyin":"dú","m":"читать"},{"hanzi":"写","pinyin":"xiě","m":"писать"},{"hanzi":"字","pinyin":"zì","m":"знак"}],"tf":[{"zh":"我听电视。","py":"wǒ tīng diànshì.","m":"Я смотрю телевизор.","ok":false,"explain":"Телевизор смотрят: 我看电视."},{"zh":"这个字怎么读？","py":"zhège zì zěnme dú?","m":"Как читается этот знак?","ok":true}],"sentences":[{"zh":"我看电影。","tokens":["我","看","电影"],"m":"Я смотрю кино."},{"zh":"我写汉字。","tokens":["我","写","汉字"],"m":"Я пишу иероглифы."},{"zh":"这个字怎么读？","tokens":["这个","字","怎么","读"],"m":"Как читается этот знак?"}]}'),
  ('hsk1-14-1', 1, 'fact', '{"emoji":"📚","title":"Корень дерева стал «книгой»","text":"Знак 本 «основа, корень» — это дерево 木 с чёрточкой внизу: она показывает корень. А потом 本 стал счётным словом для книг: 一本书 «один том». В словах 桌子 «стол» и 椅子 «стул» суффикс 子 делает слово «маленьким предметом», а сам слог в речи звучит безударно."}'),
  ('hsk1-14-1', 2, 'words', '{"title":"Книга, стол, стул","items":[{"hanzi":"书","pinyin":"shū","m":"книга","emoji":"📖","ex":{"zh":"我有一本书。","py":"Wǒ yǒu yì běn shū.","m":"У меня есть книга."}},{"hanzi":"本","pinyin":"běn","m":"том (счётное слово для книг)","emoji":"📘","ex":{"zh":"三本书","py":"sān běn shū","m":"три книги"}},{"hanzi":"桌子","pinyin":"zhuōzi","m":"стол","emoji":"🪑","ex":{"zh":"桌子很大。","py":"Zhuōzi hěn dà.","m":"Стол большой."}},{"hanzi":"椅子","pinyin":"yǐzi","m":"стул","emoji":"💺","ex":{"zh":"椅子很小。","py":"Yǐzi hěn xiǎo.","m":"Стул маленький."}}]}'),
  ('hsk1-14-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"📖","options":["书","椅子","桌子"],"correct":0},{"emoji":"📘","options":["本","书","桌子"],"correct":0},{"emoji":"🪑","options":["桌子","椅子","书"],"correct":0},{"emoji":"💺","options":["桌子","本","椅子"],"correct":2}]}'),
  ('hsk1-14-1', 4, 'theory', '{"title":"Как считать книги","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["一本书","yì běn shū","одна книга"],["三本书","sān běn shū","три книги"],["几本书？","jǐ běn shū?","сколько книг?"]]},{"t":"p","text":"Между числом и «книга» ставится счётное слово 本, как 个 для людей. 一 читается yì перед 本 (3 тон)."},{"t":"tip","text":"Слог 子 в 桌子 и 椅子 безударный: zhuōzi, yǐzi."}]}'),
  ('hsk1-14-1', 5, 'quiz', '{"title":"Мини-тест: книги и мебель","qs":[{"q":"Как сказать «одна книга»?","options":["一个书","一本书","一书本"],"correct":1},{"q":"子 в 桌子 читается с сильным ударением.","tf":false,"explain":"Он безударный."},{"q":"Из каких частей состоит 本?","options":["女 и 子","人 и 土","木 и черта"],"correct":2}]}'),
  ('hsk1-14-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["书","книга"],["本","том (счётное слово)"],["桌子","стол"],["椅子","стул"],["三本书","три книги"]]}'),
  ('hsk1-14-1', 7, 'game', '{"type":"listen","title":"Слушаем: вещи","items":[{"say":"书","options":["shǔ","shū","shú"],"correct":1},{"say":"本","options":["bēn","běn","bèn"],"correct":1},{"say":"桌子","options":["zhuǒzi","zhuózi","zhuōzi"],"correct":2},{"say":"椅子","options":["yìzi","yīzi","yǐzi"],"correct":2},{"say":"一本书","options":["yí běn shū","yì běn shū"],"correct":1}]}'),
  ('hsk1-14-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","有","一","本","书"],"hint":"«У меня есть одна книга.»"},{"answer":["桌子","很","大"],"hint":"«Стол большой.»"},{"answer":["椅子","很","小"],"hint":"«Стул маленький.»"}]}'),
  ('hsk1-14-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"书","pinyin":"shū","m":"книга","hint":"сначала ломаная, потом вертикаль"},{"hanzi":"本","pinyin":"běn","m":"основа","hint":"木 и чёрточка внизу"},{"hanzi":"子","pinyin":"zi","m":"ребёнок, суффикс","hint":"горизонталь, крючок, горизонталь"}]}'),
  ('hsk1-14-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 桌子?","options":["книга","стул","стол"],"correct":2},{"q":"Как читается 椅子?","options":["yǐzi","yīzi","yìzi"],"correct":0},{"q":"Как сказать «три книги»?","options":["三个书","三本书","书三本"],"correct":1},{"q":"本 — счётное слово для книг.","tf":true},{"q":"Что значит 书?","options":["стол","книга","стул"],"correct":1}]}'),
  ('hsk1-14-2', 1, 'fact', '{"emoji":"🏠","title":"Человек, который остаётся","text":"Знак 住 «жить, останавливаться» складывается из 亻 «человек» и 主 «хозяин»: тот, кто остаётся на месте, как хозяин. А 做 «делать» тоже с 亻: делает человек. Оба глагола очень частые: 你住哪儿？ «Где ты живёшь?» и 你做什么？ «Что ты делаешь?»"}'),
  ('hsk1-14-2', 2, 'words', '{"title":"Жить и делать","items":[{"hanzi":"住","pinyin":"zhù","m":"жить, проживать","emoji":"🏘️","ex":{"zh":"我住在北京。","py":"Wǒ zhù zài Běijīng.","m":"Я живу в Пекине."}},{"hanzi":"做","pinyin":"zuò","m":"делать","emoji":"🛠️","ex":{"zh":"你做什么？","py":"Nǐ zuò shénme?","m":"Что ты делаешь?"}}]}'),
  ('hsk1-14-2', 3, 'theory', '{"title":"住 + 在 + место","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我住在北京。","Я живу в Пекине."],["你住在哪儿？","Где ты живёшь?"],["他住在学校后面。","Он живёт за школой."]]},{"t":"p","text":"住 часто стоит вместе с 在: 住在 + место. Вопрос про место — 哪儿: 你住在哪儿？"},{"t":"tip","text":"做 и 坐 звучат одинаково (zuò) и различаются иероглифом: 做 «делать», 坐 «сидеть»."}]}'),
  ('hsk1-14-2', 4, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","住","在","北京"],"hint":"«Я живу в Пекине.»"},{"answer":["你","住","在","哪儿"],"hint":"«Где ты живёшь?»"},{"answer":["你","做","什么"],"hint":"«Что ты делаешь?»"}]}'),
  ('hsk1-14-2', 5, 'quiz', '{"title":"Мини-тест: 住 и 做","qs":[{"q":"Как спросить «Где ты живёшь?»","options":["你在住哪儿？","你住在哪儿？","你住哪儿在？"],"correct":1},{"q":"Какой глагол значит «делать»?","options":["做","坐","住"],"correct":0},{"q":"做 и 坐 пишутся одинаково.","tf":false,"explain":"Читаются одинаково, но иероглифы разные."}]}'),
  ('hsk1-14-2', 6, 'theory', '{"title":"Что где есть: место + 有 + предмет","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["桌子上有书。","На столе есть книга."],["椅子上有猫。","На стуле есть кошка."],["家里有电视。","В доме есть телевизор."]]},{"t":"p","text":"Схема: место + 有 + что находится. Слово 上 «верх» ставится после предмета: 桌子上 «на столе»."},{"t":"tip","text":"Если книги нет, скажите 没有: 桌子上没有书."}]}'),
  ('hsk1-14-2', 7, 'game', '{"type":"listen","title":"Слушаем: 住, 做, 有","items":[{"say":"我住在北京","options":["wǒ zhù zài Běijīng","wǒ zuò zài Běijīng"],"correct":0},{"say":"你做什么","options":["nǐ zuò shénme","nǐ zhù shénme"],"correct":0},{"say":"桌子上有书","options":["zhuōzi shàng yǒu shū","zhuōzi xià yǒu shū"],"correct":0},{"say":"住","options":["zhù","zhú","zhǔ"],"correct":0},{"say":"做","options":["zuǒ","zuó","zuò"],"correct":2}]}'),
  ('hsk1-14-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["住","жить"],["做","делать"],["桌子上有书","на столе есть книга"],["你住在哪儿？","где ты живёшь?"],["你做什么？","что ты делаешь?"]]}'),
  ('hsk1-14-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: где и что","cases":[{"buggyText":"我住在去北京。","context":"«Я живу в Пекине»","options":["我在住北京。","我住北京在。","我住在北京。"],"correct":2},{"buggyText":"书桌子上有。","context":"«На столе есть книга»","options":["桌子有上书。","有桌子上书。","桌子上有书。"],"correct":2},{"buggyText":"你做什么吗？","context":"«Что ты делаешь?»","options":["你做吗什么？","你什么做？","你做什么？"],"correct":2}]}'),
  ('hsk1-14-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «На стуле есть кошка»?","options":["椅子上有猫。","椅子有上猫。","有椅子上猫。"],"correct":0},{"q":"Как читается 住?","options":["zhù","zhǔ","zhú"],"correct":0},{"q":"Что значит 桌子上?","options":["на столе","за столом","под столом"],"correct":0},{"q":"上 в 桌子上 ставится после предмета.","tf":true},{"q":"Как спросить «Что ты делаешь?»","options":["什么你做？","你做什么？","你什么做？"],"correct":1}]}'),
  ('hsk1-14-3', 1, 'fact', '{"emoji":"🐱","title":"Ключ «зверь» в слове «кошка»","text":"В знаках 狗 «собака» и 猫 «кошка» слева стоит ключ 犭 «зверь, животное». У 猫 справа 苗 «росток»: так китайцы запомнили слово. А 衣服 «одежда» состоит из 衣 «одежда» и 服 «носить»; в разговоре второй слог безударный."}'),
  ('hsk1-14-3', 2, 'words', '{"title":"Одежда и животные","items":[{"hanzi":"衣服","pinyin":"yīfu","m":"одежда","emoji":"👕","ex":{"zh":"我的衣服很漂亮。","py":"Wǒ de yīfu hěn piàoliang.","m":"Моя одежда красивая."}},{"hanzi":"狗","pinyin":"gǒu","m":"собака","emoji":"🐶","ex":{"zh":"我有狗。","py":"Wǒ yǒu gǒu.","m":"У меня есть собака."}},{"hanzi":"猫","pinyin":"māo","m":"кошка","emoji":"🐱","ex":{"zh":"我喜欢猫。","py":"Wǒ xǐhuan māo.","m":"Я люблю кошек."}}]}'),
  ('hsk1-14-3', 3, 'game', '{"type":"listen","title":"Слушаем: одежда и животные","items":[{"say":"衣服","options":["yīfu","yìfu","yǐfu"],"correct":0},{"say":"狗","options":["gǒu","gōu","gòu"],"correct":0},{"say":"猫","options":["máo","māo","mǎo"],"correct":1},{"say":"我有狗","options":["wǒ yǒu māo","wǒ yǒu gǒu"],"correct":1},{"say":"我喜欢猫","options":["wǒ xǐhuan gǒu","wǒ xǐhuan māo"],"correct":1}]}'),
  ('hsk1-14-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «gǒu» (3 тон)"}'),
  ('hsk1-14-3', 5, 'theory', '{"title":"Описание вещей и животных","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我的衣服很漂亮。","Моя одежда красивая."],["我有狗，我有猫。","У меня есть собака и кошка."],["猫在椅子上。","Кошка на стуле."]]},{"t":"p","text":"Для описания используйте схему: предмет + 很 + прилагательное: 衣服很漂亮. Для принадлежности вспомните 我的: 我的衣服."},{"t":"tip","text":"Для животных можно использовать 个 или просто говорить без счётного слова: 我有狗."}]}'),
  ('hsk1-14-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"👕","options":["衣服","狗","猫"],"correct":0},{"emoji":"🐶","options":["狗","猫","衣服"],"correct":0},{"emoji":"🐱","options":["猫","衣服","狗"],"correct":0}]}'),
  ('hsk1-14-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["衣服","одежда"],["狗","собака"],["猫","кошка"],["我有狗","у меня есть собака"],["我喜欢猫","я люблю кошек"]]}'),
  ('hsk1-14-3', 8, 'game', '{"type":"chatsim","title":"WeChat: дома","messages":[{"speaker":"Друг","text":"你有狗吗？","pinyin":"Nǐ yǒu gǒu ma?","translation":"У тебя есть собака?","options":["没有，我有猫。","不是，我狗。","没有，我是猫。"],"correct":0},{"speaker":"Друг","text":"你的猫在哪儿？","pinyin":"Nǐ de māo zài nǎr?","translation":"Где твоя кошка?","options":["猫在椅子上。","猫是椅子。","椅子在猫。"],"correct":0},{"speaker":"Друг","text":"你的衣服很漂亮！","pinyin":"Nǐ de yīfu hěn piàoliang!","translation":"Твоя одежда красивая!","options":["没关系。","谢谢！","对不起！"],"correct":1}]}'),
  ('hsk1-14-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","有","狗"],"hint":"«У меня есть собака.»"},{"answer":["猫","在","椅子","上"],"hint":"«Кошка на стуле.»"},{"answer":["我","的","衣服","很","漂亮"],"hint":"«Моя одежда красивая.»"}]}'),
  ('hsk1-14-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 猫?","options":["собака","одежда","кошка"],"correct":2},{"q":"Как читается 狗?","options":["gōu","gǒu","gòu"],"correct":1},{"q":"Какой ключ у 狗 и 猫?","options":["女","亻","犭"],"correct":2},{"q":"衣服 значит «одежда».","tf":true},{"q":"Как сказать «У меня есть собака»?","options":["我有狗。","有我狗。","我狗有。"],"correct":0}]}'),
  ('hsk1-14-4', 1, 'fact', '{"emoji":"🛋️","title":"Рассказ о комнате","text":"Анна расспрашивает Ли Мина, где он живёт и что у него дома. В диалоге встретятся 住, 有, 在, 上 и новые слова."}'),
  ('hsk1-14-4', 2, 'text', '{"title":"Что у тебя дома?","lines":[{"zh":"安娜：李明，你住在哪儿？","py":"Ānnà: Lǐ Míng, nǐ zhù zài nǎr?","m":"Анна: Ли Мин, где ты живёшь?"},{"zh":"李明：我住在学校后面。","py":"Lǐ Míng: Wǒ zhù zài xuéxiào hòumian.","m":"Ли Мин: Я живу за школой."},{"zh":"安娜：你家漂亮吗？","py":"Ānnà: Nǐ jiā piàoliang ma?","m":"Анна: У тебя дома красиво?"},{"zh":"李明：很漂亮。桌子上有书，椅子上有猫。","py":"Lǐ Míng: Hěn piàoliang. Zhuōzi shàng yǒu shū, yǐzi shàng yǒu māo.","m":"Ли Мин: Очень. На столе книга, на стуле кошка."},{"zh":"安娜：你有狗吗？","py":"Ānnà: Nǐ yǒu gǒu ma?","m":"Анна: У тебя есть собака?"},{"zh":"李明：没有，我有猫。你呢？","py":"Lǐ Míng: Méiyǒu, wǒ yǒu māo. Nǐ ne?","m":"Ли Мин: Нет, у меня кошка. А у тебя?"},{"zh":"安娜：我有狗。我喜欢狗。","py":"Ānnà: Wǒ yǒu gǒu. Wǒ xǐhuan gǒu.","m":"Анна: У меня собака. Я люблю собак."}],"qs":[{"q":"Где живёт Ли Мин?","options":["в школе","за школой","перед школой"],"correct":1},{"q":"Что лежит на столе?","options":["собака","книга","кошка"],"correct":1},{"q":"У Ли Мина есть собака.","tf":false,"explain":"У него кошка."},{"q":"Где сидит кошка?","options":["на столе","в доме","на стуле"],"correct":2},{"q":"Анна любит собак.","tf":true},{"q":"Вставьте слово: 桌子上___书。","options":["有","在","是"],"correct":0},{"q":"Как Ли Мин отвечает на вопрос о собаке?","options":["不好","不是","没有"],"correct":2}]}'),
  ('hsk1-14-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我住在学校后面","Я живу за школой"],["桌子上有书","На столе книга"],["椅子上有猫","На стуле кошка"],["我有狗","У меня собака"],["我喜欢狗","Я люблю собак"]]}'),
  ('hsk1-14-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你住在哪儿","options":["nǐ zuò zài nǎr","nǐ zhù zài nǎr"],"correct":1},{"say":"桌子上有书","options":["zhuōzi shàng yǒu shū","zhuōzi shàng yǒu māo"],"correct":0},{"say":"椅子上有猫","options":["yǐzi shàng yǒu gǒu","yǐzi shàng yǒu māo"],"correct":1},{"say":"我喜欢狗","options":["wǒ xǐhuan gǒu","wǒ xǐhuan māo"],"correct":0}]}'),
  ('hsk1-14-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: комната","cases":[{"buggyText":"我住学校后面在。","context":"«Я живу за школой»","options":["我学校后面住在。","我在住学校后面。","我住在学校后面。"],"correct":2},{"buggyText":"书有桌子上。","context":"«На столе есть книга»","options":["桌子有书上。","有书桌子上。","桌子上有书。"],"correct":2},{"buggyText":"我不有狗。","context":"«У меня нет собаки»","options":["我有不狗。","我狗不有。","我没有狗。"],"correct":2}]}'),
  ('hsk1-14-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «На стуле кошка»?","options":["猫有椅子上。","有猫椅子上。","椅子上有猫。"],"correct":2},{"q":"Как читается 学校后面?","options":["xuéxiào qiánmian","xuéxiào hòumian","xuésheng hòumian"],"correct":1},{"q":"Анна и Ли Мин любят разных животных.","tf":true}]}'),
  ('hsk1-14-5', 1, 'fact', '{"emoji":"🛏️","title":"Опишите свою комнату","text":"Сегодня вы «расставляете» вещи, описываете, где что лежит, и рассказываете о питомцах. Слова глав 1–14."}'),
