  ('hsk1-14-5', 6, 'game', '{"type":"chatsim","title":"WeChat: расскажите о доме","messages":[{"speaker":"Друг","text":"你住在哪儿？","pinyin":"Nǐ zhù zài nǎr?","translation":"Где ты живёшь?","options":["我是北京。","我住在北京。","我住北京在。"],"correct":1},{"speaker":"Друг","text":"你家有什么？","pinyin":"Nǐ jiā yǒu shénme?","translation":"Что у тебя дома?","options":["有桌子和椅子。","我是桌子。","桌子有我。"],"correct":0},{"speaker":"Друг","text":"你喜欢猫吗？","pinyin":"Nǐ xǐhuan māo ma?","translation":"Ты любишь кошек?","options":["喜欢，我有猫。","没有，我喜欢。","不是，我猫。"],"correct":0}]}'),
  ('hsk1-14-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["亻 + 主","住"],["犭 + 苗","猫"],["犭 + 句","狗"],["亻 + 故","做"]]}'),
