  ('hsk1-14-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я живу в Пекине»?","options":["我在住北京。","我住北京在。","我住在北京。"],"correct":2},{"q":"Как сказать «У меня есть кошка»?","options":["我有猫。","我猫有。","有我猫。"],"correct":0},{"q":"犭 — ключ животных.","tf":true}]}'),
