  ('hsk1-14-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"书","options":["shū","shù","shǔ"],"correct":0},{"say":"桌子","options":["zhuózi","zhuǒzi","zhuōzi"],"correct":2},{"say":"我有狗","options":["wǒ yǒu māo","wǒ yǒu gǒu"],"correct":1},{"say":"我住在北京","options":["wǒ zuò zài Běijīng","wǒ zhù zài Běijīng"],"correct":1},{"say":"桌子上有书","options":["zhuōzi shàng yǒu shū","zhuōzi xià yǒu shū"],"correct":0},{"say":"衣服","options":["yīfu","yìfu","yǐfu"],"correct":0}]}'),
