  ('hsk1-14-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «три книги»?","options":["三本书","三个书","书三本"],"correct":0},{"q":"Как сказать «На столе есть книга»?","options":["书桌子上有。","桌子上有书。","有桌子上书。"],"correct":1},{"q":"Как сказать «Я живу в Пекине»?","options":["我住北京在。","我在住北京。","我住在北京。"],"correct":2},{"q":"做 и 坐 читаются одинаково.","tf":true},{"q":"Какой ключ у 狗?","options":["女","犭","亻"],"correct":1},{"q":"Как читается 椅子?","options":["yīzi","yǐzi","yìzi"],"correct":1},{"q":"本 — счётное слово для книг.","tf":true},{"q":"Как спросить «Что ты делаешь?»","options":["你做什么？","你什么做？","做你什么？"],"correct":0},{"q":"Как сказать «У меня нет собаки»?","options":["我没有狗。","我有不狗。","我不有狗。"],"correct":0},{"q":"Что значит 衣服?","options":["стул","собака","одежда"],"correct":2}]}'),
  ('hsk1-14-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","有","一","本","书"],"hint":"«У меня есть книга.»"},{"answer":["桌子","上","有","书"],"hint":"«На столе есть книга.»"},{"answer":["我","住","在","北京"],"hint":"«Я живу в Пекине.»"},{"answer":["我","喜欢","猫"],"hint":"«Я люблю кошек.»"}]}'),
  ('hsk1-14-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我住北京在。","context":"«Я живу в Пекине»","options":["我住在北京。","我在住北京。","我北京住在。"],"correct":0},{"buggyText":"书桌子上有。","context":"«На столе есть книга»","options":["有书桌子上。","桌子有书上。","桌子上有书。"],"correct":2},{"buggyText":"我不有猫。","context":"«У меня нет кошки»","options":["我没有猫。","我有不猫。","我猫不有。"],"correct":0}]}'),
  ('hsk1-14-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你住在哪儿？","pinyin":"Nǐ zhù zài nǎr?","translation":"Где ты живёшь?","options":["我住学校后面在。","我在住学校。","我住在学校后面。"],"correct":2},{"speaker":"Друг","text":"你有猫吗？","pinyin":"Nǐ yǒu māo ma?","translation":"У тебя есть кошка?","options":["没有，我是狗。","不是，我有。","没有，我有狗。"],"correct":2}]}'),
  ('hsk1-14-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"书","pinyin":"shū","m":"книга","hint":"ломаная и вертикаль"},{"hanzi":"住","pinyin":"zhù","m":"жить","hint":"亻 + 主"},{"hanzi":"猫","pinyin":"māo","m":"кошка","hint":"犭 + 苗"}]}'),
  ('hsk1-14-6', 10, 'recall', '{"words":[{"hanzi":"书","pinyin":"shū","m":"книга"},{"hanzi":"本","pinyin":"běn","m":"том"},{"hanzi":"桌子","pinyin":"zhuōzi","m":"стол"},{"hanzi":"椅子","pinyin":"yǐzi","m":"стул"},{"hanzi":"衣服","pinyin":"yīfu","m":"одежда"},{"hanzi":"狗","pinyin":"gǒu","m":"собака"},{"hanzi":"猫","pinyin":"māo","m":"кошка"},{"hanzi":"住","pinyin":"zhù","m":"жить"},{"hanzi":"做","pinyin":"zuò","m":"делать"}],"tf":[{"zh":"我住北京在。","py":"wǒ zhù Běijīng zài.","m":"Я живу в Пекине.","ok":false,"explain":"Правильно: 我住在北京."},{"zh":"桌子上有书。","py":"zhuōzi shàng yǒu shū.","m":"На столе есть книга.","ok":true}],"sentences":[{"zh":"我住在北京。","tokens":["我","住","在","北京"],"m":"Я живу в Пекине."},{"zh":"桌子上有书。","tokens":["桌子","上","有","书"],"m":"На столе есть книга."},{"zh":"我有一本书。","tokens":["我","有","一","本","书"],"m":"У меня есть книга."}]}'),
  ('hsk1-15-1', 1, 'fact', '{"emoji":"🏥","title":"Врач — «человек медицины»","text":"Слово 医生 буквально «медицина + человек» (生 «жить, человек» вы уже видели в 先生 и 学生). А 医院 — «медицина + двор»: большое учреждение с общим двором. Слово 院 встречается и в других названиях: 医院 «больница», а в университете — «факультет»."}'),
  ('hsk1-15-1', 2, 'words', '{"title":"Врач и больница","items":[{"hanzi":"医生","pinyin":"yīshēng","m":"врач","emoji":"👩‍⚕️","ex":{"zh":"我爸爸是医生。","py":"Wǒ bàba shì yīshēng.","m":"Мой папа врач."}},{"hanzi":"医院","pinyin":"yīyuàn","m":"больница","emoji":"🏥","ex":{"zh":"医院很大。","py":"Yīyuàn hěn dà.","m":"Больница большая."}}]}'),
  ('hsk1-15-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"👩‍⚕️","options":["医生","学生","医院"],"correct":0},{"emoji":"🏥","options":["医院","商店","学校"],"correct":0},{"emoji":"🎓","options":["老师","医生","学生"],"correct":2}]}'),
  ('hsk1-15-1', 4, 'theory', '{"title":"Профессия и место работы","blocks":[{"t":"table","head":["Слово","Что это","Пример"],"rows":[["医生","профессия","我爸爸是医生。"],["医院","место","他在医院工作。"],["老师","профессия","王芳是老师。"],["学生","статус","我是学生。"]]},{"t":"p","text":"Схема: кто + 是 + профессия: 他是医生. Место работы: 在 + место + 工作: 他在医院工作. 工作 вы выучили в главе 8."},{"t":"tip","text":"В названиях профессий последний слог часто безударный: yīshēng, xiānsheng, xuésheng."}]}'),
  ('hsk1-15-1', 5, 'quiz', '{"title":"Мини-тест: профессия","qs":[{"q":"Как сказать «Он врач»?","options":["他在医生。","他医院。","他是医生。"],"correct":2},{"q":"医院 — это «врач».","tf":false,"explain":"医院 — больница, 医生 — врач."},{"q":"Как сказать «Он работает в больнице»?","options":["他医院在工作。","他工作在医生。","他在医院工作。"],"correct":2}]}'),
  ('hsk1-15-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["医生","врач"],["医院","больница"],["老师","учитель"],["学生","студент"],["在医院工作","работать в больнице"]]}'),
  ('hsk1-15-1', 7, 'game', '{"type":"listen","title":"Слушаем: профессии","items":[{"say":"医生","options":["yīshēng","yìshēng","yǐshēng"],"correct":0},{"say":"医院","options":["yīyuán","yīyuàn","yǐyuàn"],"correct":1},{"say":"我爸爸是医生","options":["wǒ bàba shì yīshēng","wǒ bàba shì lǎoshī"],"correct":0},{"say":"他在医院工作","options":["tā zài xuéxiào gōngzuò","tā zài yīyuàn gōngzuò"],"correct":1}]}'),
  ('hsk1-15-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","爸爸","是","医生"],"hint":"«Мой папа врач.»"},{"answer":["他","在","医院","工作"],"hint":"«Он работает в больнице.»"},{"answer":["医院","很","大"],"hint":"«Больница большая.»"}]}'),
  ('hsk1-15-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"医","pinyin":"yī","m":"медицина","hint":"рамка 匚 с стрелой 矢 внутри"},{"hanzi":"院","pinyin":"yuàn","m":"двор, учреждение","hint":"слева 阝, справа 完"},{"hanzi":"生","pinyin":"shēng","m":"жить, рождаться","hint":"откидная, горизонтали, вертикаль"}]}'),
  ('hsk1-15-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 医院?","options":["больница","школа","врач"],"correct":0},{"q":"Как читается 医生?","options":["yǐshēng","yīshēng","yìshēng"],"correct":1},{"q":"Как сказать «Мой папа врач»?","options":["我医生爸爸。","我爸爸医生。","我爸爸是医生。"],"correct":2},{"q":"医院 состоит из «медицины» и «двора».","tf":true},{"q":"Что значит 医生 буквально?","options":["человек медицины","двор медицины","дом врача"],"correct":0}]}'),
  ('hsk1-15-2', 1, 'fact', '{"emoji":"❓","title":"Все вопросительные слова в одной таблице","text":"Вы уже знаете много вопросительных слов: 什么, 哪儿, 几, 多少, 怎么, 怎么样. Теперь добавляем 谁 «кто» и собираем всё вместе. Главное правило не изменилось: вопросительное слово встаёт на место ответа, и 吗 не нужен. А 些 «несколько» помогает говорить «эти» и «те» во множественном числе."}'),
  ('hsk1-15-2', 2, 'words', '{"title":"Кто и несколько","items":[{"hanzi":"谁","pinyin":"shéi","m":"кто","emoji":"🙋","ex":{"zh":"谁是医生？","py":"Shéi shì yīshēng?","m":"Кто врач?"}},{"hanzi":"些","pinyin":"xiē","m":"несколько, некоторые","emoji":"🔢","ex":{"zh":"这些书","py":"zhèxiē shū","m":"эти книги"}}]}'),
  ('hsk1-15-2', 3, 'theory', '{"title":"Таблица вопросительных слов","blocks":[{"t":"table","head":["Слово","Спрашивает о","Пример"],"rows":[["谁","человеке","谁是医生？"],["什么","предмете","你吃什么？"],["哪儿","месте","你在哪儿？"],["几","числе до 10","你几岁？"],["多少","большом числе, цене","多少钱？"],["怎么","способе","怎么读？"],["怎么样","качестве","天气怎么样？"]]},{"t":"p","text":"Для каждого вопросительного слова не нужно 吗. Оно само задаёт вопрос."},{"t":"tip","text":"Если на вопрос можно ответить просто «да» или «нет», добавляйте 吗; если нужно назвать что-то — вопросительное слово."}]}'),
  ('hsk1-15-2', 4, 'quiz', '{"title":"Мини-тест: вопросы","qs":[{"q":"Как спросить «Кто врач?»","options":["谁是医生？","是谁医生？","谁吗是医生？"],"correct":0},{"q":"К вопросу со словом 谁 добавляют 吗.","tf":false,"explain":"Вопросительное слово заменяет 吗."},{"q":"Каким словом спрашивают о месте?","options":["哪儿","谁","几"],"correct":0}]}'),
  ('hsk1-15-2', 5, 'theory', '{"title":"这些, 那些, 一些","blocks":[{"t":"table","head":["Слово","Смысл","Пример"],"rows":[["这些","эти","这些书很大。"],["那些","те","那些狗很小。"],["一些","несколько","我有一些书。"]]},{"t":"p","text":"Для множественного числа с 这 и 那 нужно слово 些, а не 们. 们 используют только для людей: 我们, 你们, 同学们."},{"t":"ex","zh":"这些书是我的。","py":"Zhèxiē shū shì wǒ de.","m":"Эти книги мои.","say":"这些书是我的"}]}'),
  ('hsk1-15-2', 6, 'game', '{"type":"listen","title":"Слушаем: кто и «эти»","items":[{"say":"谁","options":["shēi","shéi","shěi"],"correct":1},{"say":"些","options":["xiē","xié","xiè"],"correct":0},{"say":"这些书","options":["zhè běn shū","zhèxiē shū"],"correct":1},{"say":"谁是医生","options":["shéi shì lǎoshī","shéi shì yīshēng"],"correct":1},{"say":"我有一些书","options":["wǒ yǒu yí gè shū","wǒ yǒu yìxiē shū"],"correct":1}]}'),
  ('hsk1-15-2', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["谁","кто"],["些","частица множественного числа"],["这些","эти"],["那些","те"],["一些","несколько"]]}'),
  ('hsk1-15-2', 8, 'game', '{"type":"bughunt","title":"Китайский детектив: 谁 и 些","cases":[{"buggyText":"谁是医生吗？","context":"«Кто врач?»","options":["是谁医生吗？","谁是医生？","医生是谁吗？"],"correct":1},{"buggyText":"这些们书很大。","context":"«Эти книги большие»","options":["这们书很大。","这些书很大。","这些书们很大。"],"correct":1},{"buggyText":"我有些一书。","context":"«У меня есть несколько книг»","options":["我一些有书。","我有一书些。","我有一些书。"],"correct":2}]}'),
  ('hsk1-15-2', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["谁","是","医生"],"hint":"«Кто врач?»"},{"answer":["这些","书","很","大"],"hint":"«Эти книги большие.»"},{"answer":["我","有","一些","朋友"],"hint":"«У меня есть несколько друзей.»"}]}'),
  ('hsk1-15-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «эти книги»?","options":["这们书","这些书","这书些"],"correct":1},{"q":"Как читается 谁?","options":["shěi","shéi","shēi"],"correct":1},{"q":"们 можно прибавить к 书.","tf":false},{"q":"Что значит 一些?","options":["один","много","несколько"],"correct":2},{"q":"Каким словом спрашивают о человеке?","options":["几","什么","谁"],"correct":2}]}'),
  ('hsk1-15-3', 1, 'fact', '{"emoji":"🕵️","title":"Задача аудиошпиона","text":"Вы прошли 14 глав и знаете все правила: 3+3 → 2+3, 不 → bú перед 4 тоном, 一 → yí, yì, безударные слоги. Сегодня вы ловите «фальшивое» звучание и выбираете правильное. Это повторение перед финальным экзаменом всего уровня."}'),
  ('hsk1-15-3', 2, 'game', '{"type":"listen","title":"Аудиошпион: найдите правильное звучание","items":[{"say":"你好","options":["ní hǎo","nǐ hǎo"],"correct":0,"explain":"Два третьих тона: первый становится вторым."},{"say":"不客气","options":["bú kèqi","bū kèqi","bù kèqi"],"correct":0},{"say":"不好","options":["bú hǎo","bù hǎo"],"correct":1},{"say":"一个人","options":["yì gè rén","yí gè rén","yī gè rén"],"correct":1},{"say":"一点儿","options":["yìdiǎnr","yídiǎnr","yīdiǎnr"],"correct":0},{"say":"谢谢","options":["xiéxie","xièxie","xièxiè"],"correct":1}]}'),
  ('hsk1-15-3', 3, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: «nǐ hǎo» с сандхи"}'),
  ('hsk1-15-3', 4, 'theory', '{"title":"Справочник: четыре главных сандхи","blocks":[{"t":"table","head":["Правило","Пример","Как звучит"],"rows":[["3 + 3","你好 nǐ hǎo","ní hǎo"],["不 + 4 тон","不去 bú qù","bú qù"],["一 + 4 тон","一个 yí gè","yí gè"],["一 + 1/2/3 тон","一杯 yì bēi","yì bēi"]]},{"t":"p","text":"Нейтральный тон: 吗, 呢, 了, 的, 子, 们 звучат коротко и безударно. Пишутся они без тонового знака."},{"t":"tip","text":"Знаки на письме не меняются: 不, 一, 你 остаются теми же. Меняется только произношение."}]}'),
  ('hsk1-15-3', 5, 'game', '{"type":"match","title":"Написание и звучание","pairs":[["你好","ní hǎo"],["不去","bú qù"],["一个","yí gè"],["一杯","yì bēi"],["谢谢","xièxie"]]}'),
  ('hsk1-15-3', 6, 'game', '{"type":"listen","title":"Аудиошпион: ещё пять случаев","items":[{"say":"不吃","options":["bù chī","bú chī"],"correct":0,"explain":"吃 в первом тоне, 不 остаётся bù."},{"say":"不是","options":["bù shì","bú shì"],"correct":1},{"say":"我有","options":["wó yǒu","wǒ yǒu"],"correct":0},{"say":"很好","options":["hěn hǎo","hén hǎo"],"correct":1},{"say":"桌子","options":["zhuōzi","zhuōzǐ"],"correct":0}]}'),
  ('hsk1-15-3', 7, 'game', '{"type":"bughunt","title":"Китайский детектив: ошибки в произношении","cases":[{"buggyText":"不去 читается bù qù","context":"Правило 不 + 4 тон","options":["bǔ qù","bú qù","bù qù"],"correct":1,"explain":"Перед четвёртым тоном 不 → bú."},{"buggyText":"你好 читается nǐ hǎo","context":"В быстрой речи звучит","options":["nì hǎo","ní hǎo","nǐ hǎo"],"correct":1},{"buggyText":"一个 читается yī gè","context":"Перед 个 (4 тон)","options":["yī gè","yí gè","yì gè"],"correct":1}]}'),
  ('hsk1-15-3', 8, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 不对 (对 — 4 тон)?","options":["bù duì","bǔ duì","bú duì"],"correct":2},{"q":"Как читается 一杯?","options":["yì bēi","yí bēi","yī bēi"],"correct":0},{"q":"На письме 不 меняется на другой иероглиф перед 4 тоном.","tf":false},{"q":"Какой тон у 吗?","options":["первый","четвёртый","нейтральный"],"correct":2},{"q":"Как читается 你好 в живой речи?","options":["nǐ hǎo","ní hǎo","nì hǎo"],"correct":1}]}'),
  ('hsk1-15-4', 1, 'fact', '{"emoji":"🩺","title":"Профессия отца","text":"Анна узнаёт, кем работает папа Ли Мина. Диалог собран из слов нескольких глав: профессии, место, время, расстояние."}'),
  ('hsk1-15-4', 2, 'text', '{"title":"Папа Ли Мина","lines":[{"zh":"安娜：李明，谁是医生？","py":"Ānnà: Lǐ Míng, shéi shì yīshēng?","m":"Анна: Ли Мин, кто врач?"},{"zh":"李明：我爸爸是医生。","py":"Lǐ Míng: Wǒ bàba shì yīshēng.","m":"Ли Мин: Мой папа врач."},{"zh":"安娜：他在哪儿工作？","py":"Ānnà: Tā zài nǎr gōngzuò?","m":"Анна: Где он работает?"},{"zh":"李明：他在医院工作。医院在火车站前面。","py":"Lǐ Míng: Tā zài yīyuàn gōngzuò. Yīyuàn zài huǒchēzhàn qiánmian.","m":"Ли Мин: Он работает в больнице. Больница перед вокзалом."},{"zh":"安娜：医院大吗？","py":"Ānnà: Yīyuàn dà ma?","m":"Анна: Больница большая?"},{"zh":"李明：很大，医生很多。","py":"Lǐ Míng: Hěn dà, yīshēng hěn duō.","m":"Ли Мин: Очень большая, врачей много."},{"zh":"安娜：你爸爸几点回家？","py":"Ānnà: Nǐ bàba jǐ diǎn huí jiā?","m":"Анна: Во сколько твой папа возвращается домой?"},{"zh":"李明：他下午五点回家。","py":"Lǐ Míng: Tā xiàwǔ wǔ diǎn huí jiā.","m":"Ли Мин: В пять часов дня."}],"qs":[{"q":"Кто врач?","options":["папа Анны","папа Ли Мина","Ли Мин"],"correct":1},{"q":"Где работает папа Ли Мина?","options":["в школе","в магазине","в больнице"],"correct":2},{"q":"Больница находится за вокзалом.","tf":false,"explain":"Больница перед вокзалом."},{"q":"Во сколько папа приходит домой?","options":["в десять вечера","в три дня","в пять дня"],"correct":2},{"q":"В больнице много врачей.","tf":true},{"q":"Вставьте слово: 他在医院___。","options":["回家","吃饭","工作"],"correct":2},{"q":"Что значит 谁是医生？","options":["что делает врач?","кто врач?","где врач?"],"correct":1}]}'),
  ('hsk1-15-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["谁是医生？","Кто врач?"],["他在医院工作","Он работает в больнице"],["医院在火车站前面","Больница перед вокзалом"],["医生很多","Врачей много"],["他下午五点回家","Он возвращается в пять дня"]]}'),
  ('hsk1-15-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"谁是医生","options":["shéi shì lǎoshī","shéi shì yīshēng"],"correct":1},{"say":"他在医院工作","options":["tā zài yīyuàn shuìjiào","tā zài yīyuàn gōngzuò"],"correct":1},{"say":"医院在火车站前面","options":["yīyuàn zài huǒchēzhàn qiánmian","yīyuàn zài huǒchēzhàn hòumian"],"correct":0},{"say":"他下午五点回家","options":["tā xiàwǔ wǔ diǎn huí jiā","tā shàngwǔ wǔ diǎn huí jiā"],"correct":0}]}'),
  ('hsk1-15-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: профессия","cases":[{"buggyText":"他医院工作在。","context":"«Он работает в больнице»","options":["在他医院工作。","他工作医院在。","他在医院工作。"],"correct":2},{"buggyText":"他五点下午回家。","context":"«Он возвращается в пять дня»","options":["他下午五点回家。","他五点回家下午。","他回家下午五点。"],"correct":0},{"buggyText":"谁是医生吗？","context":"«Кто врач?»","options":["谁是医生？","医生是谁吗？","是谁医生吗？"],"correct":0}]}'),
